/* questions.js — merged, validated bank. Source of truth: drivers-guide-2026.md */
window.QUESTIONS = [{"id":"ch1-001","chapter":1,"category":"gdl","question":"At what age may a person first apply for a Class 7 learner’s licence in Alberta?","options":["12 years of age or older","14 years of age or older","15 years of age or older","16 years of age or older"],"answer":1,"explanation":"To obtain a Class 7 learner’s licence you must be 14 years of age or older. You must also pass a vision screening and a knowledge test.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-002","chapter":1,"category":"gdl","question":"In addition to passing a knowledge test on the rules of the road, what must every Class 7 applicant do?","options":["Pass an Alberta Class 5 road test","Complete an approved driver training course","Pass a vision screening","Provide proof of a clean 12-month driving record"],"answer":2,"explanation":"A Class 7 applicant must pass a vision screening and a knowledge test, and have parental consent if under 18 years of age. There is no road test for a Class 7.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-003","chapter":1,"category":"gdl","question":"How long must you hold a Class 7 learner’s licence before you can become a probationary driver?","options":["At least three months","At least one year","At least 18 months","At least two years"],"answer":1,"explanation":"The guide states you must hold a learner’s licence (Class 7) for at least one year. A suspension of your driving privileges extends this time.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-004","chapter":1,"category":"gdl","question":"While driving on a Class 7 learner’s licence, you must be accompanied by:","options":["Any licensed driver over 16 who is seated in the back seat","A Class 5-GDL probationary driver who is 18 years of age or older","A fully-licensed (non-GDL) driver who is 18 years of age or older and is seated next to you","A parent or guardian seated anywhere in the vehicle"],"answer":2,"explanation":"Learner’s conditions require a fully-licensed (non-GDL) driver, 18 years of age or older, seated next to you. A GDL probationary driver cannot supervise a learner.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-005","chapter":1,"category":"gdl","question":"A Class 7 learner is not permitted to drive between which hours?","options":["10 p.m. and 6 a.m.","11 p.m. and 6 a.m.","Midnight and 5 a.m.","1 a.m. and 5 a.m."],"answer":2,"explanation":"You are not permitted to drive from midnight to 5 a.m. while holding a learner’s licence.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-006","chapter":1,"category":"gdl","question":"A Class 7 learner will be suspended if they accumulate:","options":["four or more demerit points","six or more demerit points","fifteen or more demerit points","eight or more demerit points"],"answer":3,"explanation":"The guide states you will be suspended if you accumulate eight or more demerit points as a Class 7 learner.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-007","chapter":1,"category":"gdl","question":"When driving (or riding a motorcycle) on a Class 7 learner’s licence, your alcohol and drug level must be:","options":["Below the 0.05 legal limit","Below 0.08","Whatever your supervising driver’s level is","Zero alcohol and/or drug level"],"answer":3,"explanation":"You must have a zero alcohol and/or drug level when driving, or when riding a motorcycle, as a Class 7 learner.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-008","chapter":1,"category":"gdl","question":"Passing the Alberta Class 5 road test allows a learner to move to which licence?","options":["A full Class 5 (non-GDL) licence","A Class 5-GDL probationary licence","A Class 4 licence","A Class 6 motorcycle licence"],"answer":1,"explanation":"Passing the Class 5 road test allows drivers to move from a Class 7 learner’s licence to a Class 5-GDL driver’s licence. Only after the probationary stage do you exit GDL to a full Class 5.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-009","chapter":1,"category":"gdl","question":"What is the minimum licensing age for a Class 5-GDL (probationary) licence?","options":["14 years of age","15 years of age","16 years of age","18 years of age"],"answer":2,"explanation":"To become a probationary driver you must hold your Class 7 for a year and be 16 years of age or older, then pass the Alberta Class 5 road test.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-010","chapter":1,"category":"gdl","question":"As a Class 5-GDL probationary driver, you must remain in the probationary stage for:","options":["A minimum of one year","A minimum of three years","A minimum of two years","Until you reach 21 years of age"],"answer":2,"explanation":"Probationary conditions require you to be a probationary driver for a minimum of two years.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-011","chapter":1,"category":"gdl","question":"A driver receives a suspension of their driving privileges while holding a Class 7 learner’s licence. What happens to the one-year learner holding period?","options":["It is shortened by one month for each month suspended","It stays exactly the same","The time is extended","The holding period is waived if they retake the knowledge test"],"answer":2,"explanation":"You must hold your Class 7 learner’s licence for a year, and this time will be extended if you receive a suspension of your driving privileges.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-012","chapter":1,"category":"gdl","question":"While in the GDL probationary (Class 5-GDL) stage, you are not able to:","options":["Re-class your licence to a commercial driver’s licence (Class 1, 2, 3, or 4)","Operate a vehicle or vehicle-trailer combination a Class 5 holder may operate","Renew your licence","Drive outside city limits"],"answer":0,"explanation":"Probationary drivers are not able to re-class to a commercial driver’s licence (Class 1, 2, 3, or 4). They also cannot serve as a supervising driver to a learner.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-013","chapter":1,"category":"gdl","question":"You can reduce your probationary stage by up to six months by:","options":["Paying a reduced-probation fee at a registry agent","Successfully completing an approved driver training course resulting in a condition code (U) being added to your driving record","Driving 10,000 kilometres without a violation","Passing the Class 6 motorcycle road test"],"answer":1,"explanation":"The probationary stage can be reduced by up to six months with an approved driver training course resulting in a condition code (U) on your driving record, provided all other eligibility requirements are met.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-014","chapter":1,"category":"gdl","question":"To exit the GDL program, besides being at least 18 and completing a minimum of two years in the probationary stage, you must be:","options":["Free of suspensions or traffic violations within the last 12 months of the probationary stage","Free of parking violations for five years","A graduate of an approved high school program","Employed full-time for at least one year"],"answer":0,"explanation":"To exit GDL you must be free of suspensions or traffic violations within the last 12 months of the probationary stage, including zero alcohol and/or drug level when driving.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-015","chapter":1,"category":"gdl","question":"A GDL licence holder is suspended at eight or more demerit points. Exiting the GDL program increases the demerits you are allowed — a fully licensed (non-GDL) driver is automatically suspended at:","options":["eight or more demerit points","twelve or more demerit points","fifteen or more demerit points","twenty or more demerit points"],"answer":2,"explanation":"Upon exiting the GDL program you increase the number of demerits you are allowed, and you also remove the zero alcohol and drug tolerance condition. Under the guide, 15 or more demerit points within a two-year period results in automatic suspension.","source":{"chapter":1,"section":"Graduated driver licensing","anchor":"#graduated-driver-licensing","page":"10"}},{"id":"ch1-016","chapter":1,"category":"gdl","question":"Where can you take the knowledge test for your learner’s licence?","options":["At any police station","At most Alberta registry agent offices","Only at the Motor Vehicles Branch in Edmonton","At your school’s administration office"],"answer":1,"explanation":"You can take your knowledge test at most Alberta registry agent offices. The test is based on questions taken from the driver’s guide.","source":{"chapter":1,"section":"Knowledge test","anchor":"#knowledge-test","page":"12"}},{"id":"ch1-017","chapter":1,"category":"gdl","question":"The Class 7 knowledge test is:","options":["A written essay exam graded by an examiner","A series of multiple choice questions done on a computer","An oral test given over the phone","A driving simulation exercise"],"answer":1,"explanation":"The test is a series of multiple choice questions and you must score a certain number of correct responses to pass. You will do the test on a computer.","source":{"chapter":1,"section":"Knowledge test","anchor":"#knowledge-test","page":"12"}},{"id":"ch1-018","chapter":1,"category":"gdl","question":"There is a fee for each knowledge test you take, and you can take:","options":["Two tests per day","Unlimited tests per day for one fee","Three tests per week","Only one test per day"],"answer":3,"explanation":"There is a fee for each knowledge test that you take, and you can take only one test per day.","source":{"chapter":1,"section":"Knowledge test","anchor":"#knowledge-test","page":"12"}},{"id":"ch1-019","chapter":1,"category":"gdl","question":"The Class 7 electronic driver knowledge test is available in how many languages?","options":["10","15","20","25"],"answer":3,"explanation":"The Class 7 electronic driver knowledge test is available in 25 languages, including Amharic, Arabic, Chinese, Cree, English, French, German, Hindi, Korean, Spanish, Tagalog and Ukrainian.","source":{"chapter":1,"section":"Knowledge test","anchor":"#knowledge-test","page":"12"}},{"id":"ch1-020","chapter":1,"category":"gdl","question":"If you do not meet the vision standards at your assessment, you will be:","options":["Permanently refused an Alberta licence","Referred to an optometrist or an ophthalmologist to have a Vision Referral form completed","Issued a daylight-driving-only licence automatically","Allowed to drive until your next renewal"],"answer":1,"explanation":"A vision assessment is required before you are eligible for an Alberta licence, and failing to meet the standards leads to a referral to an optometrist or ophthalmologist for a Vision Referral form. Bring corrective glasses or contact lenses with you to the assessment.","source":{"chapter":1,"section":"Vision requirements","anchor":"#vision-requirements","page":"13"}},{"id":"ch1-021","chapter":1,"category":"gdl","question":"Approximately how long is the Class 5 road test?","options":["20 minutes","30 minutes","45 minutes","90 minutes"],"answer":2,"explanation":"The Class 5 road test is approximately 45 minutes, including the driver examiner’s pre-test instructions and the summary of your results.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-022","chapter":1,"category":"gdl","question":"After passing the Class 5 road test, you must:","options":["Keep the road test permit and use it as your licence","Take the road test permit you purchased to a registry agent to ensure your driver’s licence is updated","Wait for the examiner to mail your new licence","Register the permit with your insurance company"],"answer":1,"explanation":"When you pass the Class 5 road test you must take the road test permit to a registry agent to have your licence updated. The road test permit is not a driver’s licence.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-023","chapter":1,"category":"gdl","question":"Which of the following is required for the vehicle used on your Class 5 road test?","options":["A valid licence plate and insurance","A dash camera facing the examiner","A full tank purchased at the test centre","A factory-installed navigation system"],"answer":1,"explanation":"The vehicle must be in acceptable working condition, including a valid licence plate and insurance, headlights, brake and signal lights, horn, speedometer, brakes, mirrors and enough fuel for the road test.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-024","chapter":1,"category":"gdl","question":"Your road test will include perpendicular, uphill or downhill parking, and parallel parking — with one exception. Which maneuver are drivers over 65 NOT required to complete?","options":["Perpendicular parking","Uphill parking","Downhill parking","Parallel parking"],"answer":3,"explanation":"The road test includes perpendicular, uphill, or downhill parking, and parallel parking; drivers over 65 are not required to complete a parallel park.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-025","chapter":1,"category":"gdl","question":"Regardless of point totals, which of the following results in automatic failure of the road test?","options":["Failing to check your mirrors before a single turn","Failing to stop completely before proceeding through an intersection controlled by a stop sign","Parking with the wheels slightly turned","Keeping a three-second following distance"],"answer":1,"explanation":"Regardless of point totals, failing to stop completely before proceeding through an intersection controlled by a stop sign — or before turning right on a red light — is an automatic failure.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-026","chapter":1,"category":"gdl","question":"Which of these actions also means automatic failure of the road test?","options":["Parking more than 50 centimetres from the curb","Choosing the far lane when turning right","Climbing over the curb while parking, or being unable to park legally in three attempts","Driving with the radio on"],"answer":2,"explanation":"Climbing over the curb while parking, or being unable to park legally in three attempts, results in automatic failure regardless of point totals.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-027","chapter":1,"category":"gdl","question":"At an uncontrolled intersection during your road test, failing to slow or observe adequately is an automatic failure — you must be prepared to yield to:","options":["Drivers on your left","Drivers to your right","Larger commercial vehicles","Only pedestrians"],"answer":1,"explanation":"Failing to slow or observe adequately at uncontrolled intersections is an automatic failure; you must be prepared to yield to drivers to your right.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-028","chapter":1,"category":"gdl","question":"On a road test, drivers earn points for the mistakes they make. What happens if the maximum points for errors are exceeded?","options":["The driver must repeat only the parking portion","The driver receives a letter of caution instead","The driver fails the test","Two points are removed from the personal driving record"],"answer":2,"explanation":"Drivers earn points for mistakes made during a road test, with a set limit for each test; if the maximum points for errors are exceeded, the driver fails the test.","source":{"chapter":1,"section":"Class 5 road test","anchor":"#class-5-road-test","page":"13"}},{"id":"ch1-029","chapter":1,"category":"gdl","question":"To learn to ride a motorcycle while holding a Class 7 learner’s licence, you must be:","options":["14 years of age or older, with any licensed supervisor on the street beside you","16 years of age or older, learning with a supervisor who holds a Class 6 non-GDL licence","18 years of age or older, with a Class 5 supervisor in a following car","Any age, as long as you wear a helmet"],"answer":1,"explanation":"A Class 7 holder may operate a motorcycle only if 16 years of age or older when learning, with a supervisor who holds a Class 6 non-GDL licence.","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-030","chapter":1,"category":"gdl","question":"While learning and accompanied as required, the holder of a Class 7 licence may operate:","options":["A taxi carrying passengers for hire","A moped","A vehicle equipped with air brakes","A bus with a seating capacity of more than 15"],"answer":1,"explanation":"A Class 7 holder may operate the vehicle or vehicle-trailer combinations a Class 5 holder may operate, a motorcycle (at 16 or older with a Class 6 supervising driver), and a moped.","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-031","chapter":1,"category":"gdl","question":"Which of the following may a full Class 5 driver operate?","options":["A recreational vehicle with not more than three axles","Any motor vehicle regardless of the number of axles","A motorcycle whenever they wish","A vehicle with a seating capacity of more than 15 while transporting passengers"],"answer":0,"explanation":"A Class 5 licence covers a vehicle with only two axles, a recreational vehicle with not more than three axles, and a moped, among other light vehicles.","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-032","chapter":1,"category":"gdl","question":"The holder of a Class 5 driver’s licence shall NOT operate:","options":["A two-axle vehicle","A vehicle transporting passengers for hire","A moped","A recreational vehicle with three axles"],"answer":1,"explanation":"A Class 5 holder shall not operate a vehicle transporting passengers for hire; carrying paying passengers requires the appropriate (Class 4) licence.","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-033","chapter":1,"category":"gdl","question":"A Class 5 driver shall not operate a vehicle with a seating capacity of more than ___ while that vehicle is transporting any person other than the driver.","options":["8","12","15","20"],"answer":2,"explanation":"The Class 5 limit is not more than 15 seats: a vehicle with a seating capacity of more than 15 cannot transport any person other than the driver under a Class 5 licence.","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-034","chapter":1,"category":"gdl","question":"A Class 5 driver shall not operate a vehicle equipped with air brakes unless:","options":["The vehicle travels below 80 km/h","The supervisor has an air brake endorsement","The trip is shorter than 50 kilometres","The vehicle also has cable-operated brakes"],"answer":1,"explanation":"Vehicles with an air-only, or combined air and hydraulic, braking system are beyond Class 5 unless the supervisor holds an air brake endorsement (Q).","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-035","chapter":1,"category":"gdl","question":"A Class 5 holder may learn in a vehicle included under Classes 1, 2, 3, and 4 provided the learner:","options":["is at least 16 and accompanied by any adult","is at least 18 and has a supervisor with a valid driver’s licence for the type of vehicle","is at least 14 and has written parental consent","has held any licence for at least six months"],"answer":1,"explanation":"For learning in Class 1, 2, 3, and 4 vehicles, the learner must be at least 18 years of age and have a supervisor with a valid driver’s licence for the type of vehicle.","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-036","chapter":1,"category":"gdl","question":"The holder of a Class 5-GDL driver’s licence may operate:","options":["Only vehicles with an automatic transmission","Only a moped","Vehicles only during daylight hours","A vehicle or vehicle-trailer combination that the holder of a Class 5 driver’s licence may operate"],"answer":3,"explanation":"A Class 5-GDL holder may operate the same vehicle or vehicle-trailer combinations as a Class 5 holder; the minimum licensing age for Class 5-GDL is 16 years.","source":{"chapter":1,"section":"Types of vehicles for licence class","anchor":"#types-of-vehicles-for-licence-class","page":"14"}},{"id":"ch1-037","chapter":1,"category":"gdl","question":"A Class 4 driver’s licence is required when:","options":["You drive your own car to work to save on fuel","The vehicle owner or operator, or the operator’s employer, is being paid for the service that the vehicle is being used to provide","You lend your car to a friend for the weekend","You drive on any rural highway"],"answer":1,"explanation":"A Class 4 licence is required whenever the vehicle owner or operator, or the operator’s employer, is being paid for the service the vehicle is used to provide.","source":{"chapter":1,"section":"For hire, driver’s licence requirements","anchor":"#for-hire-drivers-licence-requirements","page":"16"}},{"id":"ch1-038","chapter":1,"category":"gdl","question":"Driving a private passenger vehicle, a Class 4 licence is NOT required when the operator receives compensation:","options":["for the kilometres travelled","for the full market price of the vehicle’s time","at triple the commercial taxi rate","for the vehicle’s depreciation"],"answer":0,"explanation":"Compensation in the form of payment for the kilometres travelled — or straight reimbursement for out-of-pocket expenses such as gas, parking, gate passes and tolls — does not require a Class 4.","source":{"chapter":1,"section":"For hire, driver’s licence requirements","anchor":"#for-hire-drivers-licence-requirements","page":"16"}},{"id":"ch1-039","chapter":1,"category":"gdl","question":"Providing transportation for compensation does NOT require a Class 4 when the operator is party to an agreement to carry only:","options":["Co-workers commuting to the same job site","Members of the public paying a posted fare","The operator’s family members, household members, or persons for whom the operator is a legal guardian","Players on a sports team sharing costs"],"answer":2,"explanation":"Class 4 is not required when the agreement to transport for compensation covers only the operator’s family members, members of the household, or persons for whom the operator is a legal guardian.","source":{"chapter":1,"section":"For hire, driver’s licence requirements","anchor":"#for-hire-drivers-licence-requirements","page":"16"}},{"id":"ch1-040","chapter":1,"category":"gdl","question":"An air brake endorsement (Q) is placed on a driver’s licence when the person:","options":["Passes a vision re-screen at a registry agent","Pays a one-time endorsement fee","Successfully completes an approved Alberta air brake course through an authorized agency","Registers a vehicle with air brakes"],"answer":2,"explanation":"When a person successfully completes an approved Alberta air brake course through an authorized agency, an air brake endorsement (Q) is placed on that driver’s licence.","source":{"chapter":1,"section":"Air brake endorsement (Q)","anchor":"#air-brake-endorsement-q","page":"16"}},{"id":"ch1-041","chapter":1,"category":"gdl","question":"An air brake endorsement is required for drivers of vehicles with:","options":["Spring parking brakes only","Disc brakes on the rear axle","A foot-operated exhaust brake","An air-only braking system, or a combination of air and hydraulic braking systems"],"answer":3,"explanation":"An air brake endorsement is required for drivers of vehicles with an air-only braking system, or a combination of air and hydraulic braking system.","source":{"chapter":1,"section":"Air brake endorsement (Q)","anchor":"#air-brake-endorsement-q","page":"16"}},{"id":"ch1-042","chapter":1,"category":"gdl","question":"Road tests must be conducted only by persons:","options":["Designated by the Government of Alberta as driver examiners","Working for your driving school","Certified by your insurance company","Registered with a driving association"],"answer":0,"explanation":"Road tests must be conducted only by persons designated by the Government of Alberta as driver examiners, who ensure only qualified individuals receive a driver’s licence.","source":{"chapter":1,"section":"Driver examiner","anchor":"#driver-examiner","page":"17"}},{"id":"ch1-043","chapter":1,"category":"gdl","question":"Who may ride along on your road test?","options":["One passenger wearing a seat belt","No passengers or pets are allowed, except an examiner accompanied by a government official during a training or monitoring session","A driving instructor seated in the back","A family member there to calm your nerves"],"answer":1,"explanation":"On a road test, no passengers or pets are allowed; the exemption is when an examiner is accompanied by a government official during a training or monitoring session.","source":{"chapter":1,"section":"Driver examiner","anchor":"#driver-examiner","page":"17"}},{"id":"ch1-044","chapter":1,"category":"gdl","question":"On the request of a peace officer, a person driving a motor vehicle must produce:","options":["Only their driver’s licence","A birth certificate only","Their subsisting driver’s licence, insurance, and registration","A photograph of the documents on their phone"],"answer":2,"explanation":"On the request of a peace officer, a person driving must produce their subsisting driver’s licence, insurance, and registration — keep these documents with you every time you operate a motor vehicle.","source":{"chapter":1,"section":"Driver’s licence","anchor":"#drivers-licence","page":"17"}},{"id":"ch1-045","chapter":1,"category":"gdl","question":"An Alberta driver’s licence may only be issued to:","options":["Canadian citizens aged 16 or older anywhere in Canada","International visitors staying less than one year","Anyone with a Canadian mailing address","Residents of Alberta — a person lawfully entitled to be in Canada, who makes their home in Alberta and is ordinarily present in Alberta"],"answer":3,"explanation":"A driver’s licence may only be issued to residents of Alberta: a person lawfully entitled to be in Canada who makes their home in Alberta and is ordinarily present in Alberta.","source":{"chapter":1,"section":"Applying for your Alberta driver’s licence","anchor":"#applying-for-your-alberta-drivers-licence","page":"17"}},{"id":"ch1-046","chapter":1,"category":"gdl","question":"A parent or guardian’s signature is NOT needed on a minor’s first licence application if the minor provides proof of:","options":["Employment at a part-time job","Marriage or self-support","Enrolment in high school","A learner’s permit held for two years"],"answer":1,"explanation":"A parent/guardian signature is not needed if the minor provides proof of marriage or self-support. A guardian may revoke consent in writing until the minor turns 18, and a revocation suspends the licence.","source":{"chapter":1,"section":"Applying for your Alberta driver’s licence","anchor":"#applying-for-your-alberta-drivers-licence","page":"17"}},{"id":"ch1-047","chapter":1,"category":"gdl","question":"A visitor to Alberta with a valid out-of-province licence or permit for a specific vehicle class may drive the same class of vehicle in Alberta without obtaining a local licence for up to:","options":["30 days","90 days","six months","one year"],"answer":3,"explanation":"Visitors with a valid out-of-province licence or permit may drive the same class of vehicle in Alberta without a local licence for up to one year.","source":{"chapter":1,"section":"Non-Alberta licenCe for tourists and visitors","anchor":"#nonalberta-licence-for-tourists-and-visitors","page":"18"}},{"id":"ch1-048","chapter":1,"category":"gdl","question":"New Alberta residents from other places in Canada must apply for an Alberta driver’s licence and surrender their out-of-province licence within:","options":["30 days of residency","90 days of residency","six months of residency","one year of residency"],"answer":1,"explanation":"New residents may use their out-of-province licence for the first 90 days of residency and must apply for an Alberta licence and surrender the old one within those 90 days. It is illegal to hold more than one driver’s licence.","source":{"chapter":1,"section":"New Alberta residents","anchor":"#new-alberta-residents","page":"18"}},{"id":"ch1-049","chapter":1,"category":"gdl","question":"A valid licence from a jurisdiction with a reciprocal licensing agreement can be exchanged for a Class 5 licence when the applicant:","options":["Passes a full Class 5 road test first","Presents a valid licence of equivalent class","Holds an Alberta Class 7 for one year","Completes the full GDL program"],"answer":1,"explanation":"A valid licence from a reciprocal jurisdiction can be exchanged for a Class 5 licence when the applicant presents a valid licence of equivalent class; all other licence classes require testing and vision screening.","source":{"chapter":1,"section":"New Alberta residents","anchor":"#new-alberta-residents","page":"18"}},{"id":"ch1-050","chapter":1,"category":"gdl","question":"Alberta’s reciprocal licensing agreement with Australia covers which licence classes?","options":["Class 1 and 2","Class 3 and 4","Class 5 and 6","All classes"],"answer":2,"explanation":"Reciprocal licensing agreements with Australia, Isle of Man, the Republic of Ireland, and Switzerland (among others) cover Class 5 and 6; Austria, Belgium, France, Germany, Japan, the Netherlands, Korea and Taiwan cover Class 5.","source":{"chapter":1,"section":"New Alberta residents","anchor":"#new-alberta-residents","page":"18"}},{"id":"ch1-051","chapter":1,"category":"gdl","question":"A person coming to Alberta from a jurisdiction without a reciprocal agreement may apply to have their previous driving history credited. A successful application will:","options":["Grant exemption from the GDL program and allow Class 5 road testing without holding a Class 7 learner’s licence for one year","Grant a full Class 5 licence by mail before any testing","Guarantee a Class 1 commercial licence","Waive the vision screening permanently"],"answer":0,"explanation":"A successful application grants exemption from the GDL program and allows Class 5 road testing without being required to hold a Class 7 learner’s licence for one year.","source":{"chapter":1,"section":"New Alberta residents","anchor":"#new-alberta-residents","page":"18"}},{"id":"ch1-052","chapter":1,"category":"gdl","question":"A full-time student from outside Alberta is not required to obtain an Alberta driver’s licence, provided the student:","options":["Is authorized to operate the same type or class of vehicle where they ordinarily reside, carries the documents required there, and carries proof of full-time student status in this province","Has a letter of permission from a professor","Owns a vehicle registered in Alberta","Pays a one-time student registry fee"],"answer":0,"explanation":"Students must be authorized to operate the same type or class of vehicle by the laws of the jurisdiction where they ordinarily reside, carry the documents required by those laws, and carry proof of full-time student status in this province.","source":{"chapter":1,"section":"New Alberta residents","anchor":"#new-alberta-residents","page":"18"}},{"id":"ch1-053","chapter":1,"category":"gdl","question":"If you have a medical or physical condition that could affect your ability to safely operate a motor vehicle, such as diabetes or a seizure disorder, you must submit:","options":["A notarized letter from any clinic","A Driver Medical Intake Form","An insurance waiver","A new vision screening only"],"answer":1,"explanation":"You must disclose any medical or physical condition that could affect safe driving and submit a Driver Medical Intake Form, which must be completed by a doctor or nurse practitioner.","source":{"chapter":1,"section":"Medical requirements","anchor":"#medical-requirements","page":"19"}},{"id":"ch1-054","chapter":1,"category":"gdl","question":"Who must complete the Driver Medical Intake Form?","options":["The driver themselves","A doctor or nurse practitioner","Any first responder","The registry agent"],"answer":1,"explanation":"The Driver Medical Intake Form must be completed by a doctor or a nurse practitioner, then returned to an Alberta registry agent office or emailed to the Driver Medical Fitness Program.","source":{"chapter":1,"section":"Medical requirements","anchor":"#medical-requirements","page":"19"}},{"id":"ch1-055","chapter":1,"category":"gdl","question":"When applying for or renewing a Class 7, 6, 5, or 3 licence at age 75 or older, you must:","options":["Provide a completed Driver Medical Intake Form and have your vision assessed at an Alberta registry agent office","Retake the full knowledge exam every year","Stop driving after your 76th birthday","Obtain a letter from your employer"],"answer":0,"explanation":"Drivers aged 75 or older must provide a completed Driver Medical Intake Form when applying for or renewing a Class 7, 6, 5, or 3 licence, and their vision will also be assessed at a registry agent office.","source":{"chapter":1,"section":"Medical requirements","anchor":"#medical-requirements","page":"19"}},{"id":"ch1-056","chapter":1,"category":"gdl","question":"If you don’t submit a Driver Medical Intake Form when it is required:","options":["Nothing happens until you are charged with an offence","Your licence renewal or application can be denied, and Transportation and Economic Corridors may suspend your existing licence until medical documentation is provided","Your demerit points are doubled","You receive a written warning only"],"answer":1,"explanation":"Failure to submit a required Driver Medical Intake Form means a licence renewal or application can be denied, and Transportation and Economic Corridors may suspend the existing licence until medical documentation is provided.","source":{"chapter":1,"section":"Medical requirements","anchor":"#medical-requirements","page":"19"}},{"id":"ch1-057","chapter":1,"category":"gdl","question":"A condition code on a driver’s licence indicates:","options":["Special requirements, such as needing glasses or contact lenses to meet the vision standards","A chosen discount program","Optional vehicle colour preferences","Active demerit points"],"answer":3,"explanation":"A condition code may be added to indicate special requirements; for example, requiring glasses or contact lenses to meet vision standards, or needing periodic medical examination, is indicated by a condition code.","source":{"chapter":1,"section":"Condition codes and endorsements","anchor":"#condition-codes-and-endorsements","page":"20"}},{"id":"ch1-058","chapter":1,"category":"gdl","question":"An endorsement code on a driver’s licence shows that the person:","options":["Has volunteered at a registry office","Exceeds the standard insurance limits","Has had specific education or training, or is permitted to drive a vehicle that has a specific feature","Was once denied a road test"],"answer":2,"explanation":"An endorsement code shows specific education or training, such as a novice driver education course or a school bus course, or that the person is permitted to drive a vehicle with a specific feature, such as air brakes.","source":{"chapter":1,"section":"Condition codes and endorsements","anchor":"#condition-codes-and-endorsements","page":"20"}},{"id":"ch1-059","chapter":1,"category":"gdl","question":"Which endorsement code indicates the driver has completed the education or training specific to operating a school bus?","options":["S","Q","V","U"],"answer":0,"explanation":"The endorsement S is for School Bus. Q is Air Brakes, V is Extended Length Vehicle Combinations, and U is Completed Driver Education Course.","source":{"chapter":1,"section":"Condition codes and endorsements","anchor":"#condition-codes-and-endorsements","page":"20"}},{"id":"ch1-060","chapter":1,"category":"gdl","question":"On an Alberta driver’s licence, endorsement V stands for:","options":["Volunteer driving","Extended length vehicle combinations","Vision standards met","Vehicle export"],"answer":1,"explanation":"V is the endorsement for Extended Length Vehicle Combinations.","source":{"chapter":1,"section":"Condition codes and endorsements","anchor":"#condition-codes-and-endorsements","page":"20"}},{"id":"ch1-061","chapter":1,"category":"gdl","question":"Which condition code on an Alberta driver’s licence means Daylight Driving Only?","options":["F","G","L","H"],"answer":3,"explanation":"H is Daylight Driving Only. F is Valid Temporary Licence, G is Temporary Resident, and L is Hand Controls.","source":{"chapter":1,"section":"Condition codes and endorsements","anchor":"#condition-codes-and-endorsements","page":"20"}},{"id":"ch1-062","chapter":1,"category":"gdl","question":"Which of the following licence codes does NOT appear on the driver’s licence itself?","options":["A — Adequate Lenses","H — Daylight Driving Only","C — Periodic Medical","K — Automatic Transmission"],"answer":2,"explanation":"Codes marked with an asterisk — C (Periodic Medical), D (Periodic Vision Report), E (Periodic Driver Examination), M, P, T (conditions) and U (endorsement) — do not appear on the driver’s licence.","source":{"chapter":1,"section":"Condition codes and endorsements","anchor":"#condition-codes-and-endorsements","page":"20"}},{"id":"ch1-063","chapter":1,"category":"gdl","question":"Conditions and endorsements specific to you are placed:","options":["On the front of the licence, in the Cond/End section","On the licence plate","In a separate registry file that is never shown","Only on your insurance policy"],"answer":0,"explanation":"Each condition or endorsement corresponds to a letter code; conditions and endorsements specific to you are placed on the front of the licence, in the Cond/End section, and some have an explanation on the back.","source":{"chapter":1,"section":"Condition codes and endorsements","anchor":"#condition-codes-and-endorsements","page":"20"}},{"id":"ch1-064","chapter":1,"category":"gdl","question":"When re-classing your driver’s licence (excluding Class 7 to Class 5), you must present proof that you have completed:","options":["A knowledge test and vision test through a registry agent office","A night-driving course","An approved first-aid certificate","A vehicle inspection"],"answer":0,"explanation":"When re-classing (excluding Class 7 to Class 5), you must present proof of a completed knowledge test and vision test through a registry agent office. A fee is charged for each knowledge test, road test, and the final licence re-classification service.","source":{"chapter":1,"section":"Re-classing your licence","anchor":"#reclassing-your-licence","page":"22"}},{"id":"ch1-065","chapter":1,"category":"gdl","question":"Re-classing your licence from your current class to a Class 1, 2, or 4 licence will also require:","options":["A medical report","A letter from your employer","A new licence photo only","Proof of home ownership"],"answer":0,"explanation":"Re-classing to a Class 1, 2, or 4 licence also requires a medical report, along with the knowledge test and vision test proof.","source":{"chapter":1,"section":"Re-classing your licence","anchor":"#reclassing-your-licence","page":"22"}},{"id":"ch1-066","chapter":1,"category":"gdl","question":"If your driver’s licence is stolen, you must:","options":["Wait until the licence’s expiry date to act","Report it to the police, and provide a copy of the police report to the registry agent when you apply for your replacement","Simply order a new licence plate","Report it only to your insurance company"],"answer":1,"explanation":"If your licence is stolen, you must report it to the police and provide a copy of the police report to the registry agent when applying for a replacement. Lost, destroyed, or unreadable licences must be replaced immediately at a registry agent office.","source":{"chapter":1,"section":"Replacing your Alberta driver’s licence","anchor":"#replacing-your-alberta-drivers-licence","page":"22"}},{"id":"ch1-067","chapter":1,"category":"gdl","question":"Which statement about renewing and updating an Alberta driver’s licence is true?","options":["The Government mails renewal reminders to every driver","It is your responsibility to renew your driver’s licence on or before the expiry date","Address changes are only possible after the licence expires","Renewals completed after expiry are free for the first 90 days"],"answer":1,"explanation":"Reminder mail-outs have stopped (Albertans can sign up for free electronic reminders via E-registry or MyAlberta), and it is your responsibility to renew on or before the expiry date. Licence information such as name, address, or class is updated at a registry agent and must by law be current and accurate.","source":{"chapter":1,"section":"Renewing your Alberta driver’s licence","anchor":"#renewing-your-alberta-drivers-licence","page":"22"}},{"id":"ch1-068","chapter":1,"category":"gdl","question":"A vehicle owner must register their vehicle within ___ of moving to Alberta.","options":["30 days","three months","six months","one year"],"answer":1,"explanation":"A vehicle owner must register their vehicle within three months of moving to Alberta. Motor vehicles and trailers travelling on Alberta roadways must be registered.","source":{"chapter":1,"section":"Registration and insurance","anchor":"#registration-and-insurance","page":"23"}},{"id":"ch1-069","chapter":1,"category":"gdl","question":"In Alberta, licence plates:","options":["Remain with the owner of the vehicle and are not transferable to another person","Transfer automatically to the buyer of the vehicle","Stay permanently attached to the vehicle","Are issued by the insurance company"],"answer":0,"explanation":"In Alberta, licence plates remain with the owner of the vehicle and are not transferable to another person. Registration certificates cannot be issued to anyone under 18 unless a parent or guardian also signs the application.","source":{"chapter":1,"section":"Registration and insurance","anchor":"#registration-and-insurance","page":"23"}},{"id":"ch1-070","chapter":1,"category":"gdl","question":"When registering a vehicle — and when requested by a peace officer — you must present:","options":["A void cheque","The vehicle owner’s manual","A financial responsibility card (pink card) issued by your insurance company","A copy of the sales receipt only"],"answer":2,"explanation":"Your insurance company issues a financial responsibility card (pink card), which must be presented when registering a vehicle and when requested by a peace officer. It is illegal to operate an uninsured motor vehicle.","source":{"chapter":1,"section":"Registration and insurance","anchor":"#registration-and-insurance","page":"23"}},{"id":"ch10-tow-001","chapter":10,"category":"towing","question":"What documentation must you have with you when towing a trailer?","options":["A notarized bill of sale for the trailer","Valid registration from an Alberta registry for the trailer","A copy of the towing vehicle insurance only","An annual trailer inspection certificate"],"answer":1,"explanation":"You must have valid registration from an Alberta registry for your trailer, and it must be with you when you are towing the trailer.","source":{"chapter":10,"section":"Registration and licence plate","anchor":"#registration-and-licence-plate","page":"120"}},{"id":"ch10-tow-002","chapter":10,"category":"towing","question":"Where must the licence plate be on a trailer being used on the road?","options":["On the trailer tongue, facing forward","Inside the trailer with the registration papers","Attached to the rear of the trailer and clearly visible","On the rear bumper of the towing vehicle"],"answer":2,"explanation":"There must be a valid licence plate attached to the rear of the trailer and clearly visible; the registration and licence plate are required before the trailer can be used on the road.","source":{"chapter":10,"section":"Registration and licence plate","anchor":"#registration-and-licence-plate","page":"120"}},{"id":"ch10-tow-003","chapter":10,"category":"towing","question":"What lighting equipment must a trailer have?","options":["Reflectors only, since lights drain the towing battery","A single combined brake and tail light at the centre of the trailer","Amber running lights on the trailer tongue only","Working tail-lights, brake lights and turn signals that are activated from the towing vehicle"],"answer":3,"explanation":"Your trailer must have working tail-lights, brake lights, and turn signals that are activated from the towing vehicle.","source":{"chapter":10,"section":"Equipment","anchor":"#equipment","page":"120"}},{"id":"ch10-tow-004","chapter":10,"category":"towing","question":"How should safety chains be attached between a trailer and the towing vehicle with a ball-and-socket hitch?","options":["Crossed under the tongue of the trailer and fastened securely","Wrapped around the towing vehicle bumper and left slack","Connected to the trailer brake cable only","Attached above the tongue, parallel to the drawbar"],"answer":0,"explanation":"If you have a ball-and-socket hitch, attach safety chains between the trailer and the towing vehicle; chains should be crossed under the tongue of the trailer and fastened securely.","source":{"chapter":10,"section":"Equipment","anchor":"#equipment","page":"120"}},{"id":"ch10-tow-005","chapter":10,"category":"towing","question":"The requirement for crossed safety chains applies to which trailers?","options":["Only trailers over 910 kilograms","All trailers except fifth-wheel trailers","Only boat and utility trailers","Only trailers without brakes"],"answer":1,"explanation":"Safety chains crossed under the tongue and fastened securely apply to all trailers except fifth-wheel trailers.","source":{"chapter":10,"section":"Equipment","anchor":"#equipment","page":"120"}},{"id":"ch10-tow-006","chapter":10,"category":"towing","question":"When towing, when must you use extension (towing) mirrors?","options":["Whenever you tow on a multi-lane highway","If the trailer is wider than the vehicle towing it","Only when towing at night","Only with a fifth-wheel hitch"],"answer":1,"explanation":"Adjust your mirrors so you can see traffic approaching from behind; you must use extension mirrors if the trailer is wider than the vehicle towing the trailer.","source":{"chapter":10,"section":"Equipment","anchor":"#equipment","page":"120"}},{"id":"ch10-tow-007","chapter":10,"category":"towing","question":"Which trailers do not require brakes on the trailer itself?","options":["All towed trailers in Alberta","Any trailer with a licence plate","Trailers with a gross weight of 910 kilograms (2,000 pounds) or less","Trailers with a gross weight between 910 and 1,400 kilograms"],"answer":2,"explanation":"Brakes are required only when needed to control safe movement; trailers with a gross weight of 910 kilograms (2,000 pounds) or less do not require brakes.","source":{"chapter":10,"section":"Equipment","anchor":"#equipment","page":"120"}},{"id":"ch10-tow-008","chapter":10,"category":"towing","question":"Besides the 910-kilogram limit, when else are trailer brakes not required?","options":["When the trailer is towed only on private property","When the gross weight is less than half the unloaded weight of the towing vehicle","When the trailer is equipped with anti-lock tires","When towing is done below 60 km/h"],"answer":1,"explanation":"Trailers do not require brakes if they have a gross weight of 910 kilograms or less, or a gross weight that is less than half the unloaded weight of the vehicle doing the towing.","source":{"chapter":10,"section":"Equipment","anchor":"#equipment","page":"120"}},{"id":"ch10-tow-009","chapter":10,"category":"towing","question":"Your trailer has a secondary emergency breakaway system. What must you do with it?","options":["Test it by pulling the release pin at 60 km/h","Remove it for light loads around town","Be sure it is connected properly according to the manufacturer's instructions","Attach it to the trailer tail-lights"],"answer":2,"explanation":"If your trailer is equipped with a secondary emergency breakaway system, be sure that the system is connected properly according to the manufacturer's instructions.","source":{"chapter":10,"section":"Equipment","anchor":"#equipment","page":"120"}},{"id":"ch10-tow-010","chapter":10,"category":"towing","question":"While towing a trailer on a multi-lane highway, which lane should slower-moving vehicles travel in?","options":["Any lane, as trailers are exempt","The left lane, to keep sight lines clear","The right lane","The centre lane, to avoid merges"],"answer":2,"explanation":"On a multi-lane highway, remember that slower-moving vehicles should travel in the right lane; avoid quick lane changes and let others pass if traffic builds behind you.","source":{"chapter":10,"section":"Towing a trailer","anchor":"#towing-a-trailer","page":"120"}},{"id":"ch10-tow-011","chapter":10,"category":"towing","question":"What is off-tracking when turning with a trailer?","options":["The towing vehicle drifting across the lane line during the turn","The trailer tongue lifting during acceleration","The trailer swaying side to side at highway speed","The trailer wheels travelling a path inside the path of the wheels of your towing vehicle"],"answer":3,"explanation":"While turning, glance at the trailer wheels: the trailer wheels travel a path that is inside the path of your vehicle's wheels. This is called off-tracking.","source":{"chapter":10,"section":"Turning at intersections","anchor":"towing-a-trailer","page":"121"}},{"id":"ch10-tow-012","chapter":10,"category":"towing","question":"What could happen when turning right with a trailer if you do not allow for off-tracking?","options":["The towing vehicle could stall mid-turn","The trailer could shift into reverse while turning","Contact with a curb, a parked vehicle, or a pedestrian","The trailer wheels could lock up"],"answer":2,"explanation":"If you do not allow for the off-tracking, you could make contact with a curb, a parked vehicle, or a pedestrian.","source":{"chapter":10,"section":"Turning at intersections","anchor":"towing-a-trailer","page":"121"}},{"id":"ch10-tow-013","chapter":10,"category":"towing","question":"How do you steer when beginning to back a trailer?","options":["Pump the steering wheel from lock to lock","Turn the steering wheel in the opposite direction you want the trailer to go; turn right to go left","Turn the steering wheel in the direction you want the trailer to go","Keep the steering wheel perfectly straight the whole way"],"answer":1,"explanation":"Begin backing by turning the steering wheel in the opposite direction you want to go; turn the steering wheel right to go left, and left to go right.","source":{"chapter":10,"section":"Backing a trailer","anchor":"towing-a-trailer","page":"121"}},{"id":"ch10-tow-014","chapter":10,"category":"towing","question":"How fast may you reverse a vehicle while backing a trailer?","options":["No faster than a walking pace","Up to 20 km/h in an empty lot","Up to 10 km/h with a spotter walking behind","There is no set reversing speed"],"answer":0,"explanation":"When backing a trailer, have someone guide you; if you do not have a guide, walk to the back of the trailer to be sure the path is clear, and always reverse no faster than a walking pace.","source":{"chapter":10,"section":"Backing a trailer","anchor":"towing-a-trailer","page":"121"}},{"id":"ch10-tow-015","chapter":10,"category":"towing","question":"How much should you turn the steering wheel to avoid contact between your vehicle and the trailer while backing?","options":["A full rotation, then compensate in reverse","Only one-quarter to one-half turn, then return it to the normal position as the trailer begins to turn","As much as needed, then hold it fully turned","Never turn while reversing a trailer"],"answer":1,"explanation":"To avoid having your vehicle contact the trailer, only turn the steering wheel one-quarter to one-half turn; as soon as the trailer begins to turn, return the steering wheel to the normal position.","source":{"chapter":10,"section":"Backing a trailer","anchor":"towing-a-trailer","page":"121"}},{"id":"ch2-mrk-001","chapter":2,"category":"markings","question":"Yellow line markings mean vehicles on each side of the yellow line travel…","options":["In the same direction","In opposite directions","Anywhere on the road","Only downhill"],"answer":1,"explanation":"Yellow lines separate opposing directions of travel; the line should always be on the driver’s left.","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"38"}},{"id":"ch2-mrk-002","chapter":2,"category":"markings","question":"A solid yellow line on your side of the road means passing is…","options":["Permitted","Not permitted","Permitted only for motorcycles","Permitted at night"],"answer":1,"explanation":"A solid line means crossing it to pass or change lanes is not permitted (within an urban area, single solid yellow may be crossed to pass safely).","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"38"}},{"id":"ch2-mrk-003","chapter":2,"category":"markings","question":"Crossing a broken yellow line to pass is…","options":["Permitted when the lane is clear and the pass can be completed safely","Always illegal","Permitted only for heavy vehicles","Permitted only on weekends"],"answer":0,"explanation":"Broken yellow lines indicate passing is permitted; be sure the lane is clear and the pass can be completed safely.","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"38"}},{"id":"ch2-mrk-004","chapter":2,"category":"markings","question":"Single or double solid yellow together indicate passing is NOT permitted — except when the lines are…","options":["Wet","Single solid yellow within an urban area","On a hill","Near a school"],"answer":1,"explanation":"Passing safely is permitted across single solid yellow lines within an urban area; elsewhere, single or double solid yellow means no passing.","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"38"}},{"id":"ch2-mrk-005","chapter":2,"category":"markings","question":"A solid yellow line and a broken yellow line together allow the pass only to the driver…","options":["On the solid line side","With the broken line on their side","Behind a bus","Turning right"],"answer":1,"explanation":"Passing is permitted for the driver who has the broken line on their side of the roadway.","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"38"}},{"id":"ch2-mrk-006","chapter":2,"category":"markings","question":"White line markings mean vehicles on each side travel…","options":["In opposite directions","In the same direction","In circles","On the shoulder"],"answer":1,"explanation":"White lines separate traffic travelling in the same direction.","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"39"}},{"id":"ch2-mrk-007","chapter":2,"category":"markings","question":"Solid white line markings mean lane changes are…","options":["Permitted","Not permitted","Permitted with signal","Permitted for taxis"],"answer":1,"explanation":"Solid white lines indicate lane changing is not permitted.","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"41"}},{"id":"ch2-mrk-008","chapter":2,"category":"markings","question":"Diamond markings on a lane indicate that the lane is…","options":["Reserved for specific vehicles (e.g., bikes, buses) possibly with time restrictions","Closed","For parking","A passing zone"],"answer":0,"explanation":"Diamond markings indicate a reserved lane for specific vehicles; signs may add time or vehicle restrictions.","source":{"chapter":2,"section":"Designated lane signs","anchor":"traffic-direction-signs","page":"28"}},{"id":"ch2-mrk-009","chapter":2,"category":"markings","question":"X markings on rural highways indicate…","options":["A gas station","The approach to a railway crossing","A bus stop","A dead end"],"answer":1,"explanation":"X markings on rural highways indicate the approach to a railway crossing; an advanced warning sign will also indicate the crossing.","source":{"chapter":2,"section":"Shared-use lanes","anchor":"#shared-use-lanes","page":"40"}},{"id":"ch2-mrk-010","chapter":2,"category":"markings","question":"A two-way left turn lane lets vehicles…","options":["Travel through between intersections","From each direction turn left using the same centre lane","Park temporarily","Turn right"],"answer":1,"explanation":"Vehicles from either direction may turn left using the shared centre lane; you may cross the solid yellow line to enter it.","source":{"chapter":2,"section":"Two-way left turn lanes","anchor":"turning-lanes","page":"67"}},{"id":"ch2-mrk-011","chapter":2,"category":"markings","question":"In a bicycle lane, other drivers may drive…","options":["Any time it is clear","Only when needing to turn, or to enter/exit a parking spot","Never","On weekends"],"answer":1,"explanation":"Vehicles are not allowed in bicycle lanes except when turning or entering/exiting a parking spot; the bike-lane line is dashed near corners to signal it is permitted to enter to turn right.","source":{"chapter":2,"section":"Shared-use lanes","anchor":"#shared-use-lanes","page":"40"}},{"id":"ch2-mrk-012","chapter":2,"category":"markings","question":"Before crossing a bicycle lane to turn right you should…","options":["Be very careful and watch for bicycles","Honk continuously","Stop on the bike line","Signal to cyclists to stop"],"answer":0,"explanation":"Enter the bicycle lane carefully, watching for bicycles, when the line is dashed near the corner.","source":{"chapter":2,"section":"Shared-use lanes","anchor":"#shared-use-lanes","page":"40"}},{"id":"ch2-mrk-013","chapter":2,"category":"markings","question":"A painted island (hatched area) shows that the area…","options":["Is not to be used for travel by any road user","Is a passing lane","Is for police use","Is a bus stop"],"answer":0,"explanation":"Painted islands are not to be used for travel; motorists may cross them only to enter or leave a driveway, alleyway, or private drive.","source":{"chapter":2,"section":"Shared-use lanes","anchor":"#shared-use-lanes","page":"40"}},{"id":"ch2-mrk-014","chapter":2,"category":"markings","question":"Crosswalks exist at intersections…","options":["Only when marked with painted lines","Even when unmarked, unless a sign indicates no crossing","Only in school zones","Only mid-block"],"answer":1,"explanation":"Crosswalks also exist at unmarked intersections unless a sign indicates no crossing; stop lines show where vehicles stop.","source":{"chapter":2,"section":"Other roadway markings","anchor":"#other-roadway-markings","page":"41"}},{"id":"ch2-mrk-015","chapter":2,"category":"markings","question":"Arrows painted on a lane indicate…","options":["The vehicle movements permitted in that lane","Parking rules","The speed limit","Bike routes"],"answer":0,"explanation":"Pavement arrows supplement signs by showing the permitted lane movements.","source":{"chapter":2,"section":"Pavement markings","anchor":"#pavement-markings","page":"39"}},{"id":"ch2-mrk-016","chapter":2,"category":"markings","question":"“No stopping” zones are painted so drivers…","options":["Know they may not stop there, since turning vehicles need extra room","Know parking is free","Know it is a taxi stand","Can wait for pedestrians"],"answer":0,"explanation":"Drivers should not stop in a no-stopping zone because turning vehicles (especially large ones) need that room.","source":{"chapter":2,"section":"Other roadway markings","anchor":"#other-roadway-markings","page":"41"}},{"id":"ch2-mrk-017","chapter":2,"category":"markings","question":"Reserved bicycle lanes are separated from traffic and parking by…","options":["Solid white lines and a bicycle-and-diamond marking","Broken yellow lines","Parked cars","Median barriers"],"answer":0,"explanation":"The reserved bike lane is separated by solid white lines and marked with an image of a bicycle and a diamond.","source":{"chapter":2,"section":"Shared-use lanes","anchor":"#shared-use-lanes","page":"40"}},{"id":"ch2-sgn-001","chapter":2,"category":"signs","question":"A red octagon (eight-sided) sign always means…","options":["Yield","Stop","No parking","Warning"],"answer":1,"explanation":"The stop sign is a red octagon; stop signs require a complete stop before proceeding when safe.","source":{"chapter":2,"section":"Traffic regulatory signs","anchor":"#traffic-regulatory-signs","page":"26"}},{"id":"ch2-sgn-002","chapter":2,"category":"signs","question":"A red triangle pointing down indicates…","options":["Yield","Stop","Divided highway","Railway crossing"],"answer":0,"explanation":"The yield sign is a downward-pointing red triangle; yield right-of-way to traffic not facing the sign and to pedestrians.","source":{"chapter":2,"section":"Traffic regulatory signs","anchor":"#traffic-regulatory-signs","page":"26"}},{"id":"ch2-sgn-003","chapter":2,"category":"signs","question":"A diamond-shaped sign with a yellow background provides…","options":["Ordering information","Warning or caution of a hazard","Route guidance","Parking rules"],"answer":1,"explanation":"Yellow diamond signs warn of potential hazards or required actions ahead.","source":{"chapter":2,"section":"Sign shapes and colours","anchor":"#sign-shapes-and-colours","page":"25"}},{"id":"ch2-sgn-004","chapter":2,"category":"signs","question":"A fluorescent yellow-green pentagon indicates…","options":["A hospital zone","A school zone or area","A construction detour","A roundabout"],"answer":1,"explanation":"The pentagon shape on a fluorescent yellow-green background indicates a school zone/area.","source":{"chapter":2,"section":"Sign shapes and colours","anchor":"#sign-shapes-and-colours","page":"25"}},{"id":"ch2-sgn-005","chapter":2,"category":"signs","question":"A square white sign with a black message is typically used for…","options":["Lane control","Recreation","Service","Detour"],"answer":0,"explanation":"White message on black background, square shape, indicates lane control.","source":{"chapter":2,"section":"Sign shapes and colours","anchor":"#sign-shapes-and-colours","page":"25"}},{"id":"ch2-sgn-006","chapter":2,"category":"signs","question":"An orange sign with a diamond or rectangular shape provides…","options":["Construction area information","Railway information","Direction and distance","Regulation"],"answer":0,"explanation":"Orange background signs provide construction area information.","source":{"chapter":2,"section":"Sign shapes and colours","anchor":"#sign-shapes-and-colours","page":"25"}},{"id":"ch2-sgn-007","chapter":2,"category":"signs","question":"A white message on a green rectangular background usually provides…","options":["A hazard warning","Information such as direction and distance to a destination","Parking rules","A law about trucks"],"answer":1,"explanation":"Green rectangles provide information like direction and distance to destinations.","source":{"chapter":2,"section":"Sign shapes and colours","anchor":"#sign-shapes-and-colours","page":"26"}},{"id":"ch2-sgn-008","chapter":2,"category":"signs","question":"A blue square sign typically indicates…","options":["A warning curve","A place for fuel, food, lodging or assistance","A no-entry rule","A school crossing"],"answer":1,"explanation":"Blue square signs indicate off-road services and facilities like fuel, food, lodging, RCMP/city police.","source":{"chapter":2,"section":"Information and guide signs","anchor":"#information-and-guide-signs","page":"36"}},{"id":"ch2-sgn-009","chapter":2,"category":"signs","question":"A red circle with a diagonal slash over a symbol means the action is…","options":["Permitted at night","Permitted with caution","Not permitted","Mandatory"],"answer":2,"explanation":"Prohibitive signs show a red circle and diagonal red bar on a white square — the action within is not permitted.","source":{"chapter":2,"section":"Prohibitive signs","anchor":"#prohibitive-signs","page":"29"}},{"id":"ch2-sgn-010","chapter":2,"category":"signs","question":"A green circle on a white square indicates the action shown is…","options":["Permitted","Prohibited","A hazard","For buses only"],"answer":0,"explanation":"Permissive signs are a green circle on a white square — the action within the circle is permitted.","source":{"chapter":2,"section":"Permissive signs","anchor":"#permissive-signs","page":"29"}},{"id":"ch2-sgn-011","chapter":2,"category":"signs","question":"What does a “WRONG WAY” regulatory sign indicate?","options":["Wrong-way traffic is legal ahead","Traffic is moving in an oncoming direction — do not proceed past the sign","Construction diverting traffic","A one-lane roundabout ahead"],"answer":1,"explanation":"The wrong-way sign indicates traffic is moving in an oncoming direction.","source":{"chapter":2,"section":"Traffic regulatory signs","anchor":"#traffic-regulatory-signs","page":"26"},"image":"../assets/p028_033.png"},{"id":"ch2-sgn-012","chapter":2,"category":"signs","question":"What is the meaning of this triangular red-and-white sign?","image":"../assets/p028_032.png","options":["Stop — complete stop required","Yield right-of-way to traffic not facing this sign and to pedestrians","Merging traffic ahead","Speed reduction zone"],"answer":1,"explanation":"The yield sign means allow traffic not facing the sign — and all pedestrians waiting to cross or within the crosswalk — the right-of-way.","source":{"chapter":2,"section":"Traffic regulatory signs","anchor":"#traffic-regulatory-signs","page":"26"}},{"id":"ch2-sgn-013","chapter":2,"category":"signs","question":"This eight-sided red sign requires you to…","image":"../assets/p028_031.png","options":["Yield if the way is clear","Come to a complete stop and proceed only when safe","Slow to 30 km/h before proceeding","Stop only if other traffic is present"],"answer":1,"explanation":"A stop sign means come to a complete stop before the stop line or crosswalk and proceed when the way is clear and safe.","source":{"chapter":2,"section":"Traffic regulatory signs","anchor":"#traffic-regulatory-signs","page":"26"}},{"id":"ch2-sgn-014","chapter":2,"category":"signs","question":"What restriction applies where you see this play figure diamond sign?","options":["A school zone: 30 km/h on school days only","A playground zone: 30 km/h every day from 8:30 a.m. to one hour after sunset","No parking any time","A pedestrian crossing with no speed change"],"answer":1,"explanation":"Playground zone restrictions are in effect every day from 8:30 a.m. to one hour after sunset, at 30 km/h unless posted otherwise.","source":{"chapter":2,"section":"Playground zones and areas","anchor":"#playground-zones-and-areas","page":"31"},"image":"../assets/p033_093.png"},{"id":"ch2-sgn-015","chapter":2,"category":"signs","question":"The slow-moving vehicle sign (orange triangle) is placed on vehicles that travel…","options":["Less than 40 km/h","Less than 60 km/h","More than 90 km/h","Only on highways"],"answer":0,"explanation":"The slow-moving vehicle sign is placed on the back of vehicles travelling less than 40 km/h, like farm machinery, warning drivers to reduce speed.","source":{"chapter":2,"section":"Other signs","anchor":"#other-signs","page":"37"}},{"id":"ch2-sgn-016","chapter":2,"category":"signs","question":"A sign showing a straight-through-and-right arrow over a lane means that lane is for…","options":[" Trucks only","Going straight or turning right","Only left turns","Parking and stopping"],"answer":1,"explanation":"Designated lane signs show the permitted movements of the lane — here straight or right turn.","source":{"chapter":2,"section":"Designated lane signs","anchor":"traffic-direction-signs","page":"28"}},{"id":"ch2-sgn-017","chapter":2,"category":"signs","question":"Reserved lanes painted with a diamond symbol are meant for…","options":["Everyone, at all times","Specific vehicles such as buses, taxis and bicycles","Heavy trucks only","Emergency vehicles only"],"answer":1,"explanation":"Diamond-marking reserved lanes are for specific vehicles; the sign symbol reveals which vehicles, and hours may restrict use.","source":{"chapter":2,"section":"Designated lane signs","anchor":"traffic-direction-signs","page":"28"}},{"id":"ch2-sgn-018","chapter":2,"category":"signs","question":"At a dual right-turn intersection you must…","options":["Turn wide into any lane","Maintain your lane position during and after the turn","Stop until both lanes clear","Turn from the left lane"],"answer":1,"explanation":"Where dual turns are marked, turn from the corresponding lane and maintain your lane position during and after the turn.","source":{"chapter":2,"section":"Designated lane signs","anchor":"traffic-direction-signs","page":"28"}},{"id":"ch2-sgn-019","chapter":2,"category":"signs","question":"In a single-lane roundabout, traffic circulates…","options":["Clockwise","Counter-clockwise","Either direction","Straight through only"],"answer":1,"explanation":"At traffic circles and roundabouts, traffic always circulates counter-clockwise around a centre island.","source":{"chapter":2,"section":"Designated lane signs","anchor":"traffic-direction-signs","page":"28"}},{"id":"ch2-sgn-020","chapter":2,"category":"signs","question":"A “no U-turn” sign appears where you planned the U-turn. You should…","options":["Do it if no one is watching","Do it but slowly","Not do the U-turn there — it is prohibited by sign","Reverse into the intersection instead"],"answer":2,"explanation":"U-turns are not permitted where a sign prohibits them; a red-slash prohibitive sign removes the permission.","source":{"chapter":2,"section":"Prohibitive signs","anchor":"#prohibitive-signs","page":"29"}},{"id":"ch2-sgn-021","chapter":2,"category":"signs","question":"A sign showing “Do not pass bicycles” means you may not…","options":["Pass bicycles in that zone","Follow bicycles","Ride bicycles there","Stop for bicycles"],"answer":0,"explanation":"The prohibitive sign bans passing bicycles — you must stay behind until the restriction ends.","source":{"chapter":2,"section":"Prohibitive signs","anchor":"#prohibitive-signs","page":"29"}},{"id":"ch2-sgn-022","chapter":2,"category":"signs","question":"A “Do Not Enter” sign with a white bar on red means…","options":["No entry — do not proceed past the sign","Enter with caution","Entry for residents only","No stopping"],"answer":0,"explanation":"The do-not-enter sign prohibits proceeding in the direction of the sign.","source":{"chapter":2,"section":"Traffic regulatory signs","anchor":"#traffic-regulatory-signs","page":"26"}},{"id":"ch2-sgn-023","chapter":2,"category":"signs","question":"The railway crossing sign (crossbuck) means…","options":["A train yard ahead","Drivers must yield to all trains at the crossing","Speed limit near trains","Trains stop for cars"],"answer":1,"explanation":"A railway crossing sign means drivers must yield to all trains; if more than one track, the sign shows the number of tracks.","source":{"chapter":2,"section":"Traffic regulatory signs","anchor":"#traffic-regulatory-signs","page":"26"}},{"id":"ch2-sig-001","chapter":2,"category":"signals","question":"You approach a solid red traffic control light. Where must you stop?","options":["Anywhere before the intersection if traffic is light","Before the stop line or crosswalk directly in front of your vehicle","Only at the right-hand curb","At the centre of the intersection"],"answer":1,"explanation":"Drivers facing a solid red light must bring their vehicle to a complete stop before the stop line or crosswalk directly in front of the vehicle; with no stop line or crosswalk, stop before the intersection.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-002","chapter":2,"category":"signals","question":"Turning right at a solid red light is permitted when…","options":["A sign prohibits it","You slow to walking speed","There is no sign prohibiting the turn, you come to a complete stop at the proper stopping point, and it is safe","Only between 9 a.m. and 5 p.m."],"answer":2,"explanation":"Unless a sign prohibits the turn, you may turn right on red after a complete stop before the stop line or crosswalk, yielding to other traffic.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-003","chapter":2,"category":"signals","question":"The only left turn allowed at a red light is…","options":["On a two-way street onto a two-way street","From a one-way street onto a one-way street, after a complete stop","Onto any one-way street from any street","Never permitted in Alberta"],"answer":1,"explanation":"Unless a sign prohibits it, the only left turn permitted at a red light is onto a one-way street from a one-way street, after a complete stop at the stop line or crosswalk.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-004","chapter":2,"category":"signals","question":"A solid double red light has…","options":["The same meaning as a single red light","Twice the penalty","A different meaning: stop once per light","No meaning in Alberta"],"answer":0,"explanation":"A solid double red light has the same meaning as a single red light.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-005","chapter":2,"category":"signals","question":"Approaching a solid yellow light, drivers must…","options":["Speed up to clear the intersection","Come to a complete stop before the stop line or crosswalk, unless stopping cannot be done safely","Proceed only if no other cars are around","Honk before proceeding"],"answer":1,"explanation":"A solid (not flashing) yellow warns the light will turn red; you must stop before the stop line or crosswalk unless you have passed the point where stopping safely is possible.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-006","chapter":2,"category":"signals","question":"You are already inside the intersection when the light turns yellow. You should…","options":["Stop as fast as possible","Reverse out of the intersection","Safely clear the intersection","Turn on hazards and wait"],"answer":2,"explanation":"Drivers already in the intersection facing a yellow light must safely clear the intersection.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-007","chapter":2,"category":"signals","question":"A “stale” green light means the light…","options":["Has been green for a while and will turn yellow soon","Is about to fail","Stays green indefinitely","Is controlled by a sensor"],"answer":0,"explanation":"A stale green light has been green for a while and will soon turn yellow; a tip is to check the pedestrian walk light at the intersection.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-008","chapter":2,"category":"signals","question":"Walking-sign tip for judging a green light: if the pedestrian signal shows “DON’T WALK”, you should…","options":["Keep speed — the light stays green","Be ready to stop if the light changes","Stop immediately","Switch on hazard lights"],"answer":1,"explanation":"If the walk light shows DON’T WALK, be ready to stop; showing WALK means the light will stay green.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"22"}},{"id":"ch2-sig-009","chapter":2,"category":"signals","question":"Facing a green arrow and a solid green light, you may…","options":["Proceed only straight","Enter and proceed without yielding in the arrow direction","Reverse in the arrow direction","Proceed after a complete stop"],"answer":1,"explanation":"You may enter the intersection and proceed without yielding in the direction of the green arrow.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"23"}},{"id":"ch2-sig-010","chapter":2,"category":"signals","question":"A flashing red traffic control light means you must…","options":["Proceed with caution","Stop, then proceed only when safe after yielding right-of-way","Speed up before it turns solid","Wait for the green light"],"answer":1,"explanation":"A flashing red light works like a stop sign: stop before the stop line or crosswalk, then proceed when safe after yielding right-of-way.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"23"}},{"id":"ch2-sig-011","chapter":2,"category":"signals","question":"When lights in all directions flash red, the intersection becomes…","options":["A merging zone","A four-way stop","A no-stopping zone","An emergency area"],"answer":1,"explanation":"When the lights in all directions are flashing red, the intersection becomes a four-way stop.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"23"}},{"id":"ch2-sig-012","chapter":2,"category":"signals","question":"Before a flashing yellow traffic control light you may…","options":["Proceed without stopping or yielding","Proceed with caution after yielding to pedestrians and vehicles within the intersection","Enter only on a police officer’s signal","Treat it as a stop sign"],"answer":1,"explanation":"A flashing yellow light means proceed with caution, yielding to pedestrians and other vehicles within the intersection.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"23"}},{"id":"ch2-sig-013","chapter":2,"category":"signals","question":"Facing a flashing green light, you are permitted to…","options":["Only proceed straight ahead","Go through, turn left or turn right without stopping, while yielding to pedestrians or vehicles lawfully in the intersection","Stop until it turns solid","Only turn right"],"answer":1,"explanation":"Opposing traffic faces a red, but you must still yield to pedestrians or other vehicles lawfully in the intersection.","source":{"chapter":2,"section":"Traffic control signals","anchor":"#traffic-control-signals","page":"23"}},{"id":"ch2-sig-014","chapter":2,"category":"signals","question":"Pedestrians facing a “WALK” symbol may…","options":["Enter the crosswalk when it is safe and proceed","Step out without looking","Cross only diagonally","Ignore the symbol"],"answer":0,"explanation":"Pedestrians facing a WALK display may enter the crosswalk or roadway when safe and proceed in that direction.","source":{"chapter":2,"section":"Pedestrian signals and signs","anchor":"#pedestrian-signals-and-signs","page":"23"}},{"id":"ch2-sig-015","chapter":2,"category":"signals","question":"A pedestrian who has already begun crossing when “DON’T WALK” appears should…","options":["Run back to the curb","Continue crossing and clear the crosswalk","Stop in place","Cross diagonally"],"answer":1,"explanation":"Pedestrians who began crossing may continue and clear the crosswalk; others must not enter.","source":{"chapter":2,"section":"Pedestrian signals and signs","anchor":"#pedestrian-signals-and-signs","page":"23"}},{"id":"ch2-sig-016","chapter":2,"category":"signals","question":"At an intersection with signals but no pedestrian WALK/DON’T WALK signals, pedestrians must…","options":["Wait for a police officer","Obey the rules for the colour of light they face","Always cross on red","Only cross at mid-block"],"answer":1,"explanation":"Pedestrians obey the rules for the colour of light they are facing when no pedestrian signal is present.","source":{"chapter":2,"section":"Pedestrian signals and signs","anchor":"#pedestrian-signals-and-signs","page":"24"}},{"id":"ch2-sig-017","chapter":2,"category":"signals","question":"A pedestrian crossing sign with flashing yellow lights requires you to…","options":["Maintain speed","Reduce to maximum 30 km/h and yield or stop for pedestrians","Sound your horn","Increase following distance only"],"answer":1,"explanation":"When the yellow lights on the sign are flashing, reduce speed to a maximum of 30 km/h, then yield or stop for pedestrians.","source":{"chapter":2,"section":"Pedestrian signals and signs","anchor":"#pedestrian-signals-and-signs","page":"24"}},{"id":"ch2-sig-018","chapter":2,"category":"signals","question":"Some pedestrian signals display a countdown timer that shows…","options":["Seconds until the light cycle ends","How much time remains before the light changes","Speed limit at the crossing","Number of pedestrians waiting"],"answer":1,"explanation":"The countdown shows how much time remains before the signal changes.","source":{"chapter":2,"section":"Pedestrian signals and signs","anchor":"#pedestrian-signals-and-signs","page":"23"}},{"id":"ch2-sig-019","chapter":2,"category":"signals","question":"A solid red X displayed over a driving lane means…","options":["The lane is closed for parking","Do not enter or remain in that lane — it is used by oncoming traffic","The lane is for buses only","Only trucks may use the lane"],"answer":1,"explanation":"When a red X is displayed over a driving lane, the driver does not enter or remain in that lane because it is being used by oncoming traffic.","source":{"chapter":2,"section":"Lane reversal signals","anchor":"#lane-reversal-signals","page":"24"}},{"id":"ch2-sig-020","chapter":2,"category":"signals","question":"A downward-pointing green arrow over a lane lets you…","options":["Wait at the lane entrance","Park briefly","Travel in that lane","Cross the lane to turn left"],"answer":2,"explanation":"A driver facing a downward-pointing green arrow is permitted to travel in that lane.","source":{"chapter":2,"section":"Lane reversal signals","anchor":"#lane-reversal-signals","page":"24"}},{"id":"ch2-sig-021","chapter":2,"category":"signals","question":"Reversible lanes controlled by lane reversal signals commonly change direction…","options":["Only during construction","During different times of the day","Every Sunday","When it rains"],"answer":1,"explanation":"A common use is reversible lanes that change the flow of traffic during different times of the day (red X vs green arrow).","source":{"chapter":2,"section":"Lane reversal signals","anchor":"#lane-reversal-signals","page":"24"}},{"id":"ch2-sig-022","chapter":2,"category":"signals","question":"A vehicle is drifting from a red-X lane into a green-arrow lane. What does the guide show as correct action?","options":["Stay and honk","Move safely into the lane with the green arrow","Stop under the X","Reverse"],"answer":1,"explanation":"The driver moves safely into the lane showing the downward green arrow.","source":{"chapter":2,"section":"Lane reversal signals","anchor":"#lane-reversal-signals","page":"25"}},{"id":"ch2-spd-001","chapter":2,"category":"signs","question":"Unless otherwise posted, the maximum speed on a provincial highway outside an urban area is…","options":["80 km/h","90 km/h","100 km/h","110 km/h"],"answer":2,"explanation":"100 km/h is the default maximum on a provincial highway located outside an urban area.","source":{"chapter":2,"section":"Speed limit signs","anchor":"#speed-limit-signs","page":"27"}},{"id":"ch2-spd-002","chapter":2,"category":"signs","question":"Unless otherwise posted, the maximum speed on a provincial highway inside a city’s corporate limit is…","options":["50 km/h","60 km/h","80 km/h","100 km/h"],"answer":2,"explanation":"80 km/h is the default maximum on a provincial highway inside a corporate limit of a city.","source":{"chapter":2,"section":"Speed limit signs","anchor":"#speed-limit-signs","page":"27"}},{"id":"ch2-spd-003","chapter":2,"category":"signs","question":"Unless otherwise posted, the maximum speed on a roadway located outside an urban area is…","options":["80 km/h","90 km/h","100 km/h","110 km/h"],"answer":0,"explanation":"80 km/h is the default maximum on a roadway (non-provincial-highway) outside an urban area.","source":{"chapter":2,"section":"Speed limit signs","anchor":"#speed-limit-signs","page":"27"}},{"id":"ch2-spd-004","chapter":2,"category":"signs","question":"Unless otherwise posted, the maximum speed within an urban area is…","options":["40 km/h","50 km/h","60 km/h","80 km/h"],"answer":1,"explanation":"50 km/h is the default maximum within an urban area unless posted otherwise.","source":{"chapter":2,"section":"Speed limit signs","anchor":"#speed-limit-signs","page":"27"}},{"id":"ch2-spd-005","chapter":2,"category":"signs","question":"A posted speed limit is…","options":["The safe speed in any weather","The maximum permitted when conditions are ideal","A minimum speed","A suggestion only"],"answer":1,"explanation":"Speed limits are the maximum permitted when conditions are ideal; any unsafe speed for current conditions is illegal.","source":{"chapter":2,"section":"Speed limit signs","anchor":"#speed-limit-signs","page":"27"}},{"id":"ch2-wrn-001","chapter":2,"category":"signs","question":"A chevron sign indicates…","options":["A sharp bend in the road","A hospital ahead","A stop ahead","A divided highway"],"answer":0,"explanation":"The chevron sign indicates a sharp bend in the road.","source":{"chapter":2,"section":"Warning signs","anchor":"#warning-signs","page":"35"}},{"id":"ch2-wrn-002","chapter":2,"category":"signs","question":"The recommended maximum speed through a curve shown by a warning sign applies…","options":["Under ideal driving conditions","In any weather","Only for trucks","Only at night"],"answer":0,"explanation":"The recommended maximum through the curve is for ideal driving conditions.","source":{"chapter":2,"section":"Warning signs","anchor":"#warning-signs","page":"33"}},{"id":"ch2-wrn-003","chapter":2,"category":"signs","question":"‘Bridge ices’ warning sign is most relevant…","options":["Only in construction zones","Because bridge decks freeze more readily than other road parts","Only for vehicles over 4,500 kg","At roundabouts"],"answer":1,"explanation":"Bridge decks and overpasses form slippery patches more readily than other road surfaces; the warning highlights that risk.","source":{"chapter":2,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"82"}},{"id":"ch2-wrn-004","chapter":2,"category":"signs","question":"A “Merging traffic” warning sign indicates…","options":["A passing lane ahead","Roadways ahead that join","A dead end","A railway crossing"],"answer":1,"explanation":"Merging traffic warns that roadways join ahead and traffic will enter your path of travel. It is part of the roadways-ahead-that-join series.","source":{"chapter":2,"section":"Warning signs","anchor":"#warning-signs","page":"34"}},{"id":"ch2-wrn-005","chapter":2,"category":"signs","question":"“Free flow (added lane)” warns that roadways ahead…","options":["Are side-by-side but do NOT join","Join with a stop","Are subject to tolls","Close at night"],"answer":0,"explanation":"A free-flow added lane means the roadways ahead run side-by-side but do not join — no merge conflict.","source":{"chapter":2,"section":"Warning signs","anchor":"#warning-signs","page":"34"}},{"id":"ch2-wrn-006","chapter":2,"category":"signs","question":"‘Narrow passage’ versus ‘road narrows both sides’: the narrow passage sign warns specifically of…","options":["Both sides narrowing equally","A single narrow point the road squeezes through","Construction narrowing","Bridge ices"],"answer":1,"explanation":"Narrow passage warns of a distinctly narrow section; road narrows both sides shows both edges moving inward.","source":{"chapter":2,"section":"Warning signs","anchor":"#warning-signs","page":"34"}},{"id":"ch2-wrn-007","chapter":2,"category":"signs","question":"A “Left lane ends” warning tells you that…","options":["The left lane will terminate — merge right","The left lane is reserved","The left lane exits","Traffic keeps left"],"answer":0,"explanation":"Left lane ends means that lane terminates ahead and traffic must merge to the continuing lane.","source":{"chapter":2,"section":"Warning signs","anchor":"#warning-signs","page":"35"}},{"id":"ch2-wrn-008","chapter":2,"category":"signs","question":"A sign warning “cyclists are allowed full use of the lane ahead” also tells you that…","options":["The lane is too narrow for side-by-side driving","Bicycles must dismount","Overtaking is mandatory","Only bikes may turn"],"answer":0,"explanation":"The shared-use single-line sign warns that cyclists may use the full lane and that the lane is too narrow for side-by-side driving.","source":{"chapter":2,"section":"Shared-use lanes","anchor":"#shared-use-lanes","page":"40"}},{"id":"ch2-zon-001","chapter":2,"category":"zones","question":"You are entering a school zone (sign with posted maximum). When is the limit in effect?","options":["24 hours daily","On school days only, at posted times","Every day 8:30 a.m.–sunset","Only when children are visible"],"answer":1,"explanation":"School zone restrictions apply on school days only, during the posted times; the default times are 8:00–9:30 a.m., 11:30 a.m.–1:30 p.m. and 3:00–4:30 p.m.","source":{"chapter":2,"section":"School zones and areas","anchor":"#school-zones-and-areas","page":"30"}},{"id":"ch2-zon-002","chapter":2,"category":"zones","question":"What are the default school zone time windows on school days?","options":["7:00–9:00 a.m., 11:00–1:00 p.m., 2:30–4:30 p.m.","8:00–9:30 a.m., 11:30 a.m.–1:30 p.m., 3:00–4:30 p.m.","8:30–11:30 a.m. and 1:00–4:00 p.m.","All school hours 9 a.m.–3 p.m."],"answer":1,"explanation":"The default school zone effect times are 8:00–9:30 a.m., 11:30 a.m.–1:30 p.m., and 3:00–4:30 p.m.; municipalities may vary them and post times beneath the sign.","source":{"chapter":2,"section":"School zones and areas","anchor":"#school-zones-and-areas","page":"30"}},{"id":"ch2-zon-003","chapter":2,"category":"zones","question":"The speed limit for both urban and rural school zones, unless posted otherwise, is…","options":["20 km/h","30 km/h","40 km/h","50 km/h"],"answer":1,"explanation":"The school zone speed limit is 30 km/h for both urban and rural school zones unless otherwise posted.","source":{"chapter":2,"section":"School zones and areas","anchor":"#school-zones-and-areas","page":"30"}},{"id":"ch2-zon-004","chapter":2,"category":"zones","question":"While a school zone is in effect you may not…","options":["Pass or attempt to pass another vehicle travelling in the same direction","Stop to let children cross","Drive under 50 km/h","Use your horn"],"answer":0,"explanation":"You are not permitted to pass or attempt to pass another vehicle travelling in the same direction within a school zone when it is in effect.","source":{"chapter":2,"section":"School zones and areas","anchor":"#school-zones-and-areas","page":"30"}},{"id":"ch2-zon-005","chapter":2,"category":"zones","question":"A school zone ends where a sign indicates…","options":["The next fuel station","A higher maximum speed or the end of the school zone","A railway crossing","A hospital"],"answer":1,"explanation":"The school zone ends where a sign indicates a higher maximum speed or the end of the school zone.","source":{"chapter":2,"section":"School zones and areas","anchor":"#school-zones-and-areas","page":"31"}},{"id":"ch2-zon-006","chapter":2,"category":"zones","question":"You approach a school sign WITHOUT a speed sign attached. This is a school…","options":["Zone — drive 30 km/h","Area — use caution, children may be walking or crossing","Bus stop only","Detour around schools"],"answer":1,"explanation":"A school sign without a posted speed indicates a school area: stay alert, children may be walking or crossing; no speed restriction applies.","source":{"chapter":2,"section":"School zones and areas","anchor":"#school-zones-and-areas","page":"31"}},{"id":"ch2-zon-007","chapter":2,"category":"zones","question":"Playground zone restrictions are in effect…","options":["On school days only","Every day from 8:30 a.m. to one hour after sunset","Only weekends","24 hours a day"],"answer":1,"explanation":"Playground restrictions apply every day from 8:30 a.m. to one hour after sunset (variations posted by municipalities).","source":{"chapter":2,"section":"Playground zones and areas","anchor":"#playground-zones-and-areas","page":"31"}},{"id":"ch2-zon-008","chapter":2,"category":"zones","question":"The default speed in a playground zone while the restriction is in effect is…","options":["20 km/h","30 km/h","30–50 km/h per bylaw","50 km/h"],"answer":1,"explanation":"The playground zone speed limit is 30 km/h unless posted otherwise.","source":{"chapter":2,"section":"Playground zones and areas","anchor":"#playground-zones-and-areas","page":"31"}},{"id":"ch2-zon-009","chapter":2,"category":"zones","question":"Passing another vehicle in the same direction inside an active playground zone is…","options":["Permitted with a signal","Permitted on the left","Not permitted","Permitted for small cars"],"answer":2,"explanation":"You are not permitted to pass or attempt to pass another vehicle travelling in the same direction within a playground zone when the restriction is in effect.","source":{"chapter":2,"section":"Playground zones and areas","anchor":"#playground-zones-and-areas","page":"31"}},{"id":"ch2-zon-010","chapter":2,"category":"zones","question":"A playground sign WITHOUT a speed sign means you are in a playground…","options":["Zone — 30 km/h applies","Area — children may be near, use caution","Bus stop","Construction area"],"answer":1,"explanation":"A playground sign without a speed sign is a playground area: stay cautious; no posted restriction applies.","source":{"chapter":2,"section":"Playground zones and areas","anchor":"#playground-zones-and-areas","page":"32"}},{"id":"ch2-zon-011","chapter":2,"category":"zones","question":"In a construction zone, the posted speed limit…","options":["Applies only while workers are present","Must be obeyed at all times","Is advisory only","Applies only to trucks"],"answer":1,"explanation":"The speed limit in construction zones must be obeyed at all times — hazards like bumps, fresh oil and loose gravel exist even when no workers are visible.","source":{"chapter":2,"section":"Construction zones","anchor":"#construction-zones","page":"37"}},{"id":"ch2-zon-012","chapter":2,"category":"zones","question":"When workers are present in a construction zone…","options":["Fines for speeding are doubled","Speed is raised to clear traffic","Only heavy vehicles pay fines","Parking is free"],"answer":0,"explanation":"If workers are present, fines for speeding in construction zones are doubled.","source":{"chapter":2,"section":"Construction zones","anchor":"#construction-zones","page":"37"}},{"id":"ch2-zon-013","chapter":2,"category":"zones","question":"In a construction zone you must…","options":["Obey the flag person’s signal and be prepared to slow down or stop","Follow the vehicle ahead regardless of speed","Use the shoulder to bypass slowing traffic","Maintain highway speed if no equipment is visible"],"answer":0,"explanation":"Obey the flag person, be prepared to slow down or stop as required.","source":{"chapter":2,"section":"Construction zones","anchor":"#construction-zones","page":"37"}},{"id":"ch2-zon-014","chapter":2,"category":"zones","question":"A sign reading “Stop at traffic lights ahead when yellow lights flashing” tells you that…","options":["The signals ahead are broken","When the yellow lights flash, signal changes are imminent or already red — be prepared to stop","Only fire trucks may pass","The lights are green until the flash stops"],"answer":1,"explanation":"When those yellow lights are flashing, the traffic control signal will turn from green to yellow or yellow to red, or is already red — prepare to stop.","source":{"chapter":2,"section":"Warning signs","anchor":"#warning-signs","page":"33"}},{"id":"ch3-basics-001","chapter":3,"category":"basics","question":"Before you take your place in the driver’s seat, the guide tells you to walk around your vehicle. What are you checking for?","options":["Children, pedestrians, tire condition, and anything in your vehicle’s path, including fluid leaks under the vehicle","Other drivers’ brake lights in the adjacent lane","The paint condition of the vehicles parked beside you","Whether your blind-spot mirrors are still angled correctly"],"answer":0,"explanation":"Walk around your vehicle before entering to check for children, pedestrians, and anything in your vehicle’s path, as well as tire inflation and fluid leaks.","source":{"chapter":3,"section":"Pre-drive basics","anchor":"#pre-drive-basics","page":"44"}},{"id":"ch3-basics-002","chapter":3,"category":"basics","question":"You are parked along a roadway and do your walk-around check. In which direction should you walk?","options":["Along the outer edge of the road, with your back to traffic","In a direction that allows you to see traffic coming toward you in the lane next to you","Down the centre of the roadway where you are most visible","It does not matter, as long as you can see your own vehicle"],"answer":1,"explanation":"When parked along a roadway, walk in a direction that allows you to see traffic coming toward you in the lane next to you.","source":{"chapter":3,"section":"Pre-drive basics","anchor":"#pre-drive-basics","page":"44"}},{"id":"ch3-basics-003","chapter":3,"category":"basics","question":"In the guide’s list of pre-driving habits, which step comes immediately after adjusting your head restraint?","options":["Fasten your seat belt","Adjust your seat and seat back","Lock your doors","Adjust your inside and outside rear view mirrors"],"answer":3,"explanation":"The order is: lock your doors, adjust your seat and seat back, adjust your head restraint, adjust your inside and outside rear view mirrors, then fasten your seat belt.","source":{"chapter":3,"section":"Pre-drive basics","anchor":"#pre-drive-basics","page":"44"}},{"id":"ch3-basics-004","chapter":3,"category":"basics","question":"Transport Canada recommends adjusting your seat so you are at least what distance from the steering wheel?","options":["25 centimetres (10 inches)","10 centimetres (four inches)","45 centimetres (18 inches)","50 centimetres (20 inches)"],"answer":0,"explanation":"Adjust your seat so you are at least 25 centimetres (10 inches) away from the steering wheel, the distance recommended by Transport Canada.","source":{"chapter":3,"section":"Adjust your seat and seat back","anchor":"pre-drive-basics","page":"46"}},{"id":"ch3-basics-005","chapter":3,"category":"basics","question":"If your vehicle has an adjustable head restraint, position it so that the centre of the restraint is:","options":["Level with your eyes","Level with the top of your shoulders","Level with the top of your ears","Level with the middle of the back of your head"],"answer":2,"explanation":"The centre of the head restraint should be level with the top of your ears.","source":{"chapter":3,"section":"Adjust your head restraint","anchor":"pre-drive-basics","page":"47"}},{"id":"ch3-basics-006","chapter":3,"category":"basics","question":"Your head restraint tilts. According to the guide, what should you do?","options":["Move it backward to make the ride more comfortable","Tilt it so it touches your shoulders","Move it forward to decrease the space between your head and the restraint","Remove it and store it in the trunk"],"answer":2,"explanation":"If the head restraint tilts, move it forward to decrease the space between your head and the restraint; less than 10 centimetres (four inches) is ideal.","source":{"chapter":3,"section":"Adjust your head restraint","anchor":"pre-drive-basics","page":"47"}},{"id":"ch3-basics-007","chapter":3,"category":"basics","question":"How should the inside rear view mirror be adjusted?","options":["Angled slightly downward to avoid headlight glare","Showing only the passenger-side door handle","So the rear window is framed within the mirror, showing as much behind you as possible","So both side windows are visible at once"],"answer":2,"explanation":"Adjust the inside rear view mirror to show as much behind you as possible by having the rear window framed within the mirror.","source":{"chapter":3,"section":"Adjust your inside and outside rear view mirrors","anchor":"pre-drive-basics","page":"47"}},{"id":"ch3-basics-008","chapter":3,"category":"basics","question":"The outside rear view mirrors should be adjusted to:","options":["Show no part of your own vehicle at all","Frame the entire sides of the vehicle","Reduce blind spots, with a small portion of your own vehicle visible closest to the vehicle","Angle slightly upward toward oncoming traffic"],"answer":2,"explanation":"Adjust the outside rear view mirrors to reduce blind spots; you should see your own vehicle in a small portion of the side view mirror closest to the vehicle.","source":{"chapter":3,"section":"Adjust your inside and outside rear view mirrors","anchor":"pre-drive-basics","page":"47"}},{"id":"ch3-basics-009","chapter":3,"category":"basics","question":"How must the shoulder portion of the seat belt be worn?","options":["Tucked behind your back so it does not wrinkle","Worn under your arm for comfort","Worn loosely so you can twist in your seat","Fit over your chest and shoulder — never tucked behind your back or under your arm"],"answer":3,"explanation":"The shoulder belt must fit over your chest and shoulder; do not tuck the shoulder belt behind your back or under your arm.","source":{"chapter":3,"section":"Fasten your seat belt","anchor":"pre-drive-basics","page":"46"}},{"id":"ch3-basics-010","chapter":3,"category":"basics","question":"You are parked at the curb and are ready to pull out. Just before you move, you must check:","options":["That traffic in the next lane is moving above the speed limit","That your intended path of travel is clear, and do a shoulder check to be sure your blind spots are clear","Only that your fuel gauge is above one quarter","The weather readout on the instrument panel"],"answer":1,"explanation":"When you are ready to go, check that your intended path of travel is clear, check your mirrors, and do a shoulder check to be sure your blind spots are clear.","source":{"chapter":3,"section":"Fasten your seat belt","anchor":"pre-drive-basics","page":"47"}},{"id":"ch3-basics-011","chapter":3,"category":"basics","question":"In a vehicle with an automatic transmission, the engine will start in which gear positions?","options":["Park and Neutral","Park and Drive","Reverse and Neutral","Drive and Second"],"answer":0,"explanation":"The engine starts in Park and in Neutral; it will not start in Reverse, Drive, the lower gears, or Overdrive.","source":{"chapter":3,"section":"Driving a vehicle with an automatic transmission","anchor":"#driving-a-vehicle-with-an-automatic-transmission","page":"48"}},{"id":"ch3-basics-012","chapter":3,"category":"basics","question":"You want to move an automatic-transmission selector from Park to Reverse. What must you do?","options":["Press the brake pedal and use the lock release button built into the gear selector","Turn the ignition key backward one click","Pump the accelerator twice before shifting","Press the clutch pedal to the floor"],"answer":0,"explanation":"The lock release must be used to move the gear selector from Park to Reverse or any forward gear while the brake pedal is pressed.","source":{"chapter":3,"section":"Driving a vehicle with an automatic transmission","anchor":"#driving-a-vehicle-with-an-automatic-transmission","page":"48"}},{"id":"ch3-basics-013","chapter":3,"category":"basics","question":"An automatic-transmission vehicle is placed in Reverse. Which lights are lit?","options":["The interior dome lights","The white or clear lights at the rear of the vehicle","Only the brake lights","The low-beam headlights"],"answer":1,"explanation":"When the vehicle is in reverse gear, the white or clear lights at the rear of the vehicle will be lit.","source":{"chapter":3,"section":"Driving a vehicle with an automatic transmission","anchor":"#driving-a-vehicle-with-an-automatic-transmission","page":"48"}},{"id":"ch3-basics-014","chapter":3,"category":"basics","question":"You are driving on slush, loose gravel, or a hill, where you need more power but less speed. What should you do?","options":["Shift into Overdrive","Stay in the Park position","Shift to a lower gear such as First or Second","Shift to Neutral and coast down"],"answer":2,"explanation":"Use Third, Second, or First gears when you require more power but less speed, such as going up or down hills or on slush, loose gravel, snow, sand, or ice.","source":{"chapter":3,"section":"Driving a vehicle with an automatic transmission","anchor":"#driving-a-vehicle-with-an-automatic-transmission","page":"48"}},{"id":"ch3-basics-015","chapter":3,"category":"basics","question":"When starting the engine of a vehicle with a manual (standard) transmission, you should:","options":["Crank the starter while the vehicle is in any gear","Have the gear shift lever in neutral and the clutch pedal pressed down completely","Leave the clutch pedal up and hold the brake","Hold the accelerator to the floor until the engine catches"],"answer":3,"explanation":"When starting the engine of a vehicle equipped with a manual transmission, the gear shift lever should be in neutral and the clutch pedal pressed down completely.","source":{"chapter":3,"section":"Driving a vehicle with a manual (standard) transmission","anchor":"#driving-a-vehicle-with-a-manual-standard-transmission","page":"49"}},{"id":"ch3-basics-016","chapter":3,"category":"basics","question":"As you slowly release the clutch pedal you feel the connection between the engine and transmission begin. What is this point called?","options":["The bite lock","The friction point","The engagement stop","The stall threshold"],"answer":1,"explanation":"The point where the connection between the engine and transmission begins to be felt is called the friction point; release the clutch slowly here to prevent stalling.","source":{"chapter":3,"section":"Driving a vehicle with a manual (standard) transmission","anchor":"#driving-a-vehicle-with-a-manual-standard-transmission","page":"49"}},{"id":"ch3-basics-017","chapter":3,"category":"basics","question":"What is “riding the clutch”?","options":["Leaving your foot resting on the clutch pedal after you finish changing gears, which causes extra wear on the clutch","Letting the clutch slip to keep the vehicle from rolling back on a hill","Pumping the clutch pedal on slippery roads","Holding the clutch down at a red light for more than a minute"],"answer":0,"explanation":"Riding the clutch means leaving your foot on the clutch pedal after changing gears unnecessarily; it causes extra wear on the clutch.","source":{"chapter":3,"section":"Driving a vehicle with a manual (standard) transmission","anchor":"#driving-a-vehicle-with-a-manual-standard-transmission","page":"49"}},{"id":"ch3-basics-018","chapter":3,"category":"basics","question":"How do you know at approximately what speeds to change gears in a standard-shift vehicle?","options":["The shifting pattern is painted on the floor mat","Your vehicle’s owner’s manual provides the approximate speeds","Change every 10 km/h, regardless of engine sound","The transmission changes gears on its own, like an automatic"],"answer":1,"explanation":"The vehicle’s owner’s manual will provide the approximate speeds at which you should change gears.","source":{"chapter":3,"section":"Driving a vehicle with a manual (standard) transmission","anchor":"#driving-a-vehicle-with-a-manual-standard-transmission","page":"49"}},{"id":"ch3-basics-019","chapter":3,"category":"basics","question":"For the best control of your vehicle, where should your hands be on the steering wheel?","options":["At 8 and 4 o’clock","At 12 and 6 o’clock","Crossed at the top, using whichever hand is free","At about the 9 and 3 o’clock positions"],"answer":3,"explanation":"Think of the steering wheel as a clock; place your left hand at about the 9 o’clock position and your right hand at about the 3 o’clock position.","source":{"chapter":3,"section":"Steering","anchor":"#steering","page":"50"}},{"id":"ch3-basics-020","chapter":3,"category":"basics","question":"If the steering wheel’s design makes the 9-and-3 position impossible, what does the guide recommend?","options":["One hand at 6 o’clock and one at the top","The 10 o’clock and 2 o’clock positions","Both hands at the bottom of the wheel","One hand resting on the horn button"],"answer":1,"explanation":"If 9 and 3 o’clock is not possible due to the wheel’s design, place your left hand at about the 10 o’clock position and your right hand at about the 2 o’clock position.","source":{"chapter":3,"section":"Steering","anchor":"#steering","page":"50"}},{"id":"ch3-basics-021","chapter":3,"category":"basics","question":"How should you steer when turning a corner?","options":["Using the hand-over-hand method","Palming the wheel with one hand at the bottom of the rim","Letting go of the wheel briefly between grips","Steering from the hub with the heel of one hand"],"answer":0,"explanation":"When turning a corner, steer using the hand-over-hand method; on the return you can also let the wheel slide through your hands while keeping contact.","source":{"chapter":3,"section":"Steering","anchor":"#steering","page":"50"}},{"id":"ch3-basics-022","chapter":3,"category":"basics","question":"Which of the following requires the use of your signal light?","options":["Only when other vehicles are close enough to see you","After you have completed the turn","Moving away from the curb or parking lane, turning left or right, and changing lanes","Only on highways and freeways"],"answer":2,"explanation":"You must use your signal light when moving away from the curb or parking lane, turning left or right, and changing lanes.","source":{"chapter":3,"section":"Signalling","anchor":"#signalling","page":"51"}},{"id":"ch3-basics-023","chapter":3,"category":"basics","question":"When do your brake lights warn other drivers that you are slowing or stopping?","options":["Only when the parking brake is engaged","As soon as you take your foot off the accelerator","Whenever you apply the brakes","Only when you downshift in a manual vehicle"],"answer":2,"explanation":"When you apply your brakes, your brake lights are activated to alert other drivers that you are slowing or stopping.","source":{"chapter":3,"section":"Signalling","anchor":"#signalling","page":"51"}},{"id":"ch3-basics-024","chapter":3,"category":"basics","question":"What does the guide warn about timing your turn signals?","options":["Signal too early or too late and you may confuse other drivers","Signal only once you are inside the intersection","Leave the signal flashing in case you change your mind","Use the hazard lights instead of turn signals in traffic"],"answer":0,"explanation":"Do not confuse other drivers by signaling too early or too late, and turn off your turn signal light if it does not turn off automatically.","source":{"chapter":3,"section":"Signalling","anchor":"#signalling","page":"51"}},{"id":"ch3-basics-025","chapter":3,"category":"basics","question":"Which three factors determine the time and distance it takes to stop?","options":["Signal timing, lane position, and vehicle weight","Perception time, reaction time, and braking time","Vision, hearing, and road surface","Tire pressure, fuel level, and engine power"],"answer":1,"explanation":"The three factors that determine stopping time and distance are perception time, reaction time, and braking time.","source":{"chapter":3,"section":"Stopping time and distance","anchor":"#stopping-time-and-distance","page":"52"}},{"id":"ch3-basics-026","chapter":3,"category":"basics","question":"Perception time is:","options":["The time it takes the tires to grip the pavement","The distance your vehicle coasts after you release the gas","How long the brake pedal takes to respond","How long it takes to recognize a situation and understand that you need to stop — about three-quarters of a second"],"answer":3,"explanation":"Perception time is how long it takes to recognize a situation and understand you need to stop; this can take about three-quarters of a second.","source":{"chapter":3,"section":"Stopping time and distance","anchor":"#stopping-time-and-distance","page":"52"}},{"id":"ch3-basics-027","chapter":3,"category":"basics","question":"Reaction time is:","options":["Moving your foot from the accelerator pedal to the brake pedal, which averages three-quarters of a second","A full two seconds, no matter the driver","The time traffic signals stay yellow","How quickly the engine responds to the accelerator"],"answer":0,"explanation":"Reaction time is how long it takes to respond to a situation by moving your foot from the accelerator pedal to the brake pedal; the average reaction time is three-quarters of a second.","source":{"chapter":3,"section":"Stopping time and distance","anchor":"#stopping-time-and-distance","page":"52"}},{"id":"ch3-basics-028","chapter":3,"category":"basics","question":"The minimum stopping-distance chart in the guide shows averages for what conditions?","options":["Any road, because braking distances never change","Wet pavement with worn brakes","Gravel roads at night","Smooth, dry pavement"],"answer":3,"explanation":"The stopping distances shown are averages for stopping on smooth, dry pavement.","source":{"chapter":3,"section":"Stopping time and distance","anchor":"#stopping-time-and-distance","page":"52"}},{"id":"ch3-basics-029","chapter":3,"category":"basics","question":"You must stop quickly. What is threshold braking?","options":["Pumping the pedal at every stop sign","Applying the brakes hard enough to lock all four wheels","Applying the brakes without locking the wheels, where braking efficiency is at its maximum","Using engine braking together with the parking brake"],"answer":2,"explanation":"Threshold braking is applying the brakes without locking the wheels — braking efficiency is at its maximum while still allowing you to steer.","source":{"chapter":3,"section":"Braking","anchor":"stopping-time-and-distance","page":"53"}},{"id":"ch3-basics-030","chapter":3,"category":"basics","question":"All reversing must be done at what speed?","options":["Up to 10 km/h","Roughly half the speed of surrounding traffic","Any speed you can still steer comfortably","A crawl or slow walking speed"],"answer":3,"explanation":"All reversing must be done at a crawl or slow walking speed, only when your path is clear of traffic, pedestrians, and obstacles.","source":{"chapter":3,"section":"Reversing","anchor":"#reversing","page":"53"}},{"id":"ch3-basics-031","chapter":3,"category":"basics","question":"Before reversing out of a driveway, what does the guide tell you to do?","options":["Sound your horn twice to warn pedestrians","Walk around the vehicle and check for possible dangers behind the vehicle","Trust the mirrors alone and back out quickly","Turn on the four-way flashers and reverse immediately"],"answer":1,"explanation":"Before reversing out of a driveway, walk around the vehicle and check for possible dangers behind the vehicle.","source":{"chapter":3,"section":"Reversing","anchor":"#reversing","page":"53"}},{"id":"ch3-basics-032","chapter":3,"category":"basics","question":"While reversing in a straight line, how much can you turn the steering wheel to correct the vehicle’s path?","options":["No more than a quarter turn, in the same direction you want the rear of the vehicle to go","A full turn, always to the left","Half a turn, in the opposite direction the rear should go","As much as needed in either direction, since your speed is low"],"answer":0,"explanation":"To correct your steering while reversing, turn the steering wheel no more than a quarter turn in the same direction that you want the rear of your vehicle to go.","source":{"chapter":3,"section":"Reversing","anchor":"#reversing","page":"53"}},{"id":"ch3-basics-033","chapter":3,"category":"basics","question":"Which of these reversing moves is illegal?","options":["Reversing at a crawl along a parking lane","Reversing out of a driveway into the nearest traffic lane, then going forward","Moving your vehicle in reverse into an intersection or a crosswalk","Reversing in a parking lot at walking speed"],"answer":2,"explanation":"It is illegal to move your vehicle in reverse into an intersection or a crosswalk; from a driveway you must reverse into the nearest traffic lane, not a second lane.","source":{"chapter":3,"section":"Reversing","anchor":"#reversing","page":"53"}},{"id":"ch3-parking-001","chapter":3,"category":"parking","question":"You are leaving a parallel parking space with a vehicle parked in front of you. Which sequence follows the guide?","options":["Check your mirrors, reverse while looking over your right shoulder until close to the vehicle behind you, then turn on the left signal","Turn on the right signal and drive straight out between the vehicles","Reverse across the lane while watching only the front bumper","Pull forward between the vehicles, then straighten out by reversing"],"answer":0,"explanation":"Check all mirrors, reverse while looking over your right shoulder until you are close to the vehicle behind without contact, turn on the left turn signal, then look over your left shoulder before moving forward.","source":{"chapter":3,"section":"Parallel parking","anchor":"parking","page":"54"}},{"id":"ch3-parking-002","chapter":3,"category":"parking","question":"While leaving a parallel parking spot, after reversing close to the vehicle behind, you move forward slowly about:","options":["Half a metre, steering sharply to the right","Five metres, steering gently to the right","About one metre (three feet), steering sharply all the way to the left","Two metres, steering left only halfway"],"answer":2,"explanation":"Move forward slowly about one metre (three feet) while steering sharply all the way to the left, then drive into the nearest travel lane when safe.","source":{"chapter":3,"section":"Parallel parking","anchor":"parking","page":"54"}},{"id":"ch3-parking-003","chapter":3,"category":"parking","question":"When entering a vehicle parked parallel to the curb on a two-way street, always approach:","options":["From the rear, watching traffic through the rear window","From the passenger side of the vehicle","From either side, whichever door is closer","From the front of the vehicle, looking for traffic in the nearest lane before opening the door"],"answer":3,"explanation":"When entering a vehicle parked parallel to the curb, always approach from the front of the vehicle and look for traffic passing in the nearest lane before opening the door.","source":{"chapter":3,"section":"Parallel parking","anchor":"parking","page":"54"}},{"id":"ch3-parking-004","chapter":3,"category":"parking","question":"Angle parking spaces in parking lots are usually on an angle of approximately:","options":["30 degrees to the traffic lane","45 degrees to the traffic lane","60 degrees to the curb line","90 degrees to the traffic lane"],"answer":1,"explanation":"Angle parking is most often used in parking lots, with spaces on an angle of approximately 45 degrees to the traffic lane.","source":{"chapter":3,"section":"Angle parking","anchor":"parking","page":"55"}},{"id":"ch3-parking-005","chapter":3,"category":"parking","question":"Entering an angle parking space on your right, you drive parallel to the curb, staying about:","options":["50 centimetres (20 inches) from the rear of the parked vehicle","One and a half metres (five feet) away from the rear of the parked vehicle","Three metres from the opposite curb","Half a metre from the rear of the parked vehicle"],"answer":1,"explanation":"Turn on your right signal, reduce speed, and remain about one and a half metres (five feet) away from the rear of the parked vehicle.","source":{"chapter":3,"section":"Angle parking","anchor":"parking","page":"55"}},{"id":"ch3-parking-006","chapter":3,"category":"parking","question":"When moving slowly into an angle parking stall, you stop when:","options":["The rear wheels reach the far stall line","Your front bumper touches the neighbouring vehicle’s corner","Your front wheel makes light contact with the curb or is within 50 centimetres (20 inches) of it","You are exactly halfway into the space with wheels still turned"],"answer":2,"explanation":"Keep moving slowly forward until the front wheel makes light contact with the curb or is within 50 centimetres (20 inches) of the curb.","source":{"chapter":3,"section":"Angle parking","anchor":"parking","page":"55"}},{"id":"ch3-parking-007","chapter":3,"category":"parking","question":"When leaving an angle parking space, the guide says to:","options":["Drive forward out of the space as soon as the way looks clear","Pull out briskly, since parking lots have no right-of-way rules","Reverse without checking behind, because you already have the right-of-way","Reverse carefully and slowly, yielding the right-of-way as you back out"],"answer":3,"explanation":"Reverse carefully and slowly, be sure there is nothing behind your vehicle, and yield the right-of-way as you back out.","source":{"chapter":3,"section":"Angle parking","anchor":"parking","page":"55"}},{"id":"ch3-parking-008","chapter":3,"category":"parking","question":"Perpendicular parking spaces are set at what angle to the curb?","options":["45 degrees","A 90-degree angle","60 degrees","An angle set by each parking lot"],"answer":1,"explanation":"Perpendicular parking spaces are at a 90 degree angle to the curb.","source":{"chapter":3,"section":"Perpendicular parking","anchor":"parking","page":"56"}},{"id":"ch3-parking-009","chapter":3,"category":"parking","question":"As you approach a perpendicular parking space, keep about how much space between your vehicle and the rear of the vehicle parked to your right?","options":["One metre (three feet)","Five metres (16 feet)","About two metres (six feet)","Half a metre (20 inches)"],"answer":2,"explanation":"Keep about two metres (six feet) between your vehicle and the rear of the vehicle parked to your right, and travel very slowly.","source":{"chapter":3,"section":"Perpendicular parking","anchor":"parking","page":"56"}},{"id":"ch3-parking-010","chapter":3,"category":"parking","question":"Why is it easier to enter a 90-degree parking stall on the left than on the right?","options":["You have more room to achieve the proper angle","Left-hand stalls are always wider than right-hand ones","You avoid the curb lane entirely","The guide does not say either entry is easier"],"answer":0,"explanation":"It is easier to enter a 90-degree stall on the left because you have more room to achieve the proper angle, similar to turning left onto another roadway.","source":{"chapter":3,"section":"Perpendicular parking","anchor":"parking","page":"56"}},{"id":"ch3-parking-011","chapter":3,"category":"parking","question":"Parking facing uphill on a street with a curb, you should:","options":["Turn the front wheels to the left (toward the centre of the road), then roll back slowly until the right front tire touches the curb","Turn the wheels right and roll forward onto the curb","Leave the wheels straight and rely on the park brake alone","Turn the wheels toward the edge of the road"],"answer":0,"explanation":"Uphill with a curb: turn the front wheels to the left toward the centre of the road and let the vehicle roll back until the right front tire is touching the curb.","source":{"chapter":3,"section":"Hill parking","anchor":"parking","page":"56"}},{"id":"ch3-parking-012","chapter":3,"category":"parking","question":"Parking facing uphill on a street without a curb, turn your front wheels:","options":["Left, toward the centre of the road","Right, toward the edge of the road","Straight ahead","Left only when driving a standard transmission"],"answer":1,"explanation":"Uphill without a curb, turn the front wheels to the right toward the edge of the road, so if the vehicle moves it will go off the road and not into traffic.","source":{"chapter":3,"section":"Hill parking","anchor":"parking","page":"56"}},{"id":"ch3-parking-013","chapter":3,"category":"parking","question":"Parking facing downhill (with or without a curb), turn your front wheels:","options":["Left, toward the centre of the road","Straight ahead with the park brake set","Right, toward the edge of the road","Left, unless you drive an automatic"],"answer":2,"explanation":"When parking facing downhill, always turn your front wheels to the right; with a curb, let the vehicle roll until the right front tire contacts the curb.","source":{"chapter":3,"section":"Hill parking","anchor":"parking","page":"56"}},{"id":"ch3-parking-014","chapter":3,"category":"parking","question":"To prevent a parked vehicle from rolling down a hill, you must:","options":["Set the park brake and place the transmission in Park (automatic) or low gear (manual)","Leave a standard transmission in neutral","Rely on the curb to block the front wheels","Turn off the engine, leaving the transmission in Drive"],"answer":0,"explanation":"Always set your park brake and place your transmission in park (automatic) or low gear (manual).","source":{"chapter":3,"section":"Hill parking","anchor":"parking","page":"56"}},{"id":"ch3-parking-015","chapter":3,"category":"parking","question":"How close to a stop sign or yield sign is parking prohibited?","options":["Within one and a half metres (five feet)","Within five metres (16 feet)","Within 15 metres (50 feet)","Within 60 metres (200 feet)"],"answer":1,"explanation":"Do not park within five metres (16 feet) of a stop sign or yield sign.","source":{"chapter":3,"section":"Do not park here","anchor":"parking","page":"57"}},{"id":"ch3-parking-016","chapter":3,"category":"parking","question":"Do not park within what distance of access to a garage, private roadway, or driveway?","options":["Within five metres (16 feet)","Within 15 metres (50 feet)","Within one metre (three feet)","Within one and a half metres (five feet)"],"answer":3,"explanation":"Do not park within one and a half metres (five feet) of access to a garage, private roadway, or driveway.","source":{"chapter":3,"section":"Do not park here","anchor":"parking","page":"57"}},{"id":"ch3-parking-017","chapter":3,"category":"parking","question":"On a roadway outside an urban area, do not park unless your vehicle can be seen for at least:","options":["30 metres (100 feet) along the roadway in both directions","60 metres (200 feet) along the roadway in both directions","150 metres along the roadway in one direction","One kilometre in both directions"],"answer":1,"explanation":"Outside urban areas, do not park unless there is a clear passage for other motor vehicles and your vehicle can be seen for 60 metres (200 feet) along the roadway in both directions.","source":{"chapter":3,"section":"Do not park here","anchor":"parking","page":"58"}},{"id":"ch4-intersections-001","chapter":4,"category":"intersections","question":"You have the right-of-way at an intersection. What does the guide still expect of you?","options":["Proceed without slowing, since other drivers must legally yield","Stop and let every other vehicle go first","Sound your horn to warn others of your right-of-way","Do everything you can to prevent a collision"],"answer":3,"explanation":"Right-of-way rules require one driver to yield; even if you have the right-of-way, you are still responsible to do everything you can to prevent a collision.","source":{"chapter":4,"section":"Right-of-way","anchor":"#right-of-way","page":"59"}},{"id":"ch4-intersections-002","chapter":4,"category":"intersections","question":"A peace officer is directing traffic in a way that contradicts the traffic signals at an intersection. You must:","options":["Obey the traffic signals instead","Follow the directions given by the peace officer","Stop and wait until the officer leaves the intersection","Follow the vehicle ahead of you"],"answer":1,"explanation":"Directions given by a peace officer or police officer must be followed over traffic signs or signals.","source":{"chapter":4,"section":"Intersections","anchor":"#intersections","page":"59"}},{"id":"ch4-intersections-003","chapter":4,"category":"intersections","question":"What must you do at a stop sign?","options":["Roll through slowly after reducing your speed","Stop only when you can see cross traffic approaching","Come to a complete stop, check the intersection carefully for pedestrians and other traffic, then proceed when safe","Slow to half the posted speed limit and continue if the way looks open"],"answer":2,"explanation":"A stop sign requires your vehicle to come to a complete stop; after stopping, check carefully for pedestrians and other traffic, and proceed when safe.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"60"}},{"id":"ch4-intersections-004","chapter":4,"category":"intersections","question":"There is a painted stop line before a marked crosswalk at a stop sign. Where do you stop?","options":["Beside the crosswalk, where you can see best","Just inside the intersection","At the nearest property line past the corner","Before the stop line"],"answer":3,"explanation":"Where a stop line has been marked, bring your vehicle to a complete stop before the stop line; with no stop line, stop before the marked crosswalk.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"60"}},{"id":"ch4-intersections-005","chapter":4,"category":"intersections","question":"At a three- or four-way stop (a “courtesy corner”), whom does courtesy allow to proceed first?","options":["The vehicle that arrived first","The largest vehicle","Any vehicle turning left","The vehicle travelling fastest"],"answer":0,"explanation":"At courtesy corners, courtesy is to allow the vehicle that arrived first to proceed first; all drivers must use courtesy and caution.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"61"}},{"id":"ch4-intersections-006","chapter":4,"category":"intersections","question":"Two vehicles arrive at a four-way stop at exactly the same time. Courtesy allows to proceed first:","options":["The vehicle on the left","The vehicle that intends to turn left","The larger vehicle","The vehicle on the right"],"answer":3,"explanation":"If two vehicles arrive at the same time, courtesy allows the vehicle on the right to proceed first.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"61"}},{"id":"ch4-intersections-007","chapter":4,"category":"intersections","question":"As you approach a yield sign, you must:","options":["Reduce speed as you near the intersection and be prepared to stop","Always come to a complete stop, even with no traffic present","Maintain your speed; a yield sign simply confirms your right-of-way","Sound your horn and continue at speed"],"answer":0,"explanation":"When approaching a yield sign, reduce speed as you near the intersection and be prepared to stop; if nothing requires you to yield, you may proceed without a complete stop.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"61"}},{"id":"ch4-intersections-008","chapter":4,"category":"intersections","question":"At an intersection with no traffic signs and no signal lights, you must yield the right-of-way to:","options":["The vehicle already moving the fastest","The vehicle on your left","The vehicle on your right","The larger vehicle"],"answer":2,"explanation":"At intersections not controlled by signs or signals, you must yield the right-of-way to a vehicle on your right.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"62"}},{"id":"ch4-intersections-009","chapter":4,"category":"intersections","question":"When exiting from a service road, alley, or parking lot onto a main street, you must:","options":["Roll through if no vehicles are visible","Accelerate to merge into the nearest gap in traffic","Stop before any sidewalk crossing, stop before entering the main street, and yield to pedestrians","Signal right and proceed straight across"],"answer":2,"explanation":"When exiting from service roads, alleys, parking lots, and driveways, you must stop before any sidewalk crossing, stop before entering a main street, and yield to pedestrians.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"62"}},{"id":"ch4-intersections-010","chapter":4,"category":"intersections","question":"At a T intersection with no signs or signals, who has the right-of-way?","options":["The driver on the right","The driver travelling straight through, because they keep the through lane","The driver on the left","Neither driver; both must stop"],"answer":0,"explanation":"At a T intersection without signs or signals there are no traffic controls, so the driver on the right has the right-of-way; be careful in case the through driver incorrectly assumes the right-of-way.","source":{"chapter":4,"section":"Intersections controlled by signs","anchor":"intersections","page":"62"}},{"id":"ch4-intersections-011","chapter":4,"category":"intersections","question":"Traffic ahead of you is delayed and the space beyond the intersection is blocked. What does the guide say to do?","options":["Enter and wait in the intersection so you keep your place in line","Do not enter the intersection until you can completely clear it and the crosswalk on the other side","Enter halfway so oncoming traffic cannot cut in ahead of you","Stop, reverse a step, and hold your place from the curb"],"answer":1,"explanation":"Do not enter an intersection until you are able to clear it completely; if traffic is delayed, wait until you can clear the intersection and crosswalk on the other side.","source":{"chapter":4,"section":"Keep intersections clear","anchor":"#keep-intersections-clear","page":"62"}},{"id":"ch4-intersections-012","chapter":4,"category":"intersections","question":"Traffic circles and roundabouts always circulate:","options":["Clockwise around the centre island","Counterclockwise around a centre island","Either way, at the driver’s choice","Clockwise, except outside urban areas"],"answer":1,"explanation":"In traffic circles and roundabouts, traffic always circulates in a counterclockwise direction around a centre island.","source":{"chapter":4,"section":"Keep intersections clear","anchor":"#keep-intersections-clear","page":"62"}},{"id":"ch4-intersections-013","chapter":4,"category":"intersections","question":"Before entering a traffic circle or roundabout, drivers must yield to:","options":["Traffic already in the circle","Traffic waiting to enter on your left","Pedestrians approaching from directly behind","Vehicles only on the far side of the circle"],"answer":0,"explanation":"Vehicles entering the intersection must yield to traffic already in the circle.","source":{"chapter":4,"section":"Keep intersections clear","anchor":"#keep-intersections-clear","page":"62"}},{"id":"ch4-intersections-014","chapter":4,"category":"intersections","question":"How does a roundabout differ from a traffic circle?","options":["The roundabout’s centre island is larger, allowing higher speeds","A roundabout’s centre island is smaller, with a tighter curve to encourage lower speeds","A traffic circle has no centre island","There is no difference except the colour of the pavement"],"answer":1,"explanation":"The centre island of a roundabout is smaller than a traffic circle’s and is designed with a tighter curve to encourage lower speeds; roundabouts may have a sloped curb for larger commercial vehicles.","source":{"chapter":4,"section":"Keep intersections clear","anchor":"#keep-intersections-clear","page":"62"}},{"id":"ch4-intersections-015","chapter":4,"category":"intersections","question":"Once inside a one-lane circular intersection, drivers must:","options":["Signal left for their entire time in the circle","Activate the right signal when preparing to exit","Signal only if other traffic is present","Use the hazard lights until they exit"],"answer":1,"explanation":"Once in the circle, drivers must activate the right signal when preparing to exit.","source":{"chapter":4,"section":"Keep intersections clear","anchor":"#keep-intersections-clear","page":"63"}},{"id":"ch4-intersections-016","chapter":4,"category":"intersections","question":"You intend to leave at the third exit of a roundabout. When should your right signal go on?","options":["As you enter the circle, even for a far exit","As you pass your intended exit","After you pass the exit that is before your intended exit","Only after you have completely cleared the circle"],"answer":2,"explanation":"Always wait to activate your right turn signal until after passing the exit that is before your intended exit, to show you intend to leave at the next exit.","source":{"chapter":4,"section":"Keep intersections clear","anchor":"#keep-intersections-clear","page":"63"}},{"id":"ch4-intersections-017","chapter":4,"category":"intersections","question":"You will take the first available exit from a circle. How do you signal?","options":["Use the right signal as you approach and leave it on until you have exited the circle","Signal left on approach, then right at the exit","No signal is needed for the first exit","Signal right only after you clear the exit"],"answer":0,"explanation":"When you intend to exit at the first available exit, use your right signal as you approach and leave it on until you have exited the circle.","source":{"chapter":4,"section":"Keep intersections clear","anchor":"#keep-intersections-clear","page":"63"}},{"id":"ch4-intersections-018","chapter":4,"category":"intersections","question":"In a two-lane traffic circle, a driver entering from the right lane must:","options":["Exit in whichever lane is open","Move to the left lane after entering","Cut across to the outer lane before exiting","Stay in the right lane while in the circle and exit using the right lane"],"answer":3,"explanation":"Drivers entering from the right lane must enter when it is safe, stay in the right lane while in the circle, and exit using the right lane.","source":{"chapter":4,"section":"Two-lane traffic circle / roundabout","anchor":"traffic-circles-and-roundabouts","page":"64"}},{"id":"ch4-intersections-019","chapter":4,"category":"intersections","question":"Who should use the left lane to enter and exit a two-lane roundabout?","options":["Drivers taking the first exit","Drivers planning to travel past the first exit","Trucks and buses only","Anyone, as long as they merge back before the island"],"answer":1,"explanation":"Drivers planning to travel past the first exit should use the left lane to enter and exit, staying in the left lane while in the circle.","source":{"chapter":4,"section":"Two-lane traffic circle / roundabout","anchor":"traffic-circles-and-roundabouts","page":"64"}},{"id":"ch4-intersections-020","chapter":4,"category":"intersections","question":"While in a two-lane roundabout, drivers on the right must:","options":["Take precedence over the inner-lane traffic","Yield to the drivers on the left","Stop before the centre island on each pass","Yield only to traffic entering the circle"],"answer":1,"explanation":"While in the circle, the drivers on the right must yield to the drivers on the left; use caution when exiting across the right (outside) lane.","source":{"chapter":4,"section":"Two-lane traffic circle / roundabout","anchor":"traffic-circles-and-roundabouts","page":"64"}},{"id":"ch4-intersections-021","chapter":4,"category":"intersections","question":"What does the guide say about changing lanes in a roundabout?","options":["Move to the outside lane just before you exit","Change lanes midway for the shortest path","Do not change lanes in the circle","Merge across when a gap appears"],"answer":2,"explanation":"Do not change lanes in the circle.","source":{"chapter":4,"section":"Two-lane traffic circle / roundabout","anchor":"traffic-circles-and-roundabouts","page":"64"}},{"id":"ch4-intersections-022","chapter":4,"category":"intersections","question":"You are exiting a two-lane roundabout from the left lane. When do you signal right?","options":["When you begin your approach to the circle","No signal is required when exiting from the left lane","When you pass the exit that is one before the exit you will use","After you have fully cleared the circle"],"answer":2,"explanation":"When you exit using the left lane, use your right signal when you pass the exit that is one before the exit you will use.","source":{"chapter":4,"section":"Two-lane traffic circle / roundabout","anchor":"traffic-circles-and-roundabouts","page":"65"}},{"id":"ch4-intersections-023","chapter":4,"category":"intersections","question":"You are in a roundabout and cannot stop or exit safely at your intended exit. The guide says to:","options":["Stop in the circle until traffic clears","Reverse back to the missed exit","Stay in your lane and travel around the circle again","Cross the right lane slowly, flashing your lights"],"answer":2,"explanation":"If you cannot stop or exit safely, stay in your lane and travel around the circle/roundabout again.","source":{"chapter":4,"section":"Two-lane traffic circle / roundabout","anchor":"traffic-circles-and-roundabouts","page":"65"}},{"id":"ch4-intersections-024","chapter":4,"category":"intersections","question":"For a right or left turn, you should be in your proper turning lane at least:","options":["15 metres (50 feet) before the intersection","5 metres (16 feet) before the intersection","30 metres before the crosswalk","One full block before the turn"],"answer":0,"explanation":"Check your mirrors, shoulder check, signal and change lanes when it is safe; be in your proper turning lane at least 15 metres (50 feet) before the intersection.","source":{"chapter":4,"section":"Right turns","anchor":"turning","page":"66"}},{"id":"ch4-intersections-025","chapter":4,"category":"intersections","question":"Making a right turn from a two-way road onto a two-way road, stay centred in the turning lane, not more than:","options":["One metre (three feet) away from the curb or road’s edge","Half a metre (20 inches) from the curb","As far right as the parked vehicles allow","One metre from the centre line"],"answer":0,"explanation":"Stay centred in the turning lane, not more than one metre (three feet) away from the curb or road’s edge, maintaining this distance as you approach, turn, and leave.","source":{"chapter":4,"section":"Right turns","anchor":"turning","page":"66"}},{"id":"ch4-intersections-026","chapter":4,"category":"intersections","question":"You are about to turn right. Before turning, in addition to yielding to pedestrians and cross-street vehicles, you should check over your right shoulder for:","options":["Traffic in the oncoming lanes only","The posted speed limit on the cross street","Parked vehicles past the intersection","Cyclists and pedestrians approaching the intersection"],"answer":3,"explanation":"Before turning, assess the street you are turning onto and check over your right shoulder for cyclists and pedestrians approaching the intersection.","source":{"chapter":4,"section":"Right turns","anchor":"turning","page":"66"}},{"id":"ch4-intersections-027","chapter":4,"category":"intersections","question":"Turning right, you see a parked car close to the corner of the street you are entering. Where should you complete the turn?","options":["Swing wide into the lane farthest from the curb","Squeeze into the curb lane past the parked car","Straddle two lanes until you are past the obstruction","Turn into the first available lane to the left of the parked vehicle, then move into the clear lane when safe"],"answer":3,"explanation":"If a parked vehicle or obstruction is close to the corner, turn into the first available lane to the left of the parked vehicle; when the lane is clear, turn directly into it.","source":{"chapter":4,"section":"Right turns","anchor":"turning","page":"66"}},{"id":"ch4-intersections-028","chapter":4,"category":"intersections","question":"Under what condition may you turn right on a red light?","options":["After a complete stop at the proper stopping point (stop line or crosswalk), unless prohibited by a sign","After slowing and checking, without coming to a complete stop","Only while waiting for a green arrow","Only at intersections with more than one turn lane"],"answer":0,"explanation":"Unless prohibited by a sign, you may turn right on a red light after you come to a complete stop at the proper stopping point (stop line or crosswalk).","source":{"chapter":4,"section":"Right turns","anchor":"turning","page":"67"}},{"id":"ch4-intersections-029","chapter":4,"category":"intersections","question":"You must stop inside the intersection while waiting to complete a left turn. What does the guide say to do?","options":["Angle the wheels left so you can clear quickly when the light changes","Pull as far left as you can, past the yellow line","Keep your front wheels pointed straight ahead, staying to the right of the yellow line","Turn the wheels right in case you are struck from behind"],"answer":2,"explanation":"Stay to the right of the yellow line and keep your front wheels pointed straight ahead; this prevents the vehicle from being pushed into oncoming traffic if hit from behind.","source":{"chapter":4,"section":"Left turns","anchor":"turning","page":"67"}},{"id":"ch4-intersections-030","chapter":4,"category":"intersections","question":"Approaching a green light to turn left, there is only room for one vehicle in the intersection. You should:","options":["Enter beside the vehicle ahead to keep traffic moving","Sound your horn and move up alongside it","Remain behind the crosswalk until the vehicle ahead of you clears the intersection","Straddle the crosswalk so oncoming traffic can see you"],"answer":2,"explanation":"Remain behind the crosswalk if there is only room for one vehicle ahead of your lane in the intersection.","source":{"chapter":4,"section":"Left turns","anchor":"turning","page":"67"}},{"id":"ch4-intersections-031","chapter":4,"category":"intersections","question":"Turning left from a two-way road with a single left turn lane, how do you complete the turn?","options":["Into the lane closest to the oncoming side of the new road","Across two lanes to reach the curb lane","Into the leftmost lane, hugging the centre of the new road","By driving to the right side of the yellow line of the road you have entered"],"answer":3,"explanation":"When it is safe, turn left and complete the turn by driving to the right side of the yellow line of the road you have entered.","source":{"chapter":4,"section":"Left turns","anchor":"turning","page":"67"}},{"id":"ch4-intersections-032","chapter":4,"category":"intersections","question":"Before turning left off a two-lane highway, what should you do?","options":["Check the rear view mirror only","Do a shoulder check to the left to be sure you are not being passed by another vehicle","Move onto the shoulder first to widen the turn","Speed up to stay ahead of any vehicle passing you"],"answer":1,"explanation":"Before turning left off a two-lane highway, do a shoulder check to the left to be sure you are not being passed by another vehicle on your left.","source":{"chapter":4,"section":"Left turns","anchor":"turning","page":"67"}},{"id":"ch4-intersections-033","chapter":4,"category":"intersections","question":"When may you turn left from a one-way street onto another one-way street on a red light?","options":["Never — a red light prohibits all turns across the intersection","Only when a police officer signals you through","Only from the centre lane of the one-way street","After a complete stop at the proper stopping point, unless signs prohibit turning, and the turn can be completed safely"],"answer":3,"explanation":"When the light is red and no signs prohibit turning, you may turn left from a one-way onto another one-way after a complete stop at the proper stopping point; this also applies to dual lane turns.","source":{"chapter":4,"section":"Left turns","anchor":"turning","page":"67"}},{"id":"ch4-intersections-034","chapter":4,"category":"intersections","question":"Where dual lane turns are indicated, how do you make the turn?","options":["Approach in one of the marked lanes and turn into the corresponding lane","Use whichever marked lane has the shorter line of vehicles","Turn from the outer marked lane into the inner marked lane","Enter the two-way left turn lane, then join the marked lanes"],"answer":0,"explanation":"When dual lane turns are indicated by pavement markings or signs, approach the intersection in one of the marked lanes and turn into the corresponding lane.","source":{"chapter":4,"section":"Dual lane turns","anchor":"turning-lanes","page":"68"}},{"id":"ch4-intersections-035","chapter":4,"category":"intersections","question":"What does the guide warn about dual lane turns?","options":["Change lanes midway through the turn to reach your exit sooner","Swing wide into the far lane, then correct back to your lane","Drift toward the centre line if the inside vehicle hesitates","Never swing wide or change lanes, as another vehicle could be turning beside you"],"answer":3,"explanation":"Dual lane turns can only be made where indicated; never swing wide or change lanes because another vehicle could be turning beside you and may swing wide into your lane.","source":{"chapter":4,"section":"Dual lane turns","anchor":"turning-lanes","page":"68"}},{"id":"ch4-intersections-036","chapter":4,"category":"intersections","question":"After a dual turn, two turn lanes converge into one. What does the guide say?","options":["Both drivers must merge at the same time as the lanes meet","The driver in the lane that ends must change to the available lane, following the proper steps for a lane change","The vehicle on the right always has the right-of-way","The faster vehicle decides the merge point"],"answer":1,"explanation":"After completing a turn, dual turn lanes may converge into one lane; the driver in the lane that ends must change to the available lane by following the proper steps for a lane change.","source":{"chapter":4,"section":"Dual lane turns","anchor":"turning-lanes","page":"68"}},{"id":"ch4-intersections-037","chapter":4,"category":"intersections","question":"A two-way left turn lane is marked between opposing traffic. How do you use it?","options":["Use the lane as a passing lane when traffic is light","Enter the shared turn lane close to where you will turn; crossing the solid yellow line to enter is permissible","Enter the lane two blocks early to save time at the light","Cross the broken yellow line at any point along the block"],"answer":1,"explanation":"In a two-way left turn lane, vehicles from each direction turn left using the same lane; it is permissible to cross the solid yellow line to enter, and you should only enter close to where you will be turning.","source":{"chapter":4,"section":"Two-way left turn lanes","anchor":"turning-lanes","page":"69"}},{"id":"ch4-intersections-038","chapter":4,"category":"intersections","question":"U-turns are not permitted:","options":["On any street with a raised concrete median","On a straight rural road where the driver of another vehicle can clearly see you","At an intersection controlled by a traffic control signal, unless permitted by a traffic control device","On curves outside urban areas whenever visibility exceeds 150 metres"],"answer":2,"explanation":"U-turns are not permitted at an intersection controlled by a traffic control signal (traffic lights) unless permitted by a traffic control device, or where a sign prohibits U-turns.","source":{"chapter":4,"section":"U-turns","anchor":"#u-turns","page":"69"}},{"id":"ch4-intersections-039","chapter":4,"category":"intersections","question":"In urban areas, U-turns are not permitted:","options":["On a roadway between intersections, at an alley intersection, or at an intersection with access to a public or private parking lot the public can access","Anywhere within blocks that have traffic lights","On any street with painted lane lines","Near schools during school hours"],"answer":0,"explanation":"In urban areas U-turns are not permitted on a roadway between intersections, at an alley intersection, or at an intersection where one or more of the roadways is an access to a public or private parking lot the public can access.","source":{"chapter":4,"section":"U-turns","anchor":"#u-turns","page":"69"}},{"id":"ch4-intersections-040","chapter":4,"category":"intersections","question":"Outside urban areas (rural), U-turns are not permitted:","options":["On straight, level stretches of rural highway","On a curve, or on an approach to or near the crest of a hill within 150 metres","On any gravel road, day or night","Anywhere visibility is less than 100 metres"],"answer":1,"explanation":"Outside urban areas, U-turns are not permitted on a curve, or on an approach to or near the crest of a hill where the driver of another vehicle cannot see you within 150 metres approaching from either direction.","source":{"chapter":4,"section":"U-turns","anchor":"#u-turns","page":"69"}},{"id":"ch5-high-001","chapter":5,"category":"highways","question":"When a roadway is divided into lanes by visible marking lines on the road surface, where should you drive?","options":["Slightly to the left of the centre of your lane","In the centre of your lane","As close as possible to the line dividing you from the next lane","Anywhere within your lane, because the markings are only a guide"],"answer":1,"explanation":"When a roadway has been divided into lanes by visible marking lines on the road surface, you should drive in the centre of your lane.","source":{"chapter":5,"section":"Lane selection and position in your lane","anchor":"#lane-selection-and-position-in-your-lane","page":"70"}},{"id":"ch5-high-002","chapter":5,"category":"highways","question":"How should you manage lane changes on a major roadway?","options":["Ask the driver behind you to slow down while you move over","Plan ahead and do not leave lane changes to the last minute","Wait until you are beside your exit, then move over quickly","Change lanes only when your exit sign first becomes visible"],"answer":1,"explanation":"Choose the lane that best meets your needs for safety and getting to your destination. Plan ahead; do not leave lane changes to the last minute.","source":{"chapter":5,"section":"Lane selection and position in your lane","anchor":"#lane-selection-and-position-in-your-lane","page":"70"}},{"id":"ch5-high-003","chapter":5,"category":"highways","question":"What is a blind spot?","options":["A glare on your mirrors that temporarily blocks your view","The area behind your vehicle shown in the inside rear view mirror","The area right beside and slightly behind your vehicle in the lanes next to you, which your mirrors cannot show","The area in front of your hood where you cannot see the pavement"],"answer":2,"explanation":"Your mirrors will not show everything to the sides or what is right beside and slightly behind in the lanes next to you. These are blind spots.","source":{"chapter":5,"section":"Blind spots","anchor":"lane-selection-and-position-in-your-lane","page":"70"}},{"id":"ch5-high-004","chapter":5,"category":"highways","question":"How do you shoulder check properly before changing lanes?","options":["Look only in your inside rear view mirror and pause there","Quickly glance back over your shoulder through the rear side windows in the direction you intend to move","Slow down so the driver behind you can see your intent","Stare into your blind spot for several seconds until it is clear"],"answer":1,"explanation":"To shoulder check properly, quickly glance back over your shoulder through the rear side windows in the direction you intend to move. This shows you the area you cannot see in your mirrors.","source":{"chapter":5,"section":"Changing lanes","anchor":"lane-selection-and-position-in-your-lane","page":"71"}},{"id":"ch5-high-005","chapter":5,"category":"highways","question":"Your vehicle has no backseat side windows or back rear window. What do you need to use for lane changes?","options":["Outside mirrors with an attached convex mirror","Camera displays with the mirrors turned off","Convex mirrors attached to your inside rear view mirror","Only your inside rear view mirror, adjusted outward"],"answer":0,"explanation":"If you do not have backseat side windows or a back rear window, you need to use your outside mirrors with an attached convex mirror.","source":{"chapter":5,"section":"Changing lanes","anchor":"lane-selection-and-position-in-your-lane","page":"71"}},{"id":"ch5-high-006","chapter":5,"category":"highways","question":"You have checked traffic, signalled and confirmed the lane change is safe. How should you make the move?","options":["Maintain your speed as much as possible while changing lanes","Accelerate well above the limit to complete it faster","Slow to at least half your previous speed","Brake gently to warn following traffic"],"answer":0,"explanation":"If safe, change lanes while maintaining your speed as much as possible, and ensure your signal light is turned off.","source":{"chapter":5,"section":"Changing lanes","anchor":"lane-selection-and-position-in-your-lane","page":"71"}},{"id":"ch5-high-007","chapter":5,"category":"highways","question":"On a multi-lane highway, where should slower traffic generally travel?","options":["In whichever lane has the least traffic at the time","In the left lane, to move with the flow of traffic","In the middle lane so other vehicles can pass on both sides","In the travel lane furthest to the right, unless needing the left lane to turn left"],"answer":3,"explanation":"Slower traffic should use the travel lane furthest to the right, leaving the left lane available for other drivers to use for passing.","source":{"chapter":5,"section":"Passing on a multi-lane highway","anchor":"passing","page":"71"}},{"id":"ch5-high-008","chapter":5,"category":"highways","question":"What is a passing lane?","options":["A lane where you must match the speed of the vehicles ahead","The lane used for slow moving maintenance equipment","The lane reserved for emergency vehicles during an incident","A lane added to a highway to allow passing, often in the mountains"],"answer":3,"explanation":"A passing lane is a lane added to a highway to allow passing, often in the mountains. Slower vehicles move into the passing lane to the right.","source":{"chapter":5,"section":"Passing lanes","anchor":"passing","page":"71"}},{"id":"ch5-high-009","chapter":5,"category":"highways","question":"A passing lane is ending ahead. What must drivers in the right lane do?","options":["Merge safely with traffic to the left","Stop until there is a large gap in the left lane","Speed up to pass vehicles in the left lane before it ends","Continue straight and use the shoulder to rejoin later"],"answer":0,"explanation":"When approaching the end of the passing lane, drivers in the right lane must merge safely with traffic to the left, and drivers in the left lane must cooperate.","source":{"chapter":5,"section":"Passing lanes","anchor":"passing","page":"71"}},{"id":"ch5-high-010","chapter":5,"category":"highways","question":"Why must passing on a two-lane highway be done only where legal, when necessary and with extreme caution?","options":["Passing on two-lane highways is never allowed","Errors in judgement can result in head-on collisions, which often cause fatalities","Oncoming traffic always has the right-of-way","It is only dangerous for the vehicle being passed"],"answer":1,"explanation":"On a two-lane highway, passing can be difficult and dangerous; errors in judgement can result in head-on collisions, and these often cause fatalities.","source":{"chapter":5,"section":"Passing on a two-lane highway","anchor":"passing","page":"71"}},{"id":"ch5-high-011","chapter":5,"category":"highways","question":"Before you attempt to pass on a two-lane highway, what should your shoulder check to the left look for?","options":["Cyclists riding along the right shoulder","The rear edge of the vehicle you intend to pass","Traffic entering the highway from a service road","Vehicles that may be passing you on the left, which may be in your blind spot"],"answer":3,"explanation":"Do a shoulder check to the left to look for vehicles that may be passing you on the left, because these vehicles may be in your blind spot.","source":{"chapter":5,"section":"Passing on a two-lane highway","anchor":"passing","page":"71"}},{"id":"ch5-high-012","chapter":5,"category":"highways","question":"May you exceed the speed limit slightly to pass a vehicle faster on a two-lane highway?","options":["Yes, if the driver being passed pulls to the right","No, it is illegal to exceed the speed limit when passing another vehicle","Yes, but only on highways and never in towns","Yes, as long as you signal first"],"answer":1,"explanation":"It is illegal to exceed the speed limit when passing another vehicle.","source":{"chapter":5,"section":"Passing on a two-lane highway","anchor":"passing","page":"71"}},{"id":"ch5-high-013","chapter":5,"category":"highways","question":"When should you start returning to your original lane after passing on a two-lane highway?","options":["Only when the oncoming lane has been clear for one minute","As soon as your front bumper draws level with the passed vehicle","Once the vehicle you have passed is visible in your inside rear view mirror","Immediately after the passed driver signals you back"],"answer":2,"explanation":"Once the vehicle you have passed is visible in your inside rear view mirror, do a shoulder check to the right, turn on your right signal light, and return to your original lane while maintaining your speed.","source":{"chapter":5,"section":"Passing on a two-lane highway","anchor":"passing","page":"71"}},{"id":"ch5-high-014","chapter":5,"category":"highways","question":"How should you help a driver who is passing you on a two-lane highway?","options":["Tap your brakes to remind them of the speed limit","Accelerate so they finish passing sooner","Stay in your lane and move to the right side of your lane to give the other driver a better view of the road ahead","Move fully onto the shoulder to let them by"],"answer":2,"explanation":"When being passed on a two-lane highway, help the driver passing you by staying in your lane and moving to the right side of your lane.","source":{"chapter":5,"section":"Passing on a two-lane highway","anchor":"passing","page":"71"}},{"id":"ch5-high-015","chapter":5,"category":"highways","question":"There is a solid yellow line on your side of the centre line. What does this mean?","options":["You may pass if the road ahead is straight","You may pass only if the line is worn or faded","Do not pass","Pass only large vehicles slowly"],"answer":2,"explanation":"Do not pass when a solid yellow line is on your side of the centre line, when a sign indicates a no passing zone, or when oncoming vehicles are too close.","source":{"chapter":5,"section":"When is it illegal to pass another vehicle?","anchor":"passing","page":"72"}},{"id":"ch5-high-016","chapter":5,"category":"highways","question":"A vehicle is stopped to allow a pedestrian to cross at a marked or unmarked crosswalk. May you pass it?","options":["Yes, if you sound your horn first","No, passing a stopped vehicle at a crosswalk is illegal","Yes, passing on the left is always permitted at crosswalks","Yes, as long as the pedestrian is still on the curb"],"answer":1,"explanation":"Do not pass another vehicle that is stopped to allow a pedestrian to cross at a marked or unmarked crosswalk.","source":{"chapter":5,"section":"When is it illegal to pass another vehicle?","anchor":"passing","page":"72"}},{"id":"ch5-high-017","chapter":5,"category":"highways","question":"A school bus ahead is showing flashing amber lights. What does this indicate?","options":["The bus is stopping to let other traffic pass","The bus is reducing speed and may be stopping to allow passengers on and off, so passing is not the safest choice","The bus is signalling that its red lights are about to turn off","The bus is turning left at the next intersection"],"answer":1,"explanation":"Flashing amber lights indicate the school bus is reducing speed; it may be stopping to allow passengers on and off. If you proceed, do it with caution.","source":{"chapter":5,"section":"When is it illegal to pass another vehicle?","anchor":"passing","page":"72"}},{"id":"ch5-high-018","chapter":5,"category":"highways","question":"You intend to pass on a two-lane highway, but oncoming vehicles are too close. What should you do?","options":["Do not attempt to pass if you have any doubts about safely completing it","Signal twice and pass with your high beams on","Move the vehicle ahead to the right so you can pass sooner","Accelerate hard to use the available space"],"answer":0,"explanation":"If oncoming vehicles are too close, or you have any doubts about safely completing the pass, do not attempt to pass.","source":{"chapter":5,"section":"When is it illegal to pass another vehicle?","anchor":"passing","page":"72"}},{"id":"ch5-high-019","chapter":5,"category":"highways","question":"What is the emergency stopping lane of a primary highway for?","options":["Driving at reduced speed when the travel lanes are busy","Drivers who need to stop due to an urgent situation or because they have problems with their vehicle","Parking while you rest, eat or use a phone","Passing slow vehicles on hills"],"answer":1,"explanation":"The portion between the edge of the roadway and the first lane of travel, sometimes called the shoulder, is for drivers who need to stop due to an urgent situation or vehicle problems.","source":{"chapter":5,"section":"Emergency stopping lane","anchor":"#emergency-stopping-lane","page":"72"}},{"id":"ch5-high-020","chapter":5,"category":"highways","question":"May you drive in the emergency stopping lane to pass another vehicle?","options":["No. Do not drive in the emergency stopping lane or pass another vehicle by using it","Only when directed by a police officer","Yes, briefly, if the shoulder is solid","Yes, if you turn on your hazard lights first"],"answer":0,"explanation":"Do not drive in the emergency stopping lane of a highway, and do not pass or assist another vehicle to pass you by using this lane.","source":{"chapter":5,"section":"Emergency stopping lane","anchor":"#emergency-stopping-lane","page":"72"}},{"id":"ch5-high-021","chapter":5,"category":"highways","question":"When two roadways join into one and traffic enters from a merging lane, who has the right-of-way?","options":["Neither has the right-of-way; merging is a shared responsibility","The vehicles already on the highway, always","The merging vehicles, because they are accelerating","Whichever vehicle arrived at the merge point first"],"answer":0,"explanation":"Neither the merging vehicle nor the vehicles already on the highway have the right-of-way; merging is a shared responsibility between both.","source":{"chapter":5,"section":"Merging","anchor":"entering-and-exiting-a-major-roadway","page":"73"}},{"id":"ch5-high-022","chapter":5,"category":"highways","question":"What are merging lanes designed to allow?","options":["Your vehicle to reach the posted speed limit of the road you are merging onto","Large trucks extra room to stop safely","A full stop at the end of the ramp to wait for a gap","Slower drivers to yield before entering"],"answer":0,"explanation":"Avoid reducing your speed abruptly or stopping when merging. Merging lanes are designed to allow your vehicle to reach the posted speed limit of the road you are merging onto.","source":{"chapter":5,"section":"Merging","anchor":"entering-and-exiting-a-major-roadway","page":"73"}},{"id":"ch5-high-023","chapter":5,"category":"highways","question":"While merging onto a major roadway, when should you use your signal light?","options":["Before or when you are in the acceleration lane","Only if there is traffic in the lane beside you","Never; mirrors are enough when merging","Only after you have fully entered the travel lane"],"answer":0,"explanation":"Merge by planning and timing your approach, and use your signal light before or when you are in the acceleration lane.","source":{"chapter":5,"section":"Merging","anchor":"entering-and-exiting-a-major-roadway","page":"73"}},{"id":"ch5-high-024","chapter":5,"category":"highways","question":"When should you move into the gap you selected in highway traffic while merging?","options":["Only once the gap is less than one car length","Before you cross the solid white line, to build up speed","After you are past the solid white line of the acceleration lane","After the vehicle behind you changes lanes"],"answer":2,"explanation":"When it is safe and legal, move into the gap after you are past the solid white line of the acceleration lane, and maintain your speed at or near the speed of other vehicles.","source":{"chapter":5,"section":"Merging","anchor":"entering-and-exiting-a-major-roadway","page":"73"}},{"id":"ch5-high-025","chapter":5,"category":"highways","question":"You are already on the main roadway and traffic is merging in from the right. If it is safe, what should you do?","options":["Hold your speed exactly and stay beside the merging vehicle","Increase speed immediately without watching traffic","Stop in the merge area to let the vehicle in","Move left to the next lane to leave the right travel lane clear for merging vehicles"],"answer":3,"explanation":"If you are on the main roadway and traffic is merging, move left to the next lane if it is safe, leaving the right travel lane clear for the merging vehicles.","source":{"chapter":5,"section":"Merging","anchor":"entering-and-exiting-a-major-roadway","page":"73"}},{"id":"ch5-high-026","chapter":5,"category":"highways","question":"You missed your exit on a major highway. What must you do?","options":["Reverse along the shoulder to reach the exit ramp","Stop, wait for a gap, then back up to the exit","Cut across the median if no traffic is visible","Continue to the next exit; do not stop or reverse on a highway, emergency stopping lane or shoulder"],"answer":3,"explanation":"If you miss your exit, do not stop. Continue to the next exit and make plans to return to your route; never stop and reverse on a highway, emergency stopping lane or shoulder.","source":{"chapter":5,"section":"Exiting","anchor":"entering-and-exiting-a-major-roadway","page":"74"}},{"id":"ch5-high-027","chapter":5,"category":"highways","question":"When exiting a major roadway, where should most of your slowing take place?","options":["In the deceleration lane, if there is one","Only after your vehicle is fully off the highway","At the very top of the exit ramp while turning","In the travel lane just after passing the exit sign"],"answer":0,"explanation":"If possible, do most of the slowing in the deceleration lane. Some deceleration lanes are short, so you may need to start to reduce your speed while still on the highway.","source":{"chapter":5,"section":"Exiting","anchor":"entering-and-exiting-a-major-roadway","page":"74"}},{"id":"ch5-high-028","chapter":5,"category":"highways","question":"What is a weave zone?","options":["A zone where police set up roadside checks","A construction area where lanes shift from side to side","The painted area where two ramps cross at different levels","An area where the highway entrance and exit use the same lane"],"answer":3,"explanation":"In some interchanges the entrance and exit use the same lane, which can be close together; the shared area is called a weave zone.","source":{"chapter":5,"section":"Weave zones","anchor":"entering-and-exiting-a-major-roadway","page":"74"}},{"id":"ch5-high-029","chapter":5,"category":"highways","question":"What must you do when you drive through a weave zone?","options":["Sound your horn to alert drivers exiting ahead of you","Control your speed and the timing of your lane change to merge with other traffic","Keep your exact speed and avoid using your signal","Stop in the zone to let entering traffic clear"],"answer":1,"explanation":"In weave zones, control your speed and the timing of your lane change to merge with other traffic, using caution so all vehicles can safely exit and enter the highway.","source":{"chapter":5,"section":"Weave zones","anchor":"entering-and-exiting-a-major-roadway","page":"74"}},{"id":"ch5-high-030","chapter":5,"category":"highways","question":"When should you reduce your speed to drive safely through a curve?","options":["Before entering the curve, and stay centred in your lane","Halfway through the curve, once you can judge the turn","After entering, by braking firmly inside the curve","Only when a warning sign posts a lower speed"],"answer":0,"explanation":"If you need to reduce your speed for a curve, do it before entering the curve, and stay centred in your lane.","source":{"chapter":5,"section":"Curves","anchor":"entering-and-exiting-a-major-roadway","page":"75"}},{"id":"ch5-high-031","chapter":5,"category":"highways","question":"On a highway with one lane in each direction, what is the rule about passing on curves?","options":["Permitted if the curve is gentle","Permitted only where a passing lane is added","Permitted with your hazard lights on","Do not pass vehicles on curves; it is unsafe and illegal"],"answer":3,"explanation":"Do not pass vehicles on curves on highways with one lane in each direction; it is unsafe and illegal.","source":{"chapter":5,"section":"Curves","anchor":"entering-and-exiting-a-major-roadway","page":"75"}},{"id":"ch5-high-032","chapter":5,"category":"highways","question":"Your tires lose traction as you enter a curve to the left. What may happen and how should you respond?","options":["Your vehicle may skid into oncoming traffic; brake firmly to stop quickly","Nothing, because traction returns automatically in curves","Your vehicle may spin in place; accelerate to straighten it","Your vehicle may skid to the right side of the road; stay off the accelerator and brake"],"answer":3,"explanation":"If your tires lose traction entering a curve to the left, your vehicle may skid to the right side of the road. Stay off the accelerator and brake, make small steering adjustments, and look in the direction you want to go.","source":{"chapter":5,"section":"Curves","anchor":"entering-and-exiting-a-major-roadway","page":"75"}},{"id":"ch5-high-033","chapter":5,"category":"highways","question":"Your tires lose traction as you enter a curve to the right. What is the main risk and correct response?","options":["Striking the vehicle ahead; pump the brakes quickly","The trailer swinging wide; pull the park brake","Your vehicle may skid into oncoming traffic; look in the direction you want to go and make small steering adjustments","Rolling into the ditch; hold the wheel still and coast"],"answer":2,"explanation":"If your tires lose traction entering a curve to the right, your vehicle may skid into oncoming traffic. Stay off the brake and the accelerator, and make small steering adjustments to come out of the skid.","source":{"chapter":5,"section":"Curves","anchor":"entering-and-exiting-a-major-roadway","page":"75"}},{"id":"ch5-high-034","chapter":5,"category":"highways","question":"Why should you use caution and move to the right in your lane as you approach the top of a hill?","options":["To prepare for a stop sign at the crest","Because vehicles may be parked at the viewpoint","Because your engine needs more power on the grade","To keep from being hit by an oncoming vehicle that has crossed the centre line and is in your lane"],"answer":3,"explanation":"As you approach the top of a hill, use caution and move to the right in your lane to avoid an oncoming vehicle that has crossed the centre line. Do not pass near the top of a hill, as you cannot see what is ahead.","source":{"chapter":5,"section":"Hills","anchor":"entering-and-exiting-a-major-roadway","page":"76"}},{"id":"ch5-high-035","chapter":5,"category":"highways","question":"While travelling down a very steep hill in a vehicle with a standard transmission, what reduces the risk of your brakes overheating?","options":["Switching to neutral and coasting down","Pumping the brakes on the steepest section","Riding the brakes with continuous light pressure","Shifting to a lower gear"],"answer":3,"explanation":"Adjust your speed on a steep hill because your stopping time will increase; in a vehicle with a standard transmission, shifting to a lower gear can reduce the risk of your brakes overheating.","source":{"chapter":5,"section":"Hills","anchor":"entering-and-exiting-a-major-roadway","page":"76"}},{"id":"ch6-emer-001","chapter":6,"category":"emergencies","question":"What does an anti-lock braking system (ABS) allow you to do during emergency braking?","options":["Slow the vehicle without touching the brake pedal","Prevent skids entirely on any road surface","Steer while the brakes are being applied","Stop in half the distance of a regular brake system"],"answer":2,"explanation":"The ABS allows you to steer while the brakes are being applied. With ABS you can brake as hard as you need without losing your ability to steer.","source":{"chapter":6,"section":"If your vehicle has ABS brakes","anchor":"emergency-braking","page":"78"}},{"id":"ch6-emer-002","chapter":6,"category":"emergencies","question":"How should you brake in an emergency in a vehicle with ABS?","options":["Press the pedal gently and slowly increase over several seconds","Brake, release and coast alternately until stopped","Pump the brake pedal rapidly to build pressure","Apply steady firm pressure and do not pump or release the brake pedal"],"answer":3,"explanation":"With ABS, apply steady firm pressure to the brake pedal and do not pump or release it; look and steer in the direction you want to go.","source":{"chapter":6,"section":"If your vehicle has ABS brakes","anchor":"emergency-braking","page":"78"}},{"id":"ch6-emer-003","chapter":6,"category":"emergencies","question":"During a hard stop in an ABS-equipped vehicle, the brake pedal vibrates under your foot. What is happening?","options":["The engine is stalling under braking load","The brake pads are wearing out as you stop","The ABS is applying brake pressure at each wheel, cycling from locked to slightly rolling","Your tires have lost contact with the road surface"],"answer":2,"explanation":"ABS applies brake pressure at each wheel, cycling from locked to slightly rolling, and you feel this as a vibration through the brake pedal.","source":{"chapter":6,"section":"If your vehicle has ABS brakes","anchor":"emergency-braking","page":"78"}},{"id":"ch6-emer-004","chapter":6,"category":"emergencies","question":"What is threshold braking in a vehicle without ABS?","options":["Pressing firmly on the brake pedal to the point just before the wheels lock","Using the park brake together with the foot brake","Braking only while travelling in a straight line","Braking with the wheels completely locked to shorten stopping distance"],"answer":0,"explanation":"In an emergency without ABS, press firmly on the brake pedal to the point just before the wheels lock. This is called threshold braking.","source":{"chapter":6,"section":"If your vehicle does not have ABS brakes","anchor":"emergency-braking","page":"78"}},{"id":"ch6-emer-005","chapter":6,"category":"emergencies","question":"In a vehicle without ABS, your wheels lock up under hard braking. What should you do?","options":["Turn the steering wheel sharply to free the tires","Hold the pedal down firmly until the vehicle stops","Ease off the brake pedal slightly to regain steering control, then brake again without locking the wheels","Accelerate briefly to straighten the vehicle"],"answer":2,"explanation":"If your wheels lock, ease off the brake pedal slightly to regain steering control, then press the brake pedal firmly again without locking the wheels.","source":{"chapter":6,"section":"If your vehicle does not have ABS brakes","anchor":"emergency-braking","page":"78"}},{"id":"ch6-emer-006","chapter":6,"category":"emergencies","question":"Your vehicle begins to skid. What is the correct general response?","options":["Hold the wheel straight and let the vehicle slow by itself","Brake gently and steer in the direction of the skid","Accelerate firmly to regain tire grip","Stay off the brake and accelerator; look and steer where you want the front of the vehicle to go"],"answer":3,"explanation":"To regain control of a skid, do not touch the brake or the accelerator. Look and steer where you want the front of the vehicle to go, point the tires along the centre of your lane and do not make large steering adjustments.","source":{"chapter":6,"section":"Skid recovery","anchor":"loss-of-control","page":"78"}},{"id":"ch6-emer-007","chapter":6,"category":"emergencies","question":"You are in a braking skid because your wheels locked (no ABS). When does your steering control return?","options":["When the engine reaches normal operating temperature","When you turn the ignition off and on","When you press harder on the brake pedal","When the wheels of the vehicle start to roll again after you take your foot off the brake"],"answer":3,"explanation":"Take your foot off the brake pedal; when the wheels of the vehicle start to roll, steering control will return. If you brake again, use firm pressure but not hard enough to lock the wheels.","source":{"chapter":6,"section":"Braking skid (non-ABS)","anchor":"loss-of-control","page":"79"}},{"id":"ch6-emer-008","chapter":6,"category":"emergencies","question":"What causes a power (acceleration) skid?","options":["Travelling too quickly when rounding a corner","Braking too firmly so the wheels lock","Accelerating too quickly, causing the wheels to spin","Turning the steering wheel too sharply at low speed"],"answer":2,"explanation":"A power skid occurs when you accelerate too quickly, causing the wheels to spin.","source":{"chapter":6,"section":"Power (acceleration) skid","anchor":"loss-of-control","page":"79"}},{"id":"ch6-emer-009","chapter":6,"category":"emergencies","question":"You are in a power skid. What should you do?","options":["Apply firm braking until the wheels stop spinning","Shift to neutral and coast to a full stop","Hold the steering wheel motionless until traction returns","Take your foot off the gas pedal, make any needed steering corrections and use gentle acceleration; do not over-correct your steering"],"answer":3,"explanation":"Take your foot off the gas pedal to allow the wheels to stop spinning, then use gentle acceleration. Be careful not to over-correct your steering or you may skid in the opposite direction.","source":{"chapter":6,"section":"Power (acceleration) skid","anchor":"loss-of-control","page":"79"}},{"id":"ch6-emer-010","chapter":6,"category":"emergencies","question":"Your vehicle is sliding sideways as you take a corner too quickly (a cornering skid). What should you do?","options":["Brake progressively while steering deeper into the curve","Accelerate out of the curve as quickly as possible","Pull the park brake to rotate the vehicle","Take your foot off the gas pedal and do not use your brakes"],"answer":3,"explanation":"In a cornering skid, take your foot off the gas pedal, do not use your brakes, and look and steer in the direction you want the front of the vehicle to go.","source":{"chapter":6,"section":"Cornering skid","anchor":"loss-of-control","page":"79"}},{"id":"ch6-emer-011","chapter":6,"category":"emergencies","question":"Your wheels have just dropped off the paved portion of the roadway. What should you do first?","options":["Keep a firm grip on the wheel, do not try to steer back immediately, and take your foot off the gas pedal","Brake hard to stop on the shoulder","Accelerate until the rear wheels regain the pavement","Steer sharply back onto the road before you lose speed"],"answer":0,"explanation":"If you drive off the paved portion of the roadway, keep a firm grip on the steering wheel, do not try to steer the vehicle back onto the road immediately, and take your foot off the gas pedal to reduce your speed.","source":{"chapter":6,"section":"Off-road recovery","anchor":"loss-of-control","page":"79"}},{"id":"ch6-emer-012","chapter":6,"category":"emergencies","question":"When is it correct to steer back onto the road after driving off the paved portion of the roadway?","options":["Immediately, while your momentum is still high","After using gradual brake pressure and checking for traffic, return at a controlled speed and straighten out in the proper travel lane","Once you have stopped completely and reversed toward the pavement","As soon as the wheels on one side are clear of gravel"],"answer":1,"explanation":"Avoid braking if possible, using gradual pressure if you must. Check for traffic before steering back, then return to the road gradually at a controlled speed and straighten your vehicle in the proper travel lane.","source":{"chapter":6,"section":"Off-road recovery","anchor":"loss-of-control","page":"79"}},{"id":"ch6-emer-013","chapter":6,"category":"emergencies","question":"Your vehicle breaks down on a highway. How far apart should you safely place reflective triangles to the rear of your vehicle?","options":["One directly beside the driver door only","About 100 to 150 metres apart, ahead of your vehicle","Touching the rear bumper, side by side","About 10 to 20 metres (33 to 66 feet) apart"],"answer":3,"explanation":"Carry reflective triangles; on the highway or in a potentially dangerous location, safely place them to the rear of your vehicle about 10 to 20 metres (33 to 66 feet) apart.","source":{"chapter":6,"section":"Vehicle mechanical problems","anchor":"#vehicle-mechanical-problems","page":"80"}},{"id":"ch6-emer-014","chapter":6,"category":"emergencies","question":"Your vehicle needs to stop because of a mechanical problem. Which stopping location must you avoid?","options":["On a bridge or in a tunnel","An off-highway rest area","A safe location beside the road with your hazard lights on","A parking lot"],"answer":0,"explanation":"Change lanes safely and park in a safe location if possible; do not stop on a bridge or in a tunnel, as this can be very dangerous.","source":{"chapter":6,"section":"Vehicle mechanical problems","anchor":"#vehicle-mechanical-problems","page":"80"}},{"id":"ch6-emer-015","chapter":6,"category":"emergencies","question":"The brake warning light comes on while you are driving and you have checked that the park brake is released. What should you do?","options":["Reset the sensor by restarting the engine","Test the brakes with a hard stop in the nearest intersection","Move to the side of the road as soon as it is safe to do so","Continue to your destination and watch the light"],"answer":2,"explanation":"The brake warning light should light before your brakes stop working; when it comes on and you have checked the park brake is released, move to the side of the road as soon as it is safe to do so.","source":{"chapter":6,"section":"Brake failure","anchor":"vehicle-mechanical-problems","page":"80"}},{"id":"ch6-emer-016","chapter":6,"category":"emergencies","question":"Your brakes have failed and your wheels are not turned. How can you slow your vehicle?","options":["Carefully use your park brake; you may also shift to a lower gear for a safe, controlled stop","Release the steering wheel so the vehicle straightens itself","Steer to the nearest ditch right away","Shift into reverse to stop quickly"],"answer":0,"explanation":"If your brakes fail and your wheels are not turned, carefully use your park brake to slow your vehicle; you may be able to shift to a lower gear to bring your vehicle to a safe and controlled stop.","source":{"chapter":6,"section":"Brake failure","anchor":"vehicle-mechanical-problems","page":"80"}},{"id":"ch6-emer-017","chapter":6,"category":"emergencies","question":"Your engine stops while you are still moving, and your vehicle does not slow with normal pressure on the power brake pedal. What should you do?","options":["Use the horn and let the vehicle roll to a stop on its own","Shift to park while still rolling","Pump the pedal lightly and often","Push the brake pedal harder and apply steady pressure"],"answer":3,"explanation":"If you have power brakes and the power system fails, such as when the engine stops while you are still moving, push the brake pedal harder and apply steady pressure.","source":{"chapter":6,"section":"Brake failure","anchor":"vehicle-mechanical-problems","page":"80"}},{"id":"ch6-emer-018","chapter":6,"category":"emergencies","question":"What happens if your power steering fails while you are driving?","options":["You must stop immediately where you are","You can still steer the vehicle, but you will have to use extra effort to turn the steering wheel","Steering works normally with no added effort","You can steer only while the engine is revving"],"answer":1,"explanation":"If your power steering fails, you can still steer the vehicle; you will have to use extra effort to turn the steering wheel.","source":{"chapter":6,"section":"Power steering failure","anchor":"vehicle-mechanical-problems","page":"81"}},{"id":"ch6-emer-019","chapter":6,"category":"emergencies","question":"What happens when your front tire goes flat while you are driving?","options":["The vehicle pulls strongly to the side that has the flat tire","The vehicle pulls away from the side with the flat tire","The steering becomes lighter and easier to turn","A flat rear tire instead causes strong pulling"],"answer":0,"explanation":"When a front tire is flat, the vehicle will pull strongly to the side that has the flat tire; a flat rear tire may make your vehicle weave.","source":{"chapter":6,"section":"Tire failure","anchor":"vehicle-mechanical-problems","page":"81"}},{"id":"ch6-emer-020","chapter":6,"category":"emergencies","question":"A tire suddenly goes flat while you are driving. What should you do first?","options":["Steer onto the shoulder at full speed","Brake immediately and stop in your lane","Resist the urge to brake; take your foot off the gas pedal and allow the engine to slow the vehicle","Accelerate to reach a service station faster"],"answer":2,"explanation":"Resist the urge to immediately apply the brakes. Take your foot off the gas pedal, hold the steering wheel firmly, and once under control and speed is reduced, apply the brake with gentle, steady pressure.","source":{"chapter":6,"section":"Tire failure","anchor":"vehicle-mechanical-problems","page":"81"}},{"id":"ch6-emer-021","chapter":6,"category":"emergencies","question":"Both of your headlights fail at night. What should you do?","options":["Turn on your hazard lights, turn the headlight control off and on, and if the headlights stay off reduce your speed and move safely to the emergency stopping lane or edge of the road","Continue slowly on daytime running lights until you arrive home","Use your instrument panel lights to illuminate the road","Follow another vehicle closely to use its lights"],"answer":0,"explanation":"If both headlights fail, turn on your hazard lights, turn the headlight control off and on, and if they are still not on, reduce your speed and safely park in a safe place. Replace a burned-out headlight bulb right away, because driving with only one headlight increases the risk of being without both.","source":{"chapter":6,"section":"Headlight failure","anchor":"vehicle-mechanical-problems","page":"81"}},{"id":"ch6-emer-022","chapter":6,"category":"emergencies","question":"When are you required to turn your headlights on?","options":["Whenever you cannot clearly see 150 metres (500 feet) in front of you","Only when conditions require windshield wipers","On major highways at all times, regardless of visibility","Only 30 minutes after sunset"],"answer":0,"explanation":"When driving at night, or at any time when you cannot clearly see 150 metres (500 feet) in front of you, you must turn your headlights on.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"81"}},{"id":"ch6-emer-023","chapter":6,"category":"emergencies","question":"Why are daytime running lights not enough for driving at night?","options":["They only work in temperatures below zero","They are not bright enough for night, and the tail-lights and instrument panel lights will not be on","They confuse oncoming drivers at low speeds","They flicker when the engine idles"],"answer":1,"explanation":"Daytime running lights are not bright enough to be used at night; the tail-lights and instrument panel lights will also not be on.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"81"}},{"id":"ch6-emer-024","chapter":6,"category":"emergencies","question":"Which lights must you use at night when there is oncoming traffic, even when the highway is divided?","options":["Only your parking lights","High-beam headlights","Low-beam headlights","Hazard flashers in place of headlights"],"answer":2,"explanation":"Use your low-beam headlights if there is oncoming traffic, even when the highway is divided; avoid looking directly at oncoming headlights and look slightly down and to the right edge of your driving lane.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"81"}},{"id":"ch6-emer-025","chapter":6,"category":"emergencies","question":"What does it mean to not overdrive your headlights at night?","options":["Dim your beams whenever a vehicle is behind you","Travel at a speed that allows you to respond safely or stop in the distance lit by your headlights","Keep your speed high enough to stay with traffic","Use high beams at all times on rural roads"],"answer":1,"explanation":"Visibility is reduced at night; do not overdrive your headlights. Travel at a speed that allows you to respond safely or stop in the distance lit by your headlights.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"82"}},{"id":"ch6-emer-026","chapter":6,"category":"emergencies","question":"When driving at night, you are following another vehicle. Within what distance must you use your low-beam headlights?","options":["Only when following a large truck or bus","Within 150 metres (one-and-one-half city blocks) of the other vehicle","Within 500 metres on rural roads","Only if the vehicle ahead flashes its brake lights"],"answer":1,"explanation":"Use your low-beam headlights when you are following within 150 metres (one-and-one-half city blocks) of another vehicle.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"82"}},{"id":"ch6-emer-027","chapter":6,"category":"emergencies","question":"Within what distance of oncoming vehicles must you use your low-beam headlights when driving at night?","options":["Within 500 metres","Only within one city block in urban areas","Within 100 metres","Within 300 metres"],"answer":3,"explanation":"Use your low-beam headlights when you are within 300 metres of oncoming vehicles, even when the highway is divided.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"82"}},{"id":"ch6-emer-028","chapter":6,"category":"emergencies","question":"Glare from the sun or the lights of other vehicles is making it hard to see the road. What should you do?","options":["Reduce your speed, and keep your vehicle windows properly cleaned inside and outside","Speed up to get past the glare source quickly","Switch to high beams to overpower the glare","Close one eye and rely on the other"],"answer":0,"explanation":"If glare makes it difficult to see the road, reduce your speed; ensure your vehicle windows are properly cleaned inside and outside to improve visibility.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"82"}},{"id":"ch6-emer-029","chapter":6,"category":"emergencies","question":"In smoke and fog, why should you use low-beam headlights instead of high beams?","options":["High beams cast shadows that hide lane markings","Low beams reach twice as far through fog","High beams use more power and dim on long trips","High beams reflect the light back to you, creating glare"],"answer":3,"explanation":"Use low-beam headlights in smoke and fog, as high beams reflect the light back to you, creating glare.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"82"}},{"id":"ch6-emer-030","chapter":6,"category":"emergencies","question":"Fog becomes so thick that it is no longer safe to continue driving. What is the correct action?","options":["Stop beside the fog line and wait with your low beams on","Maintain speed and use the left shoulder for reference","Follow the tail-lights of another vehicle closely","Slow down, move your vehicle well off the road to a safe location, turn on your hazard warning lights, and do not drive until conditions improve"],"answer":3,"explanation":"If visibility becomes so poor that it is no longer safe to continue driving, slow down and move your vehicle well off the road to a safe location, turn on your hazard warning lights, and do not attempt to drive until conditions improve.","source":{"chapter":6,"section":"Challenging conditions","anchor":"#challenging-conditions","page":"82"}},{"id":"ch6-emer-031","chapter":6,"category":"emergencies","question":"The asphalt on the road looks shiny and black instead of grey-white. What could this mean and what should you do?","options":["An oil spill; brake firmly to a stop","Wet debris; steer around it at a steady speed","A fresh paving job; accelerate to clear the section quickly","Possible black ice; be cautious and reduce your speed without braking"],"answer":3,"explanation":"Black ice is caused by moisture freezing on the road surface, and often a driver cannot see it. If the asphalt looks shiny and black instead of grey-white, be cautious and reduce your speed without braking.","source":{"chapter":6,"section":"Road surface conditions that affect traction","anchor":"challenging-conditions","page":"82"}},{"id":"ch6-emer-032","chapter":6,"category":"emergencies","question":"What is hydroplaning?","options":["Your tires losing contact with the road surface on wet roads","Driving through a flooded intersection in low gear","Water spraying from another vehicle onto your windshield","Braking with a pulsing pedal on a wet road"],"answer":0,"explanation":"On wet roads your tires may lose contact with the road surface; this is called hydroplaning, and it can cause you to lose control of your vehicle.","source":{"chapter":6,"section":"Road surface conditions that affect traction","anchor":"challenging-conditions","page":"83"}},{"id":"ch6-emer-033","chapter":6,"category":"emergencies","question":"Your vehicle begins to hydroplane on a wet road. What should you do?","options":["Do not brake; release pressure on the accelerator to let the vehicle slow, and look and steer where you want the front to go","Accelerate to cut through the water","Turn the wheel hard toward the shoulder","Brake firmly to press the tires onto the surface"],"answer":0,"explanation":"If you hydroplane, do not brake. Release pressure on the accelerator to allow the vehicle to slow, and look and steer where you want the front of the vehicle to go.","source":{"chapter":6,"section":"Road surface conditions that affect traction","anchor":"challenging-conditions","page":"83"}},{"id":"ch6-emer-034","chapter":6,"category":"emergencies","question":"When should you NOT use cruise control?","options":["When travelling behind slow-moving service vehicles","When the weather and road conditions are poor; when your tires contact ice, cruise control keeps applying the accelerator","When approaching an uncontrolled intersection in light traffic","On long straight highways in dry conditions"],"answer":1,"explanation":"Do not use cruise control when the weather and road conditions are poor; when your tires contact ice, cruise control will continue to apply the accelerator and you could lose control.","source":{"chapter":6,"section":"Road surface conditions that affect traction","anchor":"challenging-conditions","page":"83"}},{"id":"ch6-emer-035","chapter":6,"category":"emergencies","question":"You are stranded off the highway and your vehicle is in a safe place. What is usually the safest choice?","options":["Raise the hood and wait in the ditch beside the vehicle","Walk to the nearest town for help right away","Stay with your vehicle; run the engine just enough to stay warm and keep the vehicle ventilated","Leave the engine running at full speed and open all doors"],"answer":2,"explanation":"If you are stranded and your vehicle is in a safe place, it is usually safer to stay with your vehicle; run the engine just enough to stay warm, keep the vehicle ventilated, and open a window slightly to prevent carbon monoxide poisoning.","source":{"chapter":6,"section":"Road surface conditions that affect traction","anchor":"challenging-conditions","page":"83"}},{"id":"ch6-emer-036","chapter":6,"category":"emergencies","question":"What makes carbon monoxide especially dangerous in a running, snowed-in vehicle?","options":["It is colourless, odourless and tasteless","It ignites easily near a warm engine","It drains the vehicle battery quickly","It has a strong smell that causes instant coughing"],"answer":0,"explanation":"Carbon monoxide can enter your vehicle from a leaky exhaust system; it is a poisonous gas that is especially dangerous because it is colourless, odourless, and tasteless.","source":{"chapter":6,"section":"Road surface conditions that affect traction","anchor":"challenging-conditions","page":"83"}},{"id":"ch6-emer-037","chapter":6,"category":"emergencies","question":"Which winter emergency supplies should you carry in your vehicle?","options":["A portable generator and a spare battery","Only jumper cables and extra washer fluid","A chainsaw and a spare fuel can","Tire chains, sand or road salt, a shovel, and a heat source such as a candle with matches in a deep can"],"answer":3,"explanation":"Winter emergency supplies include blankets and extra clothing, sand or road salt, a shovel, a heat source with candle, matches and a deep can, an ice scraper and snow brush, and tire chains.","source":{"chapter":6,"section":"Road surface conditions that affect traction","anchor":"challenging-conditions","page":"83"}},{"id":"ch6-emer-038","chapter":6,"category":"emergencies","question":"Which emergency supplies should you consider having in your car at all times?","options":["Flares, a CB radio and a fire extinguisher","A first aid kit, reflective triangles, booster cables, a jack and inflated spare tire, and a flashlight with extra batteries","Extra oil filters and a portable air conditioner","A spare fuel pump and tire chains"],"answer":1,"explanation":"Consider always carrying a first aid kit, approved warning devices such as reflective triangles, booster cables, non-perishable food, a jack and inflated spare tire, a flashlight with extra batteries, a tow rope, and headlight replacement bulbs.","source":{"chapter":6,"section":"Emergency supplies","anchor":"#emergency-supplies","page":"84"}},{"id":"ch6-emer-039","chapter":6,"category":"emergencies","question":"An animal suddenly appears in front of your vehicle. What should you do?","options":["Swerve toward the oncoming lane to miss it","Maintain speed, since animals usually move away","Brake hard and prepare to take evasive action, choosing an escape route away from oncoming traffic","Brake gently and steer directly at the animal to make it jump away"],"answer":2,"explanation":"If an animal suddenly appears in front of you, brake hard and prepare to take evasive action; choose an escape route away from oncoming traffic. Be careful at dusk and dawn, when animals are more active.","source":{"chapter":6,"section":"Animals","anchor":"#animals","page":"84"}},{"id":"ch6-emer-040","chapter":6,"category":"emergencies","question":"When are you required to report a collision to the police or local law enforcement?","options":["Only when another driver refuses to exchange information","When overall damage exceeds $5000, when anyone is injured or killed, or when there is damage to a traffic control device, parking meter or public property","Only when a vehicle must be towed from the scene","Whenever the damage exceeds $500 to any one vehicle"],"answer":1,"explanation":"You must report all collisions if anyone is injured or killed, if overall damage exceeds $5000, or if any damage is done to a traffic control device, parking meter or public property.","source":{"chapter":6,"section":"Collisions","anchor":"#collisions","page":"84"}},{"id":"ch6-emer-041","chapter":6,"category":"emergencies","question":"After a collision, what should you NOT do?","options":["Record the time, location, weather and other important details","Discuss who was at fault with the other driver","Exchange names, contact information and insurance details","Record the names and contact information of witnesses"],"answer":1,"explanation":"At a collision, do not discuss who was at fault; exchange names, contact information and insurance details with the other drivers, record witness information, and notify your insurance company as soon as possible.","source":{"chapter":6,"section":"Collisions","anchor":"#collisions","page":"84"}},{"id":"ch6-emer-042","chapter":6,"category":"emergencies","question":"You are the first person at the scene of a collision and police are called to the scene. What must you and other drivers do?","options":["Follow the police convoy through the scene","Direct traffic around the scene until police arrive","Stop away from the collision in a safe location, protect the scene, and if police are called, all drivers must remain","Leave after providing a written summary to the injured person"],"answer":2,"explanation":"If you are first at a collision scene, stop away from the collision in a safe location, offer assistance if possible, and protect the scene with flashing hazard lights and reflective triangles; if police are called to the scene, all drivers must remain.","source":{"chapter":6,"section":"Collisions","anchor":"#collisions","page":"84"}},{"id":"ch6-emer-043","chapter":6,"category":"emergencies","question":"You are passing stopped emergency vehicles or tow trucks with their lights flashing. To what speed must you reduce?","options":["The posted limit only","80 km/h or the posted limit, whichever comes first","60 km/h or the posted speed, whichever is lower","60 km/h at all times, even if the posted limit is lower"],"answer":2,"explanation":"Motorists must reduce speed to 60 km/h or the posted speed, whichever is lower, when passing emergency vehicles or tow trucks stopped with their lights flashing.","source":{"chapter":6,"section":"Emergency response vehicles and tow trucks","anchor":"#emergency-response-vehicles-and-tow-trucks","page":"85"}},{"id":"ch6-emer-044","chapter":6,"category":"emergencies","question":"What is the penalty for speeding when passing stopped emergency vehicles or tow trucks with flashing lights?","options":["A mandatory 30-day licence suspension","A written warning for a first offence","The fine for speeding in these areas is doubled","Three demerit points only"],"answer":2,"explanation":"The 60 km/h rule applies to the lane(s) immediately next to the stopped vehicles, and the fine for speeding in these areas is doubled.","source":{"chapter":6,"section":"Emergency response vehicles and tow trucks","anchor":"#emergency-response-vehicles-and-tow-trucks","page":"85"}},{"id":"ch6-emer-045","chapter":6,"category":"emergencies","question":"You are NOT in the lane immediately next to stopped emergency vehicles with flashing lights. What does the guide ask you to do?","options":["Still reduce your speed, stay watchful and cautious, and leave lots of space between yourself and emergency personnel and equipment","Change to the lane farthest from the scene at any speed","Stop on the shoulder until the scene is cleared","Maintain your speed without changes"],"answer":0,"explanation":"If you are not in the lane next to the stopped vehicles, you still need to be watchful and cautious; reduce your speed and leave lots of space between yourself and emergency personnel and equipment.","source":{"chapter":6,"section":"Emergency response vehicles and tow trucks","anchor":"#emergency-response-vehicles-and-tow-trucks","page":"85"}},{"id":"ch6-emer-046","chapter":6,"category":"emergencies","question":"An ambulance sounding a siren is approaching on a two-way roadway. What must you do?","options":["Drive as closely as possible to the right curb or edge of the roadway and stop until it has passed","Speed up to clear the intersection first","Sound your horn to warn other drivers of the siren","Maintain your speed so the driver can pass you"],"answer":0,"explanation":"When an emergency vehicle approaches from any direction sounding a siren, safely move your vehicle, drive as closely as possible to the right curb or edge of a two-way roadway, and stop until it has passed.","source":{"chapter":6,"section":"Emergency vehicles","anchor":"#emergency-vehicles","page":"85"}},{"id":"ch6-emer-047","chapter":6,"category":"emergencies","question":"A fire truck with its siren on is approaching on a one-way street. To which edge should you move?","options":["The left edge only","Move right or left to the nearest curb, and stop until the emergency vehicle has passed","Stay in your lane and let the crew pick a path","The right edge only"],"answer":1,"explanation":"On one-way streets, move right or left to the nearest curb, stop until the emergency vehicle has passed, and check that no other emergency vehicles are approaching.","source":{"chapter":6,"section":"Emergency vehicles","anchor":"#emergency-vehicles","page":"85"}},{"id":"ch6-emer-048","chapter":6,"category":"emergencies","question":"What does a vehicle displaying flashing green lights tell you?","options":["The vehicle is carrying dangerous goods","A funeral procession is travelling ahead","The driver is a novice with a learner permit","Treat it like any other emergency vehicle, such as a volunteer fire fighter responding to an emergency"],"answer":3,"explanation":"If you see a vehicle with flashing green lights, treat it like any other emergency vehicle; in some municipalities volunteer fire fighters use flashing green lights on their emergency response vehicles.","source":{"chapter":6,"section":"Emergency vehicles","anchor":"#emergency-vehicles","page":"85"}},{"id":"ch6-emer-049","chapter":6,"category":"emergencies","question":"What must motorists do in construction zones?","options":["Stop completely at every construction sign","Reduce speed by 10 km/h below the posted limit","Obey the posted speed, follow the directions of flag persons, and remember fines for speeding are doubled when workers are present","Use hazard lights when passing through the reduced lane"],"answer":2,"explanation":"In construction zones, motorists must observe the posted speed and obey the flag person; when workers are present, the fines for speeding in these areas will be doubled.","source":{"chapter":6,"section":"Maintenance and construction vehicles","anchor":"#maintenance-and-construction-vehicles","page":"86"}},{"id":"ch6-emer-050","chapter":6,"category":"emergencies","question":"A police vehicle with flashing lights stops behind you. After stopping, what should you do?","options":["Keep the engine running and place the transmission in drive, ready to leave","Drive slowly forward so the officer sees you are cooperative","Stay calm, place the transmission in PARK (or NEUTRAL with a manual), apply the park brake, remain in the vehicle with your driver licence, registration and insurance ready, and do not move until instructed","Get out and meet the officer behind your vehicle"],"answer":2,"explanation":"After stopping for police, ensure the transmission is in PARK (automatic) or NEUTRAL (manual), apply the park brake, remain in your vehicle with your documents ready, and do not move your vehicle until instructed by the police officer.","source":{"chapter":6,"section":"Stopping your vehicle safely for law enforcement","anchor":"emergency-response-vehicles-and-tow-trucks","page":"86"}},{"id":"ch7-fuel-001","chapter":7,"category":"responsible","question":"What information does the EnerGuide label on a vehicle provide?","options":["The maximum speed at which the vehicle can cruise","The power output of the engine in horsepower","Fuel usage in litres per 100 km and the estimated annual fuel cost","The recommended service schedule for the engine"],"answer":2,"explanation":"The EnerGuide label identifies vehicle fuel usage in litres used per 100 kilometres driven, plus the estimated annual fuel cost. Generally, the smaller the engine, the less fuel the vehicle will use.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-002","chapter":7,"category":"responsible","question":"Every 10 km/h above 90 km/h burns about how much extra fuel?","options":["About 5 per cent more","About 10 per cent more","About 25 per cent more","About 40 per cent more"],"answer":1,"explanation":"Travelling at higher speeds increases fuel use. Every 10 km/h above 90 km/h burns about 10 per cent more fuel.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-003","chapter":7,"category":"responsible","question":"How much can rapid acceleration and changes in speed raise fuel consumption?","options":["Up to 10 per cent","Up to 5 per cent","Up to 50 per cent","As much as 40 per cent"],"answer":3,"explanation":"Rapid acceleration and changes in speed can increase fuel consumption by as much as 40 per cent. It is safer and more fuel-efficient to gradually increase your speed, and cruise control helps maintain a steady speed on the highway.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-004","chapter":7,"category":"responsible","question":"If you are parking for more than 10 seconds, what should you do?","options":["Turn off your engine","Leave it idling to keep the battery charged","Idle first, then switch off after five minutes","Shut it off only if the engine is cold"],"answer":0,"explanation":"Ten seconds of idling can consume more fuel than turning off the engine and re-starting it, so turn it off for longer stops. Every 10 minutes of idling uses about one-third of a litre in the average vehicle — up to one-half of a litre with a larger engine.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-005","chapter":7,"category":"responsible","question":"According to Natural Resources Canada, how much idling is enough to warm a vehicle on a cold winter day?","options":["Ten minutes","There is no need to idle at all","One minute","Thirty minutes"],"answer":2,"explanation":"One minute of idling on a cold winter day is enough. Idling warms the engine and possibly the interior, but parts such as the tires and steering are warmed only by driving.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-006","chapter":7,"category":"responsible","question":"When should a block heater be switched on in winter?","options":["Right after you park for the night","Two hours before you plan to drive, using a timer","While driving, to keep the engine oil warm","Continuously from November to March"],"answer":1,"explanation":"Use a timer to switch the block heater on two hours before you plan to drive. Proper use can improve overall fuel economy by as much as 10 per cent, and it should not be left on overnight because the electricity costs erase the savings.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-007","chapter":7,"category":"responsible","question":"A poorly tuned engine can increase fuel consumption by up to:","options":["5 per cent","10 per cent","25 per cent","50 per cent"],"answer":3,"explanation":"A poorly tuned engine can increase fuel consumption by up to 50 per cent, and a clogged air filter can reduce fuel efficiency by 10 per cent. Regular maintenance by a qualified mechanic keeps the vehicle fuel-efficient and safe.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-008","chapter":7,"category":"responsible","question":"What effect do under-inflated tires have on fuel consumption?","options":["They increase it by about five per cent","They increase it by up to 50 per cent","They decrease it by about 10 per cent","They have no effect while the tread is good"],"answer":0,"explanation":"Under-inflated tires increase fuel consumption by about five per cent, and also increase tire wear and reduce traction.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-009","chapter":7,"category":"responsible","question":"To get maximum fuel economy with a manual transmission, you should:","options":["Hold each lower gear as long as possible","Skip the lower gears and start in high gear","Shift through the lower gears smoothly and quickly, then build up speed in the higher gears","Ride the clutch so the engine runs at high revs"],"answer":2,"explanation":"With a manual transmission, shift through the lower gears smoothly and quickly and build up speed in the higher gears. An automatic transmission shifts to a higher gear earlier if you reduce pressure on the gas pedal as you increase speed.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-010","chapter":7,"category":"responsible","question":"At highway speeds, how much does air conditioning increase fuel consumption?","options":["10 to 25 per cent","Three to four per cent","35 to 40 per cent","Air conditioning has no effect there"],"answer":1,"explanation":"At highway speeds, air conditioning increases fuel consumption by three to four per cent — it is better to use the flow-through ventilation. In stop-and-go traffic air conditioners can increase consumption by 10 to 25 per cent, so in the city it is better to open a window.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-011","chapter":7,"category":"responsible","question":"Which practice saves you time, money, and fuel?","options":["Driving each errand on a separate trip","Choosing routes with the heaviest traffic","Keeping bags of sand and salt in the trunk all year","Combining several errands into one longer trip"],"answer":3,"explanation":"Trip planning saves time, money and fuel: combine several errands into one longer trip, avoid congested routes and rush hour traffic. Remove the heavy bags of sand and salt from the trunk once winter traction is no longer needed, because extra weight means extra fuel.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-012","chapter":7,"category":"responsible","question":"What can happen if you smoke or light a match while fuelling your vehicle?","options":["Gasoline vapours can ignite, causing a fire or explosion","Smoke reduces the accuracy of pump readings","It slows the automatic shut-off on the nozzle","It is only dangerous inside the station building"],"answer":0,"explanation":"Gasoline vapours mix with air, which contains oxygen, so an ignition source such as cigarettes or matches can cause a fire or explosion. Turn your vehicle ignition off before fuelling.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-013","chapter":7,"category":"responsible","question":"Why should a cellular phone not be used while fuelling?","options":["The signal interferes with fuel flow","It distracts you from watching the pump counter","Phones that light up or ring may provide a spark that ignites gasoline vapours","Only phones used inside a vehicle are a problem"],"answer":2,"explanation":"Phones that light up when switched on or when they ring may have enough energy to provide a spark, and that spark could ignite gasoline vapours.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-014","chapter":7,"category":"responsible","question":"When filling extra containers, such as a lawn mower gas can, where should the container be placed?","options":["Left inside a closed trunk","On the ground, out of the vehicle","Held by a passenger inside the vehicle","Resting on the bumper of the vehicle"],"answer":1,"explanation":"Remove extra containers from your vehicle and place them on the ground so static electricity can discharge and spills are kept out of your vehicle. Never prop the fuel nozzle handle open, and stay by the nozzle handle during fuelling.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-fuel-015","chapter":7,"category":"responsible","question":"Before fuelling a recreational vehicle, what should be done with any pilot lights?","options":["Turned up so they burn steadier","Left as they are; they ignite nothing","Covered with a metal sheet","Turned off"],"answer":3,"explanation":"If you have a recreational vehicle or trailer, be sure that any pilot lights are turned off, because they could provide a source of ignition. Also inform the station attendant of any fuel spill.","source":{"chapter":7,"section":"Fuel efficiency and helping our environment","anchor":"#fuel-efficiency-and-helping-our-environment","page":"94"}},{"id":"ch7-law-001","chapter":7,"category":"responsible","question":"Which of these is against the law?","options":["Towing a person on skis or a toboggan behind a vehicle","Carrying a toboggan strapped inside your trunk","Towing an empty utility trailer on a highway","Carrying a bicycle on a rack behind your vehicle"],"answer":0,"explanation":"Do not use your vehicle to tow anyone — for example, a person on skis, riding a toboggan, on a motorcycle or a bicycle. It is also against the law to let a person ride in a trailer when it is being towed.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-law-002","chapter":7,"category":"responsible","question":"Where is it illegal for a person to ride?","options":["In the passenger seat with a seat belt fastened","In the rear seat of the vehicle, belted in","In a trailer being towed","In a vehicle with the windows down"],"answer":2,"explanation":"It is against the law to let a person ride in a trailer when it is being towed.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-law-003","chapter":7,"category":"responsible","question":"Who cannot operate a tractor or self-propelled farm equipment on a highway?","options":["Anyone without a special equipment permit","A person under 14 years of age","A person under 16 years of age","Anyone not employed by a farm"],"answer":1,"explanation":"People under the age of 14 cannot operate a tractor or any self-propelled farm equipment on a highway.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-law-004","chapter":7,"category":"responsible","question":"Your view from the inside rear view mirror is blocked. What must you attach?","options":["A wide convex mirror at the top of the windshield","A single outside mirror on the driver side only","A camera installed to replace the inside mirror","An outside rear view mirror on each side of the vehicle"],"answer":3,"explanation":"If the view from your inside rear view mirror is blocked, you must attach an outside rear view mirror on each side of the vehicle.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-law-005","chapter":7,"category":"responsible","question":"A load extends one and a half metres (five feet) or more beyond the rear of a vehicle. What is required in daylight hours?","options":["A red flag at least 30 cm (one foot) long on each of its four sides","A red light, since it must show day and night","A white cloth of any reasonable size","An amber flashing warning beacon"],"answer":0,"explanation":"When the load extends one and a half metres (five feet) or more beyond the rear of the vehicle, a red flag — at least 30 centimetres (one foot) long on each of the four sides of the square — should be attached to the end of the load during daylight. At night, a red light is required.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-law-006","chapter":7,"category":"responsible","question":"In a residential area, during which hours must a vehicle not be operated in a way that disturbs residents?","options":["Between 9 p.m. and 6 a.m.","Between midnight and 8 a.m.","Between 10 p.m. and 7 a.m.","Between 11 p.m. and 7 a.m."],"answer":2,"explanation":"In a residential area, you must not operate a vehicle in a way that disturbs the residents between the hours of 10 p.m. and 7 a.m.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-law-007","chapter":7,"category":"responsible","question":"Driving without care and attention, or without reasonable consideration for other road users, can result in:","options":["Nothing, unless a collision has already happened","Being found guilty of careless driving","Only a warning, if no one was speeding","The passengers being charged instead of the driver"],"answer":1,"explanation":"If you drive without care and attention, or without reasonable consideration for others using the road, you could be found guilty of careless driving. It is also illegal to use two lanes on a highway, except when conditions make a single lane impractical.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-law-008","chapter":7,"category":"responsible","question":"Which statement about passengers riding on the outside of a vehicle, including the open box of a pick up truck, is correct?","options":["It is allowed only for short trips in town","It is allowed if the rider holds on securely","It is allowed only inside residential areas","It is illegal, and the driver and the rider can both be charged"],"answer":3,"explanation":"When you are driving, you must not allow anyone to ride on the outside of your vehicle — this includes the open box of a pick up truck. You and the other person can be charged for this offence.","source":{"chapter":7,"section":"Traffic laws","anchor":"#traffic-laws","page":"94"}},{"id":"ch7-pass-001","chapter":7,"category":"responsible","question":"Under Alberta law, who must be properly secured in a vehicle?","options":["Only children under six years of age","Only occupants in the front seat","All passengers, but not the driver","All drivers and all passengers"],"answer":3,"explanation":"In Alberta, all drivers and passengers must be properly secured with a seat belt, or an approved child safety seat attached by a seat belt or an anchor system.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"92"}},{"id":"ch7-pass-002","chapter":7,"category":"responsible","question":"A 17-year-old passenger is not wearing a seat belt. Who can be fined?","options":["The passenger, because they are 16 or older","The parents of the passenger in every case","The vehicle owner instead of the passenger","No one, since fines apply only to drivers"],"answer":0,"explanation":"Passengers 16 years of age and older who are not properly secured can be fined. For passengers under 16, the driver is responsible and can be fined if they are not secured.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"92"}},{"id":"ch7-pass-003","chapter":7,"category":"responsible","question":"Who is responsible for ensuring a 10-year-old passenger is properly secured?","options":["The child, once they know how seat belts work","The parents of the child, wherever they are","The driver, who can be fined if the child is not secured","The vehicle manufacturer"],"answer":2,"explanation":"As the driver, you are responsible for ensuring that all passengers under 16 years of age are properly secured. You can be fined if they are not properly secured.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"92"}},{"id":"ch7-pass-004","chapter":7,"category":"responsible","question":"Under Alberta rules, which children must be secured in a child safety seat?","options":["All passengers younger than 12 years","A child under six years and weighing no more than 18 kg (40 pounds)","Only infants under one year of age","Any child weighing 23 kg (50 pounds) or less"],"answer":1,"explanation":"A child under six years of age who does not weigh more than 18 kg (40 lb) must be properly secured in a child safety seat, installed according to the instructions of the makers of the vehicle and the seat.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"92"}},{"id":"ch7-pass-005","chapter":7,"category":"responsible","question":"What must every child safety seat used in Canada have on it?","options":["A provincial inspection sticker","A name label on both sides of the seat","An airbag on-off switch approved by the dealer","A label stating it meets Canada Motor Vehicle Safety Standard 213"],"answer":3,"explanation":"All child safety seats used in Canada must have a label stating that the product meets Canada Motor Vehicle Safety Standard 213. Do not use a seat without this label, or one designed for use in countries other than Canada.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"92"}},{"id":"ch7-pass-006","chapter":7,"category":"responsible","question":"From birth, what kind of safety seat must all children ride in at first?","options":["A rear-facing infant seat or rear-facing convertible seat","A forward-facing seat with a tether strap","A booster seat raised to the right height","Any seat, as long as the lap belt is fastened"],"answer":0,"explanation":"From birth, all children must ride in a rear-facing infant seat or a rear-facing convertible seat until reaching the recommended weight to switch to a forward-facing seat, according to the instructions from the manufacturer.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"92"}},{"id":"ch7-pass-007","chapter":7,"category":"responsible","question":"How is a child safety seat secured in an older vehicle without the universal anchor system (UAS/LATCH)?","options":["With a rope tied to a solid part of the frame","It cannot be secured in any way","By properly securing the seat using the vehicle seat belt","By placing it on the back seat so it cannot slide"],"answer":2,"explanation":"All newer vehicles and child safety seats come equipped with the universal anchor system or UAS/LATCH. In older vehicles, the child safety seat must be properly secured using the seat belt.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"92"}},{"id":"ch7-pass-008","chapter":7,"category":"responsible","question":"Forward-facing child safety seats are designed for children weighing:","options":["No more than 10 kg (22 pounds)","10 to 18 kg (22 to 40 pounds)","18 to 36 kg (40 to 80 pounds)","More than 40 pounds only"],"answer":1,"explanation":"Forward-facing child safety seats are designed for children 10 to 18 kg (22 to 40 lb). Choose a seat that suits the age and weight of the child.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"93"}},{"id":"ch7-pass-009","chapter":7,"category":"responsible","question":"What must be used with a forward-facing child safety seat?","options":["The vehicle seat belt left unfastened","A spare cushion placed behind the seat","The rear-facing base from the infant seat","The tether strap on the seat and the tether anchor in the vehicle"],"answer":3,"explanation":"A forward-facing seat must be secured with the tether strap attached to the tether anchor in the vehicle; you may need to have a tether anchor installed by your vehicle dealer. Check the instruction manuals for both the vehicle and the child safety seat.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"93"}},{"id":"ch7-pass-010","chapter":7,"category":"responsible","question":"Who should use an approved booster seat before using only the vehicle seat belt?","options":["Children weighing more than 18 kg (40 pounds)","Children weighing less than 18 kg (40 pounds)","All children under 12, whatever their weight","Only children riding without an adult"],"answer":0,"explanation":"Children who weigh more than 18 kg (40 lb) should be secured in an approved booster seat before using only the vehicle seat belt, according to the instructions from the manufacturer.","source":{"chapter":7,"section":"Securing passengers","anchor":"#securing-passengers","page":"94"}},{"id":"ch7-pro-001","chapter":7,"category":"responsible","question":"What does proactive driving mean?","options":["Driving faster than surrounding traffic so hazards pass by sooner","Anticipating possible hazards and taking action to reduce, minimize, or avoid danger before it can occur","Following the vehicle ahead at the minimum legal distance to discourage errors by others","Assuming other drivers will drive carefully and respond correctly"],"answer":1,"explanation":"Proactive driving means anticipating possible hazards and acting to reduce, minimize, or avoid danger before it can occur. The guide says never assume other drivers will drive carefully or respond correctly.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-002","chapter":7,"category":"responsible","question":"In an urban area, how far ahead of your vehicle should you look?","options":["At least 5 to 8 seconds ahead","At least 20 to 25 seconds ahead","Exactly one block, no matter your speed","At least 12 to 15 seconds ahead — about one to one-and-a-half blocks"],"answer":3,"explanation":"In urban areas look at least 12 to 15 seconds ahead, which is about one to one-and-a-half blocks. Most of your attention should go to scanning for hazards developing ahead.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-003","chapter":7,"category":"responsible","question":"When driving in rural areas, your visual lead time should be at least:","options":["20 to 25 seconds ahead","5 to 8 seconds ahead","12 to 15 seconds ahead","60 to 90 seconds ahead"],"answer":0,"explanation":"In rural areas look at least 20 to 25 seconds ahead of your vehicle. This visual lead time gives you the time to respond to hazards ahead.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-004","chapter":7,"category":"responsible","question":"How often should you check your rear view mirrors while driving?","options":["Only before changing lanes or parking","Every 20 to 30 seconds","Every eight to 12 seconds — about every block in an urban area","Only when you hear another vehicle approaching"],"answer":2,"explanation":"Check behind you by glancing in the rear view mirrors every eight to 12 seconds, about every block in an urban area. Also glance when you anticipate slowing or stopping, watch your blind spots, and check the speedometer.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-005","chapter":7,"category":"responsible","question":"Which of these is an example of a fixed hazard?","options":["School children near the road","Intersections","Stale green lights","Icy road surfaces"],"answer":1,"explanation":"Fixed hazards are permanent conditions and situations along the roadway, including restricted vision areas such as curves, hills and hidden driveways, intersections, and merging roadways.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-006","chapter":7,"category":"responsible","question":"Which of the following is a variable hazard that changes through the day?","options":["Curves","Merging roadways","Hills","Left-turning vehicles"],"answer":3,"explanation":"Variable hazards change through the day and include school children and other pedestrians, left-turning vehicles, icy road surfaces, stale green lights and emergency vehicles. Curves, merging roadways and hills are fixed hazards.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-007","chapter":7,"category":"responsible","question":"According to the proactive driving mindset, what should you always plan?","options":["An escape route","A faster lane to reach your exit","A rest stop once every hour","A shorter route for the trip home"],"answer":0,"explanation":"Expect the unexpected and always plan an escape route. Proactive driving is a continuous process of watching your surroundings, thinking about whether hazards are developing, and acting to reduce the risks as the situation changes.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-008","chapter":7,"category":"responsible","question":"What is the purpose of a space cushion around your vehicle?","options":["It keeps other drivers from tailgating you","It increases fuel efficiency in heavy traffic","It gives you room to stop safely or steer around a possible hazard","It is required only on high-speed highways"],"answer":2,"explanation":"A space cushion is the space you leave between yourself and the vehicles ahead, behind, and to either side, so you can stop safely or steer around a possible hazard.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-009","chapter":7,"category":"responsible","question":"A vehicle is following you too closely. If it is safe, what should you do?","options":["Speed up to widen the gap behind you","Reduce your speed just enough to encourage them to pass","Brake firmly to send the tailgater a warning","Increase your speed until they back off"],"answer":1,"explanation":"If it is safe, reduce your speed just enough to encourage the tailgater to pass. If they do not pass, create a wider space cushion between you and the vehicle ahead.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-010","chapter":7,"category":"responsible","question":"When stopping behind another vehicle in traffic, why leave extra space?","options":["So drivers behind can see your brake lights sooner","So you can reverse out of the way more easily","To prevent the vehicle ahead from changing lanes","So you can move into another lane without having to reverse"],"answer":3,"explanation":"Leave enough space so you could move into another lane without reversing. The extra space reduces the risk of hitting the vehicle ahead if you are hit from behind, and lets you move out of the way of a vehicle that may be skidding on ice behind you.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-011","chapter":7,"category":"responsible","question":"You missed your highway exit. What is the correct action?","options":["Continue to the next exit without ever driving in reverse on the roadway","Slow down and reverse once the lane behind you is clear","Stop until you can back up to the off-ramp safely","Make a U-turn at the next intersection and re-enter"],"answer":0,"explanation":"If you miss your exit or turn, continue on to the next exit or intersection. Never drive your vehicle in reverse on a roadway to return to a missed exit or turn.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-012","chapter":7,"category":"responsible","question":"Why should you be in the proper lane well in advance of your exit or turn?","options":["To let other drivers pass you before the intersection","Because lane changes are only legal close to your exit","To avoid making quick and dangerous lane changes","So mirrors need less checking near the exit"],"answer":2,"explanation":"Plan your route and be in the proper lane well before your exit or turning location, which helps you avoid quick and dangerous lane changes. Use your signal lights to let other drivers know what you intend to do.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-013","chapter":7,"category":"responsible","question":"If you must turn sharply to avoid something in your lane, what should you do if possible?","options":["Move onto the right shoulder immediately","Stay on your side of the yellow line","Stop across all lanes to warn other drivers","Accelerate past the obstacle on the left side"],"answer":1,"explanation":"Watch the road ahead and stay alert. If you must turn sharply to avoid something in your lane, stay on your side of the yellow line if possible.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"88"}},{"id":"ch7-pro-014","chapter":7,"category":"responsible","question":"How do you check that you are at least two seconds behind the vehicle in front?","options":["Count the number of vehicles between you and the vehicle ahead","Time how long a landmark takes to pass you","Match your speed to the vehicle two cars ahead","Count one-thousand-and-one, one-thousand-and-two as it passes a fixed object"],"answer":3,"explanation":"When the vehicle ahead passes a fixed object such as a road marking, count one-thousand-and-one, one-thousand-and-two. If the front of your vehicle reaches the object before you finish counting, reduce your speed and count again — the two second rule works at any speed.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"92"}},{"id":"ch7-pro-015","chapter":7,"category":"responsible","question":"What minimum following distance is recommended for drivers of large vehicles such as motor homes?","options":["A minimum of four seconds","A minimum of two seconds","A minimum of eight seconds","At least one vehicle length only"],"answer":0,"explanation":"Under normal conditions you should drive a minimum of two seconds behind the vehicle ahead, with more distance in poor conditions. The exception is large vehicles such as motor homes, which should use a minimum four-second following distance.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"92"}},{"id":"ch7-pro-016","chapter":7,"category":"responsible","question":"You want to send a text message while driving. What should you do?","options":["Text only at red lights when the vehicle is stationary","Use voice-to-text so your eyes stay on the road","Stop in a safe and legal place first","Reply quickly only on familiar roads"],"answer":2,"explanation":"Do not use a cellular phone or other electronic devices while driving — this applies to hands-free phones as well. If you want to make or receive a call, or receive or send a text message, stop in a safe and legal place.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"92"}},{"id":"ch7-pro-017","chapter":7,"category":"responsible","question":"Which activity can result in a fine and three demerits under the Traffic Safety Act?","options":["Checking your speedometer while driving","Entering information on a GPS unit while driving","Glancing in your rear view mirrors","Signalling your next turn in advance"],"answer":1,"explanation":"The Traffic Safety Act includes fines and three demerits for certain distractions, including using a hand-held cell phone, texting or e-mailing, programming portable audio players, entering information on GPS units, reading printed materials, writing or sketching, and personal grooming.","source":{"chapter":7,"section":"Proactive driving","anchor":"#proactive-driving","page":"92"}},{"id":"ch8-bus-001","chapter":8,"category":"sharing","question":"On an undivided highway, a school bus ahead shows alternating amber lights flashing. What does this warn?","options":["The bus is turning at the upcoming intersection","The bus lights are being tested by the driver","The bus is stopping to let students on or off and the red lights will soon flash","The bus wants following traffic to move past quickly"],"answer":2,"explanation":"Alternating amber lights are a warning that the alternating red lights are going to begin flashing and the school bus is stopping to allow students to get on or off; you must be ready to stop.","source":{"chapter":8,"section":"School buses","anchor":"#school-buses","page":"103"}},{"id":"ch8-bus-002","chapter":8,"category":"sharing","question":"You pass a school bus whose alternating amber lights are flashing. How should you pass?","options":["With caution","Only after accelerating well past the limit","At the posted maximum speed for the road","Only after the bus driver waves you by"],"answer":0,"explanation":"If you pass a school bus that has its alternating amber lights flashing, pass with caution.","source":{"chapter":8,"section":"School buses","anchor":"#school-buses","page":"103"}},{"id":"ch8-bus-003","chapter":8,"category":"sharing","question":"A school bus has stopped with alternating red lights flashing on an undivided highway. How far back must you stop?","options":["About five metres (15 feet)","About 20 metres (about four to five car lengths)","About 10 metres (two to three car lengths)","About 50 metres (10 car lengths)"],"answer":1,"explanation":"You must come to a full stop about 20 metres (about four to five car lengths) away, so drivers of other vehicles behind you can see the flashing lights and students crossing the highway.","source":{"chapter":8,"section":"School buses","anchor":"#school-buses","page":"103"}},{"id":"ch8-bus-004","chapter":8,"category":"sharing","question":"When can you leave a stop made behind a school bus with flashing red lights on an undivided highway?","options":["As soon as students are visible inside the bus","After a full 60-second wait","When the roadway beside the bus is clear of students","When the red lights stop flashing and the stop sign is no longer extended"],"answer":3,"explanation":"You must remain stopped until the alternating flashing red lights are turned off and the stop sign is no longer extended.","source":{"chapter":8,"section":"School buses","anchor":"#school-buses","page":"103"}},{"id":"ch8-bus-005","chapter":8,"category":"sharing","question":"On a divided highway, you meet a school bus head-on with its red lights flashing. What may you do?","options":["Stop and wait exactly as if meeting it from behind","Turn around at the median and follow the same rules as the bus","Proceed with caution, watching for pedestrians","Follow the bus until it turns off its lights"],"answer":2,"explanation":"On a highway divided by a median, a driver approaching from the front with the amber or red lights flashing may proceed with caution and watch for pedestrians; this applies only on a divided highway.","source":{"chapter":8,"section":"School buses","anchor":"#school-buses","page":"103"}},{"id":"ch8-bus-006","chapter":8,"category":"sharing","question":"On a divided highway, you approach a school bus from the rear with its amber lights flashing. What applies?","options":["You may pass on the shoulder before the bus stops","Follow the same procedures as for a highway not divided by a median","You may proceed with caution as you face the other direction","You must stop only if students are at the roadside"],"answer":1,"explanation":"When you approach a school bus from the rear on a divided highway and its alternating amber lights are flashing, follow the same procedures as you would for a highway that is not divided by a median.","source":{"chapter":8,"section":"School buses","anchor":"#school-buses","page":"103"}},{"id":"ch8-com-001","chapter":8,"category":"sharing","question":"A large vehicle is ahead of you approaching a traffic light. What must you never do?","options":["Follow it at the normal urban following distance","Change lanes to the left for a better view","Move into the space in front of the large vehicle","Leave a large gap behind it before the intersection"],"answer":2,"explanation":"Never move into the space in front of a large vehicle that is approaching a traffic light; if the light changes to red, the driver needs that extra space for stopping because a large vehicle needs extra distance to stop.","source":{"chapter":8,"section":"Commercial vehicles","anchor":"#commercial-vehicles","page":"99"}},{"id":"ch8-com-002","chapter":8,"category":"sharing","question":"You are stopping on a hill behind a large vehicle. Why leave extra space in front of your vehicle?","options":["The large vehicle may roll back when the driver releases the brakes","The large vehicle will need the space to swing into your lane","Your front brakes work less well downhill","Large vehicles always stop further up the hill"],"answer":0,"explanation":"If you are on a hill and stopping behind a large vehicle, leave extra space in front of your vehicle; the large vehicle may roll back when the driver releases the brakes.","source":{"chapter":8,"section":"Commercial vehicles","anchor":"#commercial-vehicles","page":"99"}},{"id":"ch8-com-003","chapter":8,"category":"sharing","question":"You are behind a large vehicle and cannot see both of its side mirrors. What does this tell you?","options":["The mirrors are set for the truck operator alone","The vehicle is signalling a lane change","The mirrors must be cleaned before continuing","You are too close behind the large vehicle"],"answer":3,"explanation":"If you are driving behind a large vehicle and cannot see both of its side mirrors, you are too close; if you can see the driver in the side mirror, then the driver can see you.","source":{"chapter":8,"section":"Commercial vehicles","anchor":"#commercial-vehicles","page":"99"}},{"id":"ch8-com-004","chapter":8,"category":"sharing","question":"After passing a heavy commercial vehicle, what should you do before re-entering your lane?","options":["Pull in right away so the driver can see your brake lights","Leave extra room before returning to your lane in front of it","Stay beside the vehicle until the next intersection","Return only once your speed matches its speed"],"answer":1,"explanation":"Heavy commercial vehicles require more distance to slow or stop, so leave extra room before you return to your lane in front of one; this also applies to changing lanes in front of one.","source":{"chapter":8,"section":"Commercial vehicles","anchor":"#commercial-vehicles","page":"99"}},{"id":"ch8-com-005","chapter":8,"category":"sharing","question":"A large vehicle is turning right at an intersection ahead. What does the guide warn against?","options":["Crossing the intersection while the light is green","Following more than two vehicle lengths behind","Passing the large vehicle on its left side","Driving in the space on the right of the large vehicle"],"answer":2,"explanation":"When a large vehicle is turning to the right, stay well back and do not drive in the space on the right of the large vehicle; your vehicle could be squeezed between the large vehicle and the curb or edge of the road.","source":{"chapter":8,"section":"Commercial vehicles","anchor":"#commercial-vehicles","page":"99"}},{"id":"ch8-com-006","chapter":8,"category":"sharing","question":"A large vehicle is turning onto the road you are on. What should you expect, and what should you do?","options":["The operator must stay inside a single lane, so keep moving","The operator may cross the centre line or use part of your lane; stop well back","The operator will always stop and wait for traffic to clear","The operator will complete the turn from the far left lane only"],"answer":1,"explanation":"The operator may need to drive across the centre line, cut a corner, or use part of your lane to complete the turn; stop back from the intersection to allow the operator the space to complete the turn.","source":{"chapter":8,"section":"Commercial vehicles","anchor":"#commercial-vehicles","page":"99"}},{"id":"ch8-com-007","chapter":8,"category":"sharing","question":"What typically happens when traffic builds up behind an oversized vehicle load or convoy?","options":["The whole unit typically moves off the roadway so traffic can pass","The pilots close the highway until the load leaves the route","The load speeds up to clear the traffic queue quickly","Traffic must wait until the next designated passing bay"],"answer":0,"explanation":"Drivers of oversized vehicle loads and convoys typically look for opportunities to allow traffic to pass; if traffic buildup becomes heavy, the entire unit will typically move off the travelled portion of the roadway. These loads often travel at reduced speed, with pilot vehicles at the front and rear of the convoy.","source":{"chapter":8,"section":"Commercial vehicles","anchor":"#commercial-vehicles","page":"99"}},{"id":"ch8-cyc-001","chapter":8,"category":"sharing","question":"Who must wear an approved bicycle safety helmet by law?","options":["Every cyclist and bicycle passenger in Alberta","Cyclists or passengers on a bicycle who are under 18 years of age","Only new cyclists during their first year of riding","Riders of bicycles on sidewalks and pathways only"],"answer":1,"explanation":"The law requires cyclists or passengers on a bicycle who are under 18 years of age to wear an approved bicycle safety helmet.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-cyc-002","chapter":8,"category":"sharing","question":"A cyclist walks beside and pushes a bicycle along the road. Legally, this cyclist is:","options":["a disabled vehicle operator","treated as a slow-moving vehicle","a pedestrian","exempt from all traffic rules"],"answer":2,"explanation":"A cyclist who is walking beside and pushing a bicycle is a pedestrian.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-cyc-003","chapter":8,"category":"sharing","question":"Besides keeping close to the right curb, why might a cyclist ride further out?","options":["To hold a place in the queue at a red light","To let following traffic see around them better","To signal that they are about to stop pedalling","To avoid drainage grates, pot holes, debris, or slippery surfaces"],"answer":3,"explanation":"Cyclists are required to ride as close as practicable to the right curb, but may ride further out when avoiding drainage grates, pot holes, debris, gravel or sand, wet or slippery surfaces, and rutted or grooved pavement.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-cyc-004","chapter":8,"category":"sharing","question":"A cyclist seated on a bicycle waits at an intersection for a green light. What applies to the cyclist?","options":["Cyclists must always give way to motor vehicles at signal lights","The same rights and responsibilities as any other vehicle waiting to proceed","The cyclist may proceed on the pedestrian signal","The cyclist must dismount and wait on the sidewalk"],"answer":1,"explanation":"A bicycle being ridden is a vehicle; a cyclist seated on it at an intersection, waiting for a traffic control signal, has the same rights and responsibilities as any other vehicle waiting to proceed.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-cyc-005","chapter":8,"category":"sharing","question":"What should you do before turning right when a cyclist may be riding beside your vehicle?","options":["Tap the horn to move the cyclist away","Speed past the cyclist before the turn","Do a shoulder check of your blind spots to the right","Stay close to the curb through the whole turn"],"answer":2,"explanation":"When preparing to turn right, watch for cyclists who may ride along side your vehicle and remember to do a shoulder check to your blind spots to the right.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-cyc-006","chapter":8,"category":"sharing","question":"When a bicycle is used after dark, what must it be equipped with?","options":["At least one headlamp, one red tail lamp, and one rear red reflector","A headlamp, tail lamp, and reflector on the front wheel","Two headlamps and two red tail lamps","Only a headlamp when riding under street lights"],"answer":0,"explanation":"For cycling after dark, the bicycle needs at least one headlamp (but not more than two), one red tail lamp, and at least one red reflector mounted on the rear; wear bright and reflective clothing.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-dg-001","chapter":8,"category":"sharing","question":"Which vehicles can be required by law or company policy to stop at railway crossings?","options":["Any vehicle pulling two or more trailers","Only school buses on rural routes","Vehicles heavier than 5,000 kilograms","Vehicles transporting passengers or dangerous goods"],"answer":3,"explanation":"Commercial vehicles transporting passengers or dangerous goods can be required by law or company policy to stop at railway crossings.","source":{"chapter":8,"section":"Vehicles carrying passengers or dangerous goods","anchor":"#vehicles-carrying-passengers-or-dangerous-goods","page":"106"}},{"id":"ch8-dg-002","chapter":8,"category":"sharing","question":"What should you be prepared for when following a commercial vehicle near a railway crossing?","options":["To pass it before it reaches the stop line","To stop, because it may be required to stop at the crossing","To change lanes away from the tracks","To sound your horn as a caution near the tracks"],"answer":1,"explanation":"Commercial vehicles transporting passengers or dangerous goods can be required by law or company policy to stop at railway crossings, so be prepared to stop when following one near a crossing.","source":{"chapter":8,"section":"Vehicles carrying passengers or dangerous goods","anchor":"#vehicles-carrying-passengers-or-dangerous-goods","page":"106"}},{"id":"ch8-fun-001","chapter":8,"category":"sharing","question":"You are driving in a funeral procession and reach an intersection with a red traffic light. What are you permitted to do?","options":["Stop briefly, then continue through on the red","Continue through the intersection without stopping, with your headlights on","Circle the block and rejoin the procession later","Turn right on the red to stay with the procession"],"answer":1,"explanation":"Participants in a funeral procession are permitted to continue through an intersection with a stop sign or red traffic light without stopping, and headlights must be turned on; you may only proceed if closely following the vehicle in front of you in the procession and it is safe to do so.","source":{"chapter":8,"section":"Funeral processions","anchor":"#funeral-processions","page":"106"}},{"id":"ch8-fun-002","chapter":8,"category":"sharing","question":"You meet a funeral procession that has the right-of-way. What should you do?","options":["Yield until it has passed, and do not pass through it","Fill a gap in the procession to keep traffic moving","Pass its rear vehicles when the road ahead is open","Sound your horn and proceed through the intersection"],"answer":0,"explanation":"Do not pass through a funeral procession; yield the right-of-way until it has passed before proceeding.","source":{"chapter":8,"section":"Funeral processions","anchor":"#funeral-processions","page":"106"}},{"id":"ch8-log-001","chapter":8,"category":"sharing","question":"In which case must you never pass a log hauling truck?","options":["When its load appears lighter than usual","When it signals to return to the highway after a stop","When it is slowing for a hill on the highway","When it is turning left or right off the highway"],"answer":3,"explanation":"Never pass a log hauling truck that is turning left or right off the highway; log hauling vehicles are long and heavy when loaded.","source":{"chapter":8,"section":"Log hauling vehicles","anchor":"#log-hauling-vehicles","page":"102"}},{"id":"ch8-log-002","chapter":8,"category":"sharing","question":"How far from the rear of a log hauling truck may the logs extend?","options":["They end at the tailgate of the truck","As long as nine metres (30 feet)","As long as three metres (10 feet)","As long as 20 metres (65 feet)"],"answer":1,"explanation":"The extension of the logs from the rear of the truck may be as long as nine metres (30 feet).","source":{"chapter":8,"section":"Log hauling vehicles","anchor":"#log-hauling-vehicles","page":"102"}},{"id":"ch8-log-003","chapter":8,"category":"sharing","question":"What can happen when a loaded log hauling vehicle turns?","options":["The logs can block all or some of the lanes of the highway","The logs must be shortened before a turn is made","The operator must stop and reload before turning","The vehicle cannot turn without unloading first"],"answer":0,"explanation":"When these trucks are turning, the logs can block all or some of the lanes of the highway, which is why you must never pass a log hauling truck that is turning off the highway.","source":{"chapter":8,"section":"Log hauling vehicles","anchor":"#log-hauling-vehicles","page":"102"}},{"id":"ch8-lrt-001","chapter":8,"category":"sharing","question":"Why must pedestrians, cyclists, and motorists use caution at LRT crossings in Calgary and Edmonton?","options":["LRT trains are powered by electricity, which makes them very quiet","LRT tracks are hidden below the road surface","LRT trains reverse through the crossings each hour","LRT crossings use no warning devices at all"],"answer":0,"explanation":"LRT systems are powered by electricity, which makes them very quiet. LRT crossings are similar to other railway crossings and require pedestrians, cyclists, and motorists to use caution.","source":{"chapter":8,"section":"Light rail transit","anchor":"#light-rail-transit","page":"106"}},{"id":"ch8-lrt-002","chapter":8,"category":"sharing","question":"What do the warning devices at LRT crossings, such as signals, signs, bells, and gates, all mean?","options":["Slow down, then cross when the near track is clear","Yield only to trains travelling on your side","Stop and do not cross the tracks","Stop only when a train is in sight"],"answer":2,"explanation":"LRT crossings use a variety of warning devices such as regular traffic signal lights, signs, bells, and gates; these warnings all mean stop and do not cross the tracks.","source":{"chapter":8,"section":"Light rail transit","anchor":"#light-rail-transit","page":"106"}},{"id":"ch8-lrt-003","chapter":8,"category":"sharing","question":"An LRT train has just passed through the crossing gates. Why must you still not drive around them?","options":["The gates stay down during a set time interval","Emergency crews close LRT crossings at random","The rails remain energized for passing trains only","Another train may be coming from the other direction"],"answer":3,"explanation":"Never drive around the gates, even if an LRT train has just passed; another one may be coming from the other direction. Due to its weight and speed, an LRT train may take up to 100 metres (330 feet) to stop in an emergency.","source":{"chapter":8,"section":"Light rail transit","anchor":"#light-rail-transit","page":"106"}},{"id":"ch8-moto-001","chapter":8,"category":"sharing","question":"A motorcycle rider often travels in the left portion of their lane. What does this usually mean?","options":["The rider intends to turn left at the next intersection","The rider is making themselves more visible to others","The rider is yielding the right portion to traffic","The rider wants following traffic to overtake"],"answer":1,"explanation":"Motorcycle riders often travel in the left portion of their lane to be more visible to other road users; it does not mean they will be turning left.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-moto-002","chapter":8,"category":"sharing","question":"When is it acceptable to share a lane with a motorcycle rider?","options":["In heavy traffic moving at low speeds","Whenever the lane is marked for two vehicles","Only when the motorcycle is stopped at a light","Never; a motorcycle rider needs the whole lane"],"answer":3,"explanation":"Never share a lane with a motorcycle rider; a motorcycle rider needs the whole lane to travel safely.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-moto-003","chapter":8,"category":"sharing","question":"Why allow extra space when following a motorcycle?","options":["Motorcycles can stop very quickly","Motorcycles travel faster downhill than other vehicles","Riders cannot see vehicles close behind them at night","Motorcycle signals stay lit for a shorter time"],"answer":0,"explanation":"When following a motorcycle, allow extra space because motorcycles can stop very quickly; poor weather, road conditions, or road hazards could also make the rider lose control.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-ohv-001","chapter":8,"category":"sharing","question":"Which road users should you watch for near, or attempting to cross, the highway?","options":["Operators of all-terrain vehicles, snowmobiles, or similar off-highway vehicles","Only farm tractors crossing at marked approaches","Only emergency vehicles using the gravel shoulder","Only vehicles towing boats leaving launch sites"],"answer":0,"explanation":"Be aware of off-highway vehicles and their operators who may be near or attempting to cross the highway, and be cautious when encountering all-terrain vehicles or snowmobiles.","source":{"chapter":8,"section":"Off-highway vehicles","anchor":"#off-highway-vehicles","page":"106"}},{"id":"ch8-ohv-002","chapter":8,"category":"sharing","question":"How should you drive when encountering an all-terrain vehicle or snowmobile near the highway?","options":["Hold your speed, because they must clear the way","Follow closely to encourage them to pull over","Pass right away before their path changes","With caution, staying alert until they are clear"],"answer":3,"explanation":"Be cautious when encountering all-terrain vehicles, snowmobiles, or similar vehicles, which may be near or attempting to cross the highway.","source":{"chapter":8,"section":"Off-highway vehicles","anchor":"#off-highway-vehicles","page":"106"}},{"id":"ch8-ped-001","chapter":8,"category":"sharing","question":"When you approach a pedestrian-activated traffic light flashing yellow, what should you do?","options":["Maintain full speed, as the signal directs pedestrians only","Slow to 30 km/h and yield to pedestrians wanting to cross the street","Stop and wait for the light to change to solid green","Stop, then proceed if no one is already on the crosswalk"],"answer":1,"explanation":"A yellow flashing pedestrian-activated traffic light means slow to 30 km/h and yield to pedestrians wanting to cross the street.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-ped-002","chapter":8,"category":"sharing","question":"When stopping for a pedestrian at a crosswalk, how far back should you stop?","options":["Right at the crosswalk line, to hold your place in traffic","About one car length back from the pedestrian","About two to three car lengths back, so other lanes can see the pedestrian","As far back as the nearest driveway"],"answer":2,"explanation":"Stop far enough back, about two to three car lengths, so that traffic in other lanes will be able to see the pedestrian and have time to stop.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-ped-003","chapter":8,"category":"sharing","question":"You near a crosswalk and the vehicle in front of you is slowing down. What must you never do?","options":["Pass that vehicle as you approach the crosswalk","Stop behind it and wait for it to move","Slow down and be ready to stop behind it","Watch the crosswalk for pedestrians as you approach"],"answer":0,"explanation":"Never pass another vehicle when you are approaching a crosswalk; there is always a chance that the other vehicle is slowing or stopping for a pedestrian.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-ped-004","chapter":8,"category":"sharing","question":"A pedestrian has entered an unmarked crosswalk at an intersection. What does the law require you to do?","options":["Yield only if a municipal bylaw marks the crossing","Proceed, because unmarked crossings give no protection","Stop only if the pedestrian is moving quickly","Yield the right-of-way to the pedestrian"],"answer":3,"explanation":"When a pedestrian has entered a marked or unmarked crosswalk, you must yield the right-of-way. Not all crosswalks are marked, but the rules of pedestrian safety apply at all intersections.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-ped-005","chapter":8,"category":"sharing","question":"How should you respond to visually impaired pedestrians?","options":["Wave them across the street from your vehicle","Be considerate; some carry a white cane or use a guide dog","Overtake them before they step onto the road","Avoid residential areas where they usually walk"],"answer":1,"explanation":"Be considerate of visually impaired pedestrians; some will have a white cane or guide dog.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-ped-006","chapter":8,"category":"sharing","question":"At night, what does it mean to not overdrive your headlights?","options":["Keep high beams on at all times after dark","Drive only on well-lit city streets","Drive so you can stop within the distance you can clearly see","Reduce speed only where signs set a lower night limit"],"answer":2,"explanation":"Do not overdrive your headlights: you should drive so you are able to stop your vehicle within the distance you can clearly see. Be alert for pedestrians, who can be difficult to see, especially in dark clothing.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-ped-007","chapter":8,"category":"sharing","question":"Why should you glance under parked vehicles ahead in residential areas?","options":["To look for toys, feet, or bicycle wheels that warn children may be near","To identify potholes hidden beside the parked cars","To check whether a parked vehicle has its engine running","To find a gap to pull ahead of slower traffic"],"answer":0,"explanation":"Children can be unpredictable and may be around parked vehicles, riding bikes, or playing on the street. Feet, toys, and bicycle wheels under parked vehicles provide warning that you may need to stop.","source":{"chapter":8,"section":"Vulnerable road users","anchor":"#vulnerable-road-users","page":"99"}},{"id":"ch8-rail-001","chapter":8,"category":"sharing","question":"What should you do when you see a railway advance warning sign?","options":["Speed up to clear the crossing before a train arrives","Choose a lower gear and stay hard to the right","Stop, then proceed once the tracks appear empty","Look, listen, and reduce speed because you may have to stop"],"answer":3,"explanation":"Advance warning signs tell you to look, listen, and reduce speed because you may have to stop for a train. The speed sign below the advance warning sign is the recommended speed for the railway crossing, and it will be less than the posted speed for the road.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"105"}},{"id":"ch8-rail-002","chapter":8,"category":"sharing","question":"An X and a stop line are painted on the approach to a railway crossing. If you must stop for a train, where do you stop?","options":["Just past the stop line, closer to the tracks","Wherever you can still see down the tracks clearly","Before the stop line","Only after the front wheels reach the X"],"answer":2,"explanation":"Pavement markings, such as an X and/or stop line, may be marked at the approach to some railway crossings; if you must stop for a train, do it before the stop line.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"105"}},{"id":"ch8-rail-003","chapter":8,"category":"sharing","question":"What does a railway crossing sign, found at all public railway crossings, mean for drivers?","options":["Stop, look, and proceed at 30 km/h","Drivers must yield to all trains","Stop only when the bells ring at the crossing","Trains use the crossing only outside city limits"],"answer":1,"explanation":"A railway crossing sign means drivers must yield to all trains.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"105"}},{"id":"ch8-rail-004","chapter":8,"category":"sharing","question":"A railway crossing sign displays the number 3. What does this show?","options":["That the crossing is three kilometres ahead","That this is the third crossing on the route","That three trains use the crossing each day","That there are three railway tracks at the crossing"],"answer":3,"explanation":"If there is more than one railway track, the crossing sign will show the number of tracks at that crossing.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"105"}},{"id":"ch8-rail-005","chapter":8,"category":"sharing","question":"At a crossing marked with a railway crossing sign, when must you stop?","options":["Only when a flagger stands at the crossing","Whenever the pavement markings show an X","When a train is visible or sounding a signal within 500 metres (five city blocks)","Only after dark or in poor weather"],"answer":2,"explanation":"You must stop when a train is visible or sounding a signal and approaching within 500 metres (about five city blocks) of the crossing. Always yield to trains and never try to outrace one to a crossing.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"105"}},{"id":"ch8-rail-006","chapter":8,"category":"sharing","question":"A stop sign stands at a railway crossing. Between what distances from the nearest rail must you come to a complete stop?","options":["Between five metres (15 feet) and 15 metres (50 feet)","Between one metre and five metres from the rail","Between 15 metres and 50 metres from the rail","At least 500 metres before the crossing"],"answer":0,"explanation":"A stop sign at a railway crossing requires the driver to come to a complete stop between five metres (15 feet) and 15 metres (50 feet) from the nearest rail; do not proceed until you are sure a train is not approaching.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"105"}},{"id":"ch8-rail-007","chapter":8,"category":"sharing","question":"At a crossing with flashing red light signals and a bell, where must the vehicle nearest the crossing stop?","options":["With the front bumper just past the stop line","At least five metres back from the nearest rail","Where the X marking begins on the pavement","Between the two warning posts"],"answer":1,"explanation":"Stop when the lights begin to flash and the bells ring; the driver of the vehicle nearest the crossing must stop at least five metres back from the nearest rail, and must not proceed until the lights and bells have stopped and the train has passed or has come to a complete stop.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"106"}},{"id":"ch8-rail-008","chapter":8,"category":"sharing","question":"The last car of a train has passed a multi-track crossing. What must you confirm before moving?","options":["That the bells have rung for a full minute","That the pavement markings are dry","That vehicles behind you are also ready","That another train is not approaching on any track"],"answer":3,"explanation":"When the last car of a train passes the crossing, make sure that another train is not coming before you move ahead. A second train can come on another track from a different direction, and you may not hear it because of the noise of the first one.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"106"}},{"id":"ch8-rail-009","chapter":8,"category":"sharing","question":"The gate at a railway crossing is lowering in front of you. What must you do?","options":["Do not cross the tracks; never drive around the gates","Pass behind the gate arm if no train is audible","Follow the vehicle ahead through the crossing","Wait inside the gate line until it lifts"],"answer":0,"explanation":"Never drive around the gates; if the gate is down, is raising, or is lowering, do not cross the tracks.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"106"}},{"id":"ch8-rail-010","chapter":8,"category":"sharing","question":"Your vehicle stalls on a railway crossing and a train is coming. What should you do?","options":["Stay inside and restart the engine immediately","Push the vehicle clear before the train arrives","Get everyone out, and move away from the tracks toward the oncoming train","Stay with the vehicle and wait for help to arrive"],"answer":2,"explanation":"Get everyone out of the vehicle and away from the track immediately. If a train is coming, move well away from your vehicle and the tracks, and if possible go in the direction where the train is approaching to avoid flying debris if the train hits the stalled vehicle.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"106"}},{"id":"ch8-rail-011","chapter":8,"category":"sharing","question":"Even under full emergency braking, about how far can it take a train to stop?","options":["Within two to three car lengths","A kilometre or more","Within 100 metres (330 feet)","Within 500 metres of the crossing"],"answer":1,"explanation":"It may take a kilometre or more for a train to stop, even under full emergency braking, so never try to outrace a train and always yield to it.","source":{"chapter":8,"section":"Railway crossings","anchor":"#railway-crossings","page":"106"}},{"id":"ch8-snow-001","chapter":8,"category":"sharing","question":"In winter, a vehicle ahead displays flashing amber and red lights. What does this tell you?","options":["An oversized load is changing lanes ahead","A funeral procession is forming ahead","A school bus is about to pick up students","A snowplow is ahead"],"answer":3,"explanation":"Snowplows are equipped with flashing amber and red lights to make them more visible: flashing amber and red means snowplow ahead.","source":{"chapter":8,"section":"Snowplows","anchor":"#snowplows","page":"103"}},{"id":"ch8-snow-002","chapter":8,"category":"sharing","question":"In which situation is passing a snowplow strictly prohibited?","options":["When the view along the side of the snowplow is obstructed","When the plow has just finished clearing your lane","When the plow travels a little below the speed limit","When the shoulder beside the plow is freshly graded"],"answer":0,"explanation":"Passing a snowplow is strictly prohibited when the view along the side of the snowplow is obstructed, when passing impedes the operation of the snowplow, or when the act of passing cannot be done safely.","source":{"chapter":8,"section":"Snowplows","anchor":"#snowplows","page":"103"}},{"id":"ch8-snow-003","chapter":8,"category":"sharing","question":"How do snowplow operators open a chance for traffic to pass?","options":["By raising the plow and stopping at rest areas","By moving to the side of the road, where safe, every five to eight kilometres","By switching to a green flashing light to invite passing","By slowing near the next intersection and waving traffic by"],"answer":1,"explanation":"Snow plow operators move to the side of the road, where it is safe, every five to eight kilometres to allow vehicles to pass; even when passing is permitted, it is safer to stay well back until the operator can safely move over.","source":{"chapter":8,"section":"Snowplows","anchor":"#snowplows","page":"103"}},{"id":"ch8-snow-004","chapter":8,"category":"sharing","question":"A snowplow is approaching from the opposite direction. What should you watch for in your lane?","options":["The plow dropping its blade on the centre line","The plow switching its lights to high beam","An oncoming vehicle passing the snowplow using your lane","Sand thrown from the plow reaching your windshield"],"answer":2,"explanation":"When a snowplow is approaching from the opposite direction, look ahead in your lane carefully; there may be an oncoming vehicle that is passing the snowplow using your lane, so be prepared to use an escape route.","source":{"chapter":8,"section":"Snowplows","anchor":"#snowplows","page":"103"}},{"id":"ch9-fit-001","chapter":9,"category":"law","question":"Which of the following can affect your ability to drive safely?","options":["Only alcohol and illegal street drugs","Alcohol, drugs, some medications, stress, fatigue and lack of sleep","Only fatigue from very long trips","Only prescription painkillers"],"answer":1,"explanation":"Alcohol and drugs impair judgement and reaction time, and impairment begins with the first drink or drug use. Some prescription and over-the-counter medications have a similar effect, and stress, fatigue and lack of sleep also negatively affect your driving.","source":{"chapter":9,"section":"Driver fitness","anchor":"#driver-fitness","page":"106"}},{"id":"ch9-fit-002","chapter":9,"category":"law","question":"Which of the following is listed as a cause of fatigue while driving?","options":["Eye strain and illness","Listening to the radio","Cold, dry winter air","Talking with passengers"],"answer":0,"explanation":"Fatigue can be caused by lack of sleep or rest, emotional stress, boredom, driving for long periods of time, physical activity, illness, and eye strain.","source":{"chapter":9,"section":"Driver fitness","anchor":"#driver-fitness","page":"106"}},{"id":"ch9-fit-003","chapter":9,"category":"law","question":"Which factor can intensify fatigue on a trip?","options":["A cool, well-ventilated vehicle","Scanning the road ahead and behind","Overeating, alcohol or drug use, or a warm and comfortable vehicle","Frequent stops to walk around your vehicle"],"answer":2,"explanation":"Fatigue can be intensified by overeating, alcohol or drug use, or even a warm and comfortable vehicle. Keeping the vehicle well ventilated and stopping for a rest helps reduce fatigue.","source":{"chapter":9,"section":"Driver fitness","anchor":"#driver-fitness","page":"106"}},{"id":"ch9-fit-004","chapter":9,"category":"law","question":"How does fatigue affect your driving?","options":["It shortens your reaction time and sharpens judgement","It has no effect if you drink coffee before driving","It increases your reaction time and impairs judgement and decision-making","It only matters when driving at night"],"answer":2,"explanation":"Fatigue increases the time it takes you to react and impairs judgement and decision-making, which can lead to driving off the road, into another lane, or into oncoming traffic.","source":{"chapter":9,"section":"Driver fitness","anchor":"#driver-fitness","page":"106"}},{"id":"ch9-fit-005","chapter":9,"category":"law","question":"You begin to feel tired while driving. What should you do?","options":["Speed up to reach your destination sooner","Turn up the radio and keep driving","Drive more closely behind another vehicle to stay alert","Stop for a rest and walk around your vehicle"],"answer":3,"explanation":"If you are feeling tired, stop for a rest and walk around your vehicle. You should also start the trip well rested and never drive after drinking alcohol or taking drugs.","source":{"chapter":9,"section":"Driver fitness","anchor":"#driver-fitness","page":"106"}},{"id":"ch9-fit-006","chapter":9,"category":"law","question":"Which medications can impair your vehicle-handling ability and judgement?","options":["Only medications taken together with alcohol","Only strong prescription painkillers","Some prescription and over-the-counter medications","No medication affects driving if a doctor prescribed it"],"answer":2,"explanation":"Some prescription and non-prescription (over-the-counter) medications can impair driving, with side effects such as drowsiness or dizziness. Talk with your doctor and pharmacist about the effects of everything you take.","source":{"chapter":9,"section":"Driver fitness","anchor":"#driver-fitness","page":"106"}},{"id":"ch9-fit-007","chapter":9,"category":"law","question":"On average each year from 2016 to 2020, how many people were killed and injured in Alberta collisions involving impaired driving?","options":["About 38 killed and 535 injured","About 18 killed and 135 injured","About 83 killed and 350 injured","About 138 killed and 1,535 injured"],"answer":0,"explanation":"Approximately 38 people were killed and 535 people were injured each year on average in collisions involving impaired driving. Driving while impaired remains a major cause of traffic deaths and injuries in Alberta.","source":{"chapter":9,"section":"Driver fitness","anchor":"#driver-fitness","page":"106"}},{"id":"ch9-laws-001","chapter":9,"category":"law","question":"Which law makes impaired driving a criminal offence in Canada?","options":["The Traffic Safety Act","Municipal traffic bylaws","The Insurance Act","The Criminal Code of Canada"],"answer":3,"explanation":"Impaired driving offences are federal offences under the Criminal Code of Canada. Alberta adds provincial administrative penalties through the Immediate Roadside Sanctions (IRS) program.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-002","chapter":9,"category":"law","question":"Which of the following is an impaired driving offence under the Criminal Code of Canada?","options":["Refusing to provide a breath or blood sample","Failing to signal a lane change","Driving 20 km/h over the posted limit","Parking in a fire lane"],"answer":0,"explanation":"Criminal Code offences include impaired driving regardless of blood alcohol or drug content, being over the legal limit, refusing to provide a breath or blood sample, impaired driving causing bodily harm or death, and driving while suspended or disqualified.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-003","chapter":9,"category":"law","question":"A driver is found guilty under section 320 of the Criminal Code for a first impaired driving offence. What disqualification applies?","options":["One month","One year from the date of the finding of guilt","Six months","Five years"],"answer":1,"explanation":"On a first guilty finding, you are disqualified from driving and your licence is suspended for one year from the date of the finding of guilt.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-004","chapter":9,"category":"law","question":"A driver has one prior impaired offence in the last 10 years and is convicted again. What is the disqualification?","options":["One year","Two years","Three years from the date of the conviction","Ten years"],"answer":2,"explanation":"With one prior offence in the last 10 years, you are disqualified from holding a driver's licence for three years from the date of the conviction.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-005","chapter":9,"category":"law","question":"A driver has two or more prior impaired offences in the last 10 years. What disqualification applies to a new conviction?","options":["Three years","Four years","Seven years","Five years from the date of the conviction"],"answer":3,"explanation":"With two or more prior offences in the last 10 years, you are disqualified from holding a driver's licence for five years from the date of the conviction.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-006","chapter":9,"category":"law","question":"An impaired driving offence causes death or injury. What is the minimum licence suspension, even for a first offender?","options":["One year","Two years","Five years","There is no minimum"],"answer":2,"explanation":"If a death or injury occurs as a result of an impaired offence, the minimum licence suspension is five years, even for a first offender.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-007","chapter":9,"category":"law","question":"What does Alberta's Immediate Roadside Sanctions (IRS) program do at roadside?","options":["Gives only a warning letter to every driver","Applies immediate penalties, including escalating suspensions, fines and vehicle seizures","Sends every case straight to criminal court with no roadside penalties","Charges a single fixed fine for every driver"],"answer":1,"explanation":"The IRS program is Alberta's one impaired driving program, with an escalating approach: licence suspensions, fines and vehicle seizure lengths, mandatory education programs, and the Ignition Interlock Program.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-008","chapter":9,"category":"law","question":"Who does the IRS: 24-hour program apply to?","options":["Drivers impaired by a physical or medical condition, or by drugs or alcohol","Only novice GDL drivers","Only commercial drivers","Drivers who have 15 or more demerit points"],"answer":0,"explanation":"The IRS: 24-hour program issues a 24-hour licence disqualification when a driver's ability to operate a motor vehicle is impaired by a physical or medical condition, or by drugs or alcohol.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-009","chapter":9,"category":"law","question":"Under IRS ZERO: Novice, what penalties apply to a Class 7 learner or Class 5-GDL driver for any alcohol or drug use?","options":["A warning letter only","A one-year suspension and a $2,000 fine","A 30-day suspension, a seven-day vehicle seizure and a $200 fine plus a 20 per cent surcharge","A three-day suspension with no fine"],"answer":2,"explanation":"IRS ZERO: Novice takes a zero tolerance approach for any alcohol and/or drugs for novice drivers in the Class 7 learner's licence or Class 5-GDL licence category: an immediate 30-day suspension, a seven-day seizure, and a $200 fine plus a 20 per cent victim fine surcharge.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-010","chapter":9,"category":"law","question":"What penalty applies to a commercial driver's first IRS ZERO: Commercial occurrence?","options":["A 15-day suspension and a $600 fine","A three-day suspension and a $300 fine plus a 20 per cent surcharge","A 30-day suspension and a $1,200 fine","A one-year suspension and vehicle seizure"],"answer":1,"explanation":"There is zero tolerance for any alcohol or drug for a commercial driver operating in a commercial capacity. A first occurrence is a three-day suspension and a $300 fine; the second is 15 days and $600; the third is 30 days and $1,200.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-011","chapter":9,"category":"law","question":"IRS: WARN applies when a driver's blood alcohol concentration equals or exceeds which level?","options":["80 milligrams of alcohol in 100 millilitres of blood","20 milligrams of alcohol in 100 millilitres of blood","100 milligrams of alcohol in 100 millilitres of blood","50 milligrams of alcohol in 100 millilitres of blood"],"answer":3,"explanation":"IRS: WARN applies at 50 or more milligrams of alcohol in 100 millilitres of blood. The 80 mg level, impairment to any degree, and refusing a demand fall under IRS: FAIL.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-012","chapter":9,"category":"law","question":"What happens on a driver's first IRS: WARN occurrence?","options":["A three-day licence suspension, a three-day vehicle seizure and a $300 fine","A 30-day licence suspension and a $1,200 fine","A one-year suspension with an interlock device","Only a fine, with no suspension"],"answer":0,"explanation":"A first IRS: WARN occurrence brings a three-day suspension, a three-day vehicle seizure and a $300 fine, plus a 20 per cent victim fine surcharge. A second occurrence requires the Crossroads course; a third requires the IMPACT Program.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-013","chapter":9,"category":"law","question":"A third IRS: WARN occurrence brings a 30-day suspension and a $1,200 fine. What else is required?","options":["Completing the Crossroads course","Nothing beyond the fine","Completing the IMPACT Program, along with a seven-day vehicle seizure","A fixed one-year suspension"],"answer":2,"explanation":"A third WARN occurrence includes a 30-day licence suspension, a seven-day vehicle seizure, the requirement to complete the IMPACT Program, and a $1,200 fine. The second occurrence requires the Crossroads course (or Planning Ahead as an equivalent).","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-014","chapter":9,"category":"law","question":"When does the IRS: FAIL program apply?","options":["At 50 milligrams of alcohol in 100 millilitres of blood","At a blood alcohol concentration of 80 mg or more per 100 mL, or when a driver is impaired to any degree","Whenever any alcohol at all is found in the body","Only for drug impairment, never alcohol"],"answer":1,"explanation":"IRS: FAIL applies at the criminal level, including a blood alcohol concentration of 80 milligrams or more per 100 millilitres of blood within two hours of driving, impairment to any degree by alcohol or a drug, and failing or refusing to comply with a demand.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-015","chapter":9,"category":"law","question":"What licence suspension applies to a first IRS: FAIL occurrence?","options":["A one-month suspension","Only a $300 fine","A 90-day period with no driving at all, followed by a further 12-month suspension","A three-day suspension"],"answer":2,"explanation":"The first 90 days allow no driving under any circumstances; during the 12-month stage the driver may drive an interlock-equipped vehicle under the IRS: FAIL Ignition Interlock Program. The Planning Ahead course must be completed (within 450 days), the vehicle is seized for 30 days, and there is a $1,000 fine.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-laws-016","chapter":9,"category":"law","question":"What applies on a third (and subsequent) IRS: FAIL occurrence?","options":["A 36-month suspension stage","A 12-month suspension stage","A 90-day suspension only","A lifetime suspension stage, with a possible application for reinstatement after 10 years"],"answer":3,"explanation":"After the 90 days with no driving, the suspension is for life, though the driver may participate in the Ignition Interlock Program during it. Drivers meeting the eligibility criteria may apply for reinstatement and removal of the interlock after 10 years, but an application does not guarantee removal. A 30-day seizure and a $2,000 fine also apply.","source":{"chapter":9,"section":"Driving laws","anchor":"#driving-laws","page":"112"}},{"id":"ch9-reg-001","chapter":9,"category":"law","question":"What can Albertans appeal through the Registrar Reconsideration Process?","options":["Non-impaired driving decisions, such as an Ignition Interlock Program Exemption or driver conduct decisions","Immediate Roadside Sanctions impaired driving penalties","Criminal Code sentences","Court judgements about collisions"],"answer":0,"explanation":"The process also covers administrative reviews such as safety fitness certificates, driver training schools and driving instructors, driver examiners, and vehicle inspection facilities and technicians.","source":{"chapter":9,"section":"Registrar Reconsideration Process","anchor":"#registrar-reconsideration-process","page":"112"}},{"id":"ch9-reg-002","chapter":9,"category":"law","question":"You want to challenge a provincial administrative penalty received under the IRS impaired driving program. Where do you apply?","options":["The Registrar Reconsideration Process","Any Alberta registry agent","SafeRoads Alberta","Your insurance provider"],"answer":2,"explanation":"SafeRoads Alberta conducts reviews for challenges to the provincial administrative penalties under the IRS program, applied for at www.saferoads.com. The Registrar Reconsideration Process covers non-impaired driving decisions only.","source":{"chapter":9,"section":"Registrar Reconsideration Process","anchor":"#registrar-reconsideration-process","page":"112"}},{"id":"ch9-resp-001","chapter":9,"category":"law","question":"When are demerit points recorded against your driving record?","options":["Whenever a police officer stops you","When you are convicted of an offence","Every time your licence is renewed","When you buy or sell a vehicle"],"answer":1,"explanation":"Demerit points are recorded when you are convicted of an offence, which happens when you pay the fine voluntarily, are found guilty in court, or are convicted (guilty) in absence after failing to appear.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-002","chapter":9,"category":"law","question":"How long do convictions and licence suspensions remain on your driving record and driver's abstract?","options":["2 years","5 years","10 years","25 years"],"answer":2,"explanation":"Convictions and times when your licence privileges have been suspended remain on your driving record for 10 years and will appear on your driver's abstract.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-003","chapter":9,"category":"law","question":"A fully licensed driver accumulates 15 or more demerit points within a two-year period. What happens?","options":["Their licence privileges are automatically suspended","Nothing, because the limit is 20 points","They receive only a warning letter","Their vehicle is impounded for 30 days"],"answer":0,"explanation":"At 15 or more points in two years, a fully licensed driver's licence privileges are automatically suspended. A driver with 8 to 14 points receives a letter about their demerit standing.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-004","chapter":9,"category":"law","question":"A fully licensed driver has 8 to 14 demerit points within a two-year period. What do they receive?","options":["An automatic six-month suspension","A letter notifying them of their demerit point standing","A criminal charge","A mandatory road test"],"answer":1,"explanation":"Eight to 14 points within two years results in a letter notifying you of your demerit point standing. An automatic suspension happens only at 15 or more points.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-005","chapter":9,"category":"law","question":"A GDL driver accumulates eight or more demerit points within a two-year period. What happens?","options":["A warning letter is issued only","Their demerit points are cleared from the record","Their licence privileges are automatically suspended","They must complete a defensive driving course"],"answer":2,"explanation":"GDL drivers are suspended at 8 or more points within two years, and a letter is sent at 4 to 7 points. Fully licensed drivers are not suspended until 15 or more points.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-006","chapter":9,"category":"law","question":"When a GDL driver's demerit suspension has been served, how many demerit points remain on the record at reinstatement?","options":["Seven","Three","Two","None"],"answer":1,"explanation":"GDL drivers are reinstated with three demerit points, which stay on the record for two years from the assessed date. Fully licensed drivers are reinstated with seven points remaining.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-007","chapter":9,"category":"law","question":"How many demerit points are assessed for failing to remain at the scene of a collision?","options":["2","4","7","5"],"answer":2,"explanation":"Failing to remain at the scene of a collision carries 7 demerit points, the highest value on the demerit schedule.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-008","chapter":9,"category":"law","question":"Which offence is worth six demerit points?","options":["Failing to stop for a school bus","Stunting","Improper turns","Failing to report a collision"],"answer":0,"explanation":"Six-point offences include careless driving, failing to stop for a school bus, racing, and speeding by at least 51 km/h. Stunting and failing to report a collision are 3 points; improper turns are 2 points.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-009","chapter":9,"category":"law","question":"Speeding 31 to 50 km/h over the limit carries how many demerit points?","options":["2","3","4","6"],"answer":2,"explanation":"Speeding by 31 to 50 km/h is a 4-point offence, like failing to yield the right-of-way to a pedestrian in a crosswalk or following too closely. Speeding by 16 to 30 km/h is 3 points, and by at least 51 km/h is 6 points.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-010","chapter":9,"category":"law","question":"How many demerit points are assessed for stunting?","options":["6","3","7","2"],"answer":1,"explanation":"Stunting is a 3-point offence, in the same group as improper passing, failing to report a collision, and speeding by 16 to 30 km/h.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"106"}},{"id":"ch9-resp-011","chapter":9,"category":"law","question":"Which GDL offence is worth two demerit points?","options":["Failing to stop for a peace officer","Racing","Failing to yield to a pedestrian in a crosswalk","Driving between midnight and 5 a.m. in the Class 7 learner stage"],"answer":3,"explanation":"Two-point GDL offences include curfew driving between midnight and 5 a.m. (Class 7 learner stage only), having more passengers than seat belts, and a supervisor who is not fully qualified.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"112"}},{"id":"ch9-resp-012","chapter":9,"category":"law","question":"A fully licensed driver receives a first demerit-point suspension. How long is it?","options":["Six months","Three months","One week","One month"],"answer":3,"explanation":"A first demerit suspension is automatic for one month; a second within one year is three months; a third within two years is six months, and a review with the Registrar of Motor Vehicles may be required.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"112"}},{"id":"ch9-resp-013","chapter":9,"category":"law","question":"Can you appeal a demerit point suspension?","options":["Yes, at any registry agent office","No, but you may request a review if you believe points were assigned in error","Yes, by paying an appeal fee to SafeRoads Alberta","No, and the points can never be reviewed"],"answer":1,"explanation":"You may not appeal a demerit suspension, but you can request in writing to Driver Fitness and Monitoring, under section 99 of the Traffic Safety Act, a review of points assigned in error. Convictions can only be removed by an appeal through the courts.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"112"}},{"id":"ch9-resp-014","chapter":9,"category":"law","question":"When are the demerit points for a conviction removed from your driver's record?","options":["One year after the conviction","When you complete any approved driving course","Once the fine is paid a second time","Two years after the date of the conviction"],"answer":3,"explanation":"When two years have passed from the date of a conviction, the demerit points assessed for that conviction are removed from your driver's record.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"112"}},{"id":"ch9-resp-015","chapter":9,"category":"law","question":"What credit does a Government-approved defensive driving course give if completed before accumulating 15 or more points?","options":["A one-point credit for life","Removal of all previous convictions","A three-point credit for a two-year period","A six-point credit for five years"],"answer":2,"explanation":"A Government-approved defensive driving course completed prior to accumulating 15 or more points applies a three-point credit to your record for a two-year period.","source":{"chapter":9,"section":"Driving responsibly","anchor":"#driving-responsibly","page":"112"}},{"id":"ch9-safe-001","chapter":9,"category":"law","question":"What is SafeRoads Alberta responsible for?","options":["Conducting reviews of provincial IRS penalties and reviews of vehicle seizures","Laying Criminal Code charges","Setting speed limits on Alberta highways","Conducting road tests for new drivers"],"answer":0,"explanation":"SafeRoads Alberta is the administrative adjudication branch of Transportation and Economic Corridors that reviews provincial administrative penalties received by impaired drivers and vehicle seizures; all matters are dealt with within 30 days.","source":{"chapter":9,"section":"SafeRoads Alberta","anchor":"#saferoads-alberta","page":"112"}},{"id":"ch9-safe-002","chapter":9,"category":"law","question":"When can you ask SafeRoads Alberta to review a vehicle seizure?","options":["When any vehicle registered to you is impounded for any reason","When the vehicle was stolen or taken without consent, or is owned by a rental car agency","When you agree to pay double the fees","Never, because vehicle seizures cannot be reviewed"],"answer":1,"explanation":"Vehicles seized under section 94 of the Traffic Safety Act after being stolen or taken without consent, or owned by a rental car agency, can be reviewed. Applying does not guarantee return, review fees are non-refundable, and registered owners are responsible for all seizure costs.","source":{"chapter":9,"section":"SafeRoads Alberta","anchor":"#saferoads-alberta","page":"112"}},{"id":"ch9-sus-001","chapter":9,"category":"law","question":"What can happen if you operate a motor vehicle while your licence is suspended or disqualified?","options":["Nothing, if the vehicle is not registered to you","Only a small parking fine","A jail term, a fine or both, plus an additional suspension","Just a reminder letter from the police"],"answer":2,"explanation":"You can face time in jail, fines, or both, and while serving a suspension you will face another suspension. Driving while suspended is a serious offence.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}},{"id":"ch9-sus-002","chapter":9,"category":"law","question":"Your vehicle is seized because you drove while suspended. How long is it impounded, and who pays the fees?","options":["7 days, with fees paid by the police","30 days, regardless of who owns the vehicle; the registered owner pays all towing and impound fees","15 days, with fees covered by insurance","60 days, with fees paid by the government"],"answer":1,"explanation":"The vehicle is seized and impounded for 30 days regardless of who is the registered owner, and all towing charges and impound fees are charged to the registered owner.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}},{"id":"ch9-sus-003","chapter":9,"category":"law","question":"What must you do with your driver's licence when a suspension begins?","options":["Keep it in your wallet to show police","Surrender it to any Alberta registry agent office on or before the effective date","Mail it to SafeRoads Alberta","Give it to a family member for safekeeping"],"answer":1,"explanation":"You are required by law to give up your licence on or before the date the suspension begins. It is illegal to be in possession of your driver's licence while you are serving a suspension.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}},{"id":"ch9-sus-004","chapter":9,"category":"law","question":"Where will your Notice of Suspension letter be sent?","options":["To your employer","To your family doctor","To the last recorded address on your driver's licence record","To your insurance company"],"answer":2,"explanation":"Driver Fitness and Monitoring sends the notice via registered letter to the last recorded address, so it is your responsibility to notify an Alberta registry agent office anytime you change your mailing address.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}},{"id":"ch9-sus-005","chapter":9,"category":"law","question":"Which conditions may be required to reinstate your privileges after an alcohol, drug, or alcohol and drug related offence?","options":["A one-day or weekend driver program and participation in Alberta's Ignition Interlock Program","Only payment of the original fine","A new Class 7 learner application","Written permission from your employer"],"answer":0,"explanation":"You must also pay the reinstatement fee and take a road test, and provide proof at a registry agent office that you met the requirements. If your licence expires during the suspension, it cannot be renewed until all reinstatement conditions are met.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}},{"id":"ch9-sus-006","chapter":9,"category":"law","question":"What does an ignition interlock device do?","options":["Tracks your vehicle's location only","Limits your vehicle's maximum speed","Locks your phone while you drive","Measures alcohol in the driver's breath and locks the ignition above the set threshold"],"answer":3,"explanation":"The interlock device measures the alcohol concentration level of the driver's breath and locks the vehicle ignition if a breath alcohol reading is above the specified threshold level.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}},{"id":"ch9-sus-007","chapter":9,"category":"law","question":"Why does Alberta offer the Ignition Interlock Program?","options":["To let suspended drivers drive anywhere with no conditions","So drivers can stay mobile for treatment, work and family responsibilities while driving is monitored","To punish convicted drivers with higher insurance premiums","To replace a criminal charge without any conditions"],"answer":1,"explanation":"The program helps drivers separate the high-risk behaviours of impaired driving, prevents recidivism, and lets drivers remain mobile for support and treatment, employment and family while public safety is monitored. The Mandatory Interlock stream is required for drivers convicted under the Criminal Code.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}},{"id":"ch9-sus-008","chapter":9,"category":"law","question":"Which of the following can be grounds for a provincial suspension?","options":["A poor driving record, failure to pay a legal judgement, medical reasons, or failure to comply with a Notice to Report","Only criminal convictions","Only exceeding 15 demerit points","Parking tickets that are paid on time"],"answer":0,"explanation":"Provincial suspensions may be imposed for reasons such as a poor driving record, failure to pay a legal judgement, medical reasons, or failure to comply with a Notice to Report.","source":{"chapter":9,"section":"Driver’s licence suspensions and disqualifications","anchor":"#drivers-licence-suspensions-and-disqualifications","page":"112"}}];
